import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration
#if canImport(Darwin)
import Darwin
#elseif canImport(Glibc)
import Glibc
#endif

public struct AnyDestinationMigrationMapping: Codable, Sendable {
    public let sourceKey: String
    public let sourceObjectID: String
    public let kind: String
    public let intentID: String
    public let objectID: String
    public let recordIDs: [String]
    public let fileID: String?
    public let fingerprint: String
    public let signedChangeIDs: [String]
    public let currentReceiptSHA256: String
}

/// This reports individually reconciled native operations. Full-Space semantic
/// acceptance additionally compares the source bundle with destination content
/// and file bytes; it is never inferred from a count of these receipts.
public struct AnyDestinationMigrationProgress: Sendable {
    public let binding: AnyPreparedMigrationPlanBinding
    public let source: AnyDestinationSourceBinding
    public let mappings: [AnyDestinationMigrationMapping]
    public let totalItems: Int
    public let allItemsReconciled: Bool
    // Retain the original typed immutable intents so content verification can
    // re-read current native receipts without reconstructing a property revision.
    let verificationIntents: [AnyDestinationNativeIntent]
}


/// Historical checkpoint identities read from the existing private journal.
/// These routing facts do not assert current native content or authorization.
public struct AnyDestinationSavedCheckpoint: Sendable {
    public let plan: AnyDestinationMigrationPlan
    public let mappings: [AnyDestinationMigrationMapping]
    public let checkpointSHA256: String
    public var nativeOperationsPerformed: Int { 0 }
    public var provesCurrentNativeState: Bool { false }
    let intents: [AnyDestinationNativeIntent]

    static func fingerprint(plan: AnyDestinationMigrationPlan,
                            mappings: [AnyDestinationMigrationMapping]) throws -> String {
        struct Material: Encodable {
            let contract: String
            let planSHA256: String
            let mappings: [AnyDestinationMigrationMapping]
        }
        let bytes = try AnyDestinationMigrationJournal.encoded(Material(
            contract: "pinkha-destination-saved-checkpoint-v1",
            planSHA256: plan.binding.planSHA256, mappings: mappings))
        guard bytes.count <= 32 * 1024 * 1024 else { throw AnyEngineError.readLimit }
        return AnyContentDigest.sha256(bytes)
    }
}

public actor AnyDestinationMigrationExecutor {
    private typealias Factory = @Sendable (AnyDestinationMigrationPlan, @escaping AnyDestinationAuthorization) async throws -> any AnyDestinationNativeDriving
    private let journalDirectory: URL
    private let factory: Factory
    private let checkpointHook: @Sendable (Int) async throws -> Void
    private var executing = false

    /// The journal parent must be a private application-owned existing folder.
    /// `verifySource` below is supplied by the native captured-source adapter;
    /// it must recheck that exact capture's current authorization/checkpoint.
    public init(client: AnyHTTPClient, journalDirectory: URL) {
        self.journalDirectory = journalDirectory
        factory = { plan, authorize in
            try await AnyDestinationNativeClients.open(client: client, plan: plan, authorize: authorize)
        }
        checkpointHook = { _ in }
    }

    /// Internal crash-boundary injection. Production always uses native HTTP.
    init(journalDirectory: URL, driver: any AnyDestinationNativeDriving,
         checkpointHook: @escaping @Sendable (Int) async throws -> Void = { _ in }) {
        self.journalDirectory = journalDirectory; factory = { _, _ in driver }
        self.checkpointHook = checkpointHook
    }

    public func execute(
        plan: AnyDestinationMigrationPlan,
        payloads: @escaping @Sendable (String) async throws -> URL,
        verifySource: @escaping @Sendable (AnyDestinationSourceBinding) async throws -> Void,
        authorize: @escaping @Sendable () async throws -> Void
    ) async throws -> AnyDestinationMigrationProgress {
        guard !executing else { throw AnyDestinationMigrationError.alreadyExecuting }
        executing = true; defer { executing = false }
        try plan.requireExecutable()
        let admit: AnyDestinationAuthorization = {
            try Task.checkCancellation(); try await verifySource(plan.source)
            try await authorize(); try Task.checkCancellation()
        }
        try await admit()
        // Both the OS lock and in-actor guard remain held across suspension.
        // The OS closes the lock on process death; no timestamp lease expires
        // while an older process could still mutate the destination.
        let prerequisiteDriver: (any AnyDestinationNativeDriving)?
        if let namespace = plan.importedPropertyNamespace {
            let candidate = try await factory(plan, admit)
            // A missing, obsolete or foreign original namespace refuses before
            // the supplemental journal is created or any new intent prepared.
            try await namespace.observe(using: candidate, authorize: admit)
            prerequisiteDriver = candidate
        } else { prerequisiteDriver = nil }
        let journal = try AnyDestinationMigrationJournal(parent: journalDirectory, plan: plan)
        let driver: any AnyDestinationNativeDriving
        if let prerequisiteDriver { driver = prerequisiteDriver }
        else { driver = try await factory(plan, admit) }
        let operationAdmit: AnyDestinationAuthorization
        if let namespace = plan.importedPropertyNamespace {
            operationAdmit = {
                try await namespace.observe(using: driver, authorize: admit)
            }
        } else { operationAdmit = admit }
        var mappings: [Data: AnyDestinationMigrationMapping] = [:]
        var ordered: [AnyDestinationMigrationMapping] = []
        var entries: [AnyDestinationJournalEntry] = []
        var propertyGroups = Set<Data>()
        var creationProperties: [Data: AnyJSON] = [:]
        for (index, item) in plan.items.enumerated() {
            try await operationAdmit()
            let resolved = try item.operation.resolved(destinationSpaceID: plan.binding.workspace.spaceID) {
                try Self.resolve($0, mappings: mappings, destinationSpaceID: plan.binding.workspace.spaceID)
            }
            let resolvedBytes = try AnyDestinationMigrationJournal.encoded(resolved)
            if case .propertyUpdate(let object, let owner, let patch) = resolved {
                let group = try AnyDestinationMigrationJournal.encoded([object, owner])
                guard propertyGroups.insert(group).inserted else {
                    throw AnyDestinationMigrationError.invalidPlan("aliased property object/owner group")
                }
                try Self.requireDisjointCreationFields(object: object, owner: owner, patch: patch,
                                                       properties: creationProperties)
            }
            var entry: AnyDestinationJournalEntry
            if let previous = try journal.load(index: index) {
                guard previous.resolvedOperation == resolvedBytes else { throw AnyDestinationMigrationError.changedPlan }
                entry = previous
            } else {
                let sequence: Int64?
                if case .propertyUpdate(.native(let object), _, _) = resolved {
                    sequence = try await driver.applySequence(objectID: object, authorize: operationAdmit)
                } else { sequence = nil }
                let content: Data?
                if case .file(_, _, _, let size, let digest) = resolved, size < 4096 {
                    let url = try await payloads(item.sourceKey)
                    content = try Self.inlinePayload(url, size: size, digest: digest, sourceKey: item.sourceKey)
                } else { content = nil }
                let immutableSchema: AnyPreparedImmutableRecordSchema?
                if case .immutableRecord(_, .native(let owner), let key, _) = resolved {
                    immutableSchema = try await driver.immutableSchema(ownerTypeID: owner,
                        dataset: AnyPreparedImmutableRecordIntent.ownedDataset(ownerTypeID: owner, key: key), authorize: operationAdmit)
                } else { immutableSchema = nil }
                let intent = try AnyDestinationNativeIntent.make(resolved, binding: plan.binding,
                    sourceKey: item.sourceKey, sequence: sequence, inlineContent: content, immutableSchema: immutableSchema)
                entry = .init(index: index, sourceKey: item.sourceKey,
                    itemSHA256: AnyContentDigest.sha256(try AnyDestinationMigrationJournal.encoded(item)),
                    resolvedOperation: resolvedBytes, expectedApplySequence: sequence, inlineContent: content,
                    intentID: intent.identity.id, specBytes: intent.identity.spec, specSHA256: intent.identity.sha,
                    immutableRecordSchema: immutableSchema)
                // This sync completes BEFORE prepare/sign/append. A later call
                // must not refresh a property sequence or resolve a new body.
                try journal.save(entry)
                try await checkpointHook(index)
            }
            let intent = try Self.intent(entry, plan: plan)
            if let previous = entry.receipts.last { try Self.requireNonterminal(previous, sourceKey: item.sourceKey) }
            let prepared: AnyJSON
            do {
                prepared = try await driver.status(intent, authorize: operationAdmit)
            } catch AnyEngineError.http(let status, _) where status == 404 && entry.receipts.isEmpty {
                // Only a native 404 with no prior native receipt permits initial
                // preparation. Network/auth/corruption errors are never absence.
                let payload: URL?
                if case .file = intent { payload = try await payloads(item.sourceKey) } else { payload = nil }
                prepared = try await driver.prepare(intent, payload: payload, authorize: operationAdmit)
            }
            try Self.record(prepared, in: &entry, intent: intent, journal: journal)
            try Self.requireNonterminal(prepared, sourceKey: item.sourceKey)
            let completed: AnyJSON
            if Self.isComplete(prepared) {
                completed = prepared
            } else {
                // A lost reply escapes immediately. Resuming reconciles this
                // same intent; there is no uncertain-write loop in this call.
                completed = try await driver.commit(intent, receipt: prepared, authorize: operationAdmit)
                try Self.record(completed, in: &entry, intent: intent, journal: journal)
                try Self.requireNonterminal(completed, sourceKey: item.sourceKey)
            }
            guard Self.isComplete(completed) else { throw AnyPreparedMigrationError.incompleteCommit }
            let mapping = try Self.mapping(item, entry: entry)
            mappings[Data(item.sourceKey.utf8)] = mapping; ordered.append(mapping); entries.append(entry)
            if case .object(_, _, .literal(let values)) = resolved {
                creationProperties[Data(mapping.objectID.utf8)] = values
            }
        }
        // Recheck every original identity after all later phases, including
        // property links and file records, and after reopening an old journal.
        // This is a sequence of current native reads, not an atomic Space view.
        for index in entries.indices {
            var entry = entries[index]
            let intent = try Self.intent(entry, plan: plan)
            let current = try await driver.status(intent, authorize: operationAdmit)
            try Self.record(current, in: &entry, intent: intent, journal: journal)
            try Self.requireNonterminal(current, sourceKey: entry.sourceKey)
            guard Self.isComplete(current) else { throw AnyPreparedMigrationError.incompleteCommit }
            ordered[index] = try Self.mapping(plan.items[index], entry: entry)
            entries[index] = entry
        }
        try await operationAdmit()
        return .init(binding: plan.binding, source: plan.source, mappings: ordered,
                     totalItems: plan.items.count, allItemsReconciled: true,
                     verificationIntents: try entries.map { try Self.intent($0, plan: plan) })
    }


    /// Reads an existing completed journal under its original shared OS lock.
    /// It cannot open a native driver, prepare/commit, repair a checkpoint or
    /// create missing files. Current readers still revalidate native authority.
    public nonisolated static func readCompletedCheckpoint(
        journalDirectory: URL, binding: AnyPreparedMigrationPlanBinding
    ) throws -> AnyDestinationSavedCheckpoint {
        try Task.checkCancellation()
        let journal = try AnyDestinationMigrationJournal(readOnlyParent: journalDirectory,
                                                          expectedBinding: binding)
        let plan = journal.storedPlan
        try plan.requireExecutable()
        var byKey: [Data: AnyDestinationMigrationMapping] = [:]
        var mappings: [AnyDestinationMigrationMapping] = []
        var intents: [AnyDestinationNativeIntent] = []
        var propertyGroups = Set<Data>()
        var creationProperties: [Data: AnyJSON] = [:]
        for (index, item) in plan.items.enumerated() {
            try Task.checkCancellation()
            let resolved = try item.operation.resolved(destinationSpaceID: binding.workspace.spaceID) {
                try Self.resolve($0, mappings: byKey, destinationSpaceID: binding.workspace.spaceID)
            }
            guard let entry = try journal.load(index: index),
                  entry.resolvedOperation == (try AnyDestinationMigrationJournal.encoded(resolved)),
                  !entry.receipts.isEmpty else { throw AnyDestinationMigrationError.journalCorrupt }
            if case .propertyUpdate(let object, let owner, let patch) = resolved {
                let group = try AnyDestinationMigrationJournal.encoded([object, owner])
                guard propertyGroups.insert(group).inserted else {
                    throw AnyDestinationMigrationError.invalidPlan("aliased property object/owner group")
                }
                try Self.requireDisjointCreationFields(object: object, owner: owner, patch: patch,
                                                       properties: creationProperties)
            }
            let intent = try Self.intent(entry, plan: plan)
            for pair in zip(entry.receipts, entry.receipts.dropFirst()) {
                try Self.compare(pair.0, pair.1, sourceKey: item.sourceKey)
            }
            let mapping = try Self.mapping(item, entry: entry)
            guard byKey.updateValue(mapping, forKey: Data(item.sourceKey.utf8)) == nil else {
                throw AnyDestinationMigrationError.journalCorrupt
            }
            mappings.append(mapping); intents.append(intent)
            if case .object(_, _, .literal(let values)) = resolved {
                creationProperties[Data(mapping.objectID.utf8)] = values
            }
        }
        let checkpointSHA256 = try AnyDestinationSavedCheckpoint.fingerprint(plan: plan, mappings: mappings)
        try journal.finishReadOnly()
        try Task.checkCancellation()
        return .init(plan: plan, mappings: mappings,
            checkpointSHA256: checkpointSHA256, intents: intents)
    }

    private static func intent(_ entry: AnyDestinationJournalEntry,
                               plan: AnyDestinationMigrationPlan) throws -> AnyDestinationNativeIntent {
        let operation = try JSONDecoder().decode(AnyDestinationMigrationOperation.self, from: entry.resolvedOperation)
        let value = try AnyDestinationNativeIntent.make(operation, binding: plan.binding, sourceKey: entry.sourceKey,
            sequence: entry.expectedApplySequence, inlineContent: entry.inlineContent, immutableSchema: entry.immutableRecordSchema)
        guard value.identity.id == entry.intentID, value.identity.spec == entry.specBytes,
              value.identity.sha == entry.specSHA256 else { throw AnyDestinationMigrationError.journalCorrupt }
        for receipt in entry.receipts { try value.validateReceipt(receipt) }
        return value
    }

    private static func resolve(_ reference: AnyDestinationReference,
                                mappings: [Data: AnyDestinationMigrationMapping], destinationSpaceID: String) throws -> String {
        switch reference {
        case .native(let value): return value
        case .mapped(let key, let slot, let encoding):
            guard let mapping = mappings[Data(key.utf8)] else { throw AnyDestinationMigrationError.unknownReference(key) }
            let value: String
            switch slot {
            case .objectID: value = mapping.objectID
            case .record(let index):
                guard mapping.recordIDs.indices.contains(index) else { throw AnyDestinationMigrationError.unknownReference(key) }
                value = mapping.recordIDs[index]
            case .fileID:
                guard let id = mapping.fileID else { throw AnyDestinationMigrationError.unknownReference(key) }; value = id
            }
            switch encoding {
            case .rawID: return value
            case .anyURI: return "any://" + value
            case .fileURI: return try AnyNativeFileReference(spaceID: destinationSpaceID, fileID: value).uri
            }
        }
    }

    private static func record(_ receipt: AnyJSON, in entry: inout AnyDestinationJournalEntry,
                               intent: AnyDestinationNativeIntent, journal: AnyDestinationMigrationJournal) throws {
        try intent.validateReceipt(receipt)
        if let previous = entry.receipts.last { try compare(previous, receipt, sourceKey: entry.sourceKey) }
        let bytes = try AnyDestinationMigrationJournal.encoded(receipt)
        if let previous = entry.receipts.last, try AnyDestinationMigrationJournal.encoded(previous) == bytes { return }
        guard entry.receipts.count < 32 else { throw AnyDestinationMigrationError.journalCorrupt }
        entry.receipts.append(receipt); try journal.save(entry)
    }

    private static func isComplete(_ value: AnyJSON) -> Bool {
        value["stage"]?.string == "complete" && value["outcome"]?.string == "committed" &&
        (value["kind"]?.string != "file" || value["localFileComplete"]?.bool == true)
    }
    private static func requireNonterminal(_ value: AnyJSON, sourceKey: String) throws {
        guard let outcome = value["outcome"]?.string else { throw AnyDestinationMigrationError.journalCorrupt }
        guard outcome == "prepared" || outcome == "committed" else {
            throw AnyDestinationMigrationError.nativeTerminal(sourceKey, outcome)
        }
    }

    private static func compare(_ old: AnyJSON, _ new: AnyJSON, sourceKey: String) throws {
        func same(_ key: String) -> Bool {
            guard let a = old[key]?.string else { return true }
            return new[key]?.string.map { Data($0.utf8) } == Data(a.utf8)
        }
        guard ["intentId", "fingerprint", "objectId", "fileId", "rootCid", "ownerObjectId", "specSHA256"].allSatisfy(same) else {
            throw AnyDestinationMigrationError.changedIdentity(sourceKey)
        }
        if let previous = old["recordIds"]?.array, !previous.isEmpty {
            guard let current = new["recordIds"]?.array,
                  try AnyDestinationMigrationJournal.encoded(previous) == AnyDestinationMigrationJournal.encoded(current) else {
                throw AnyDestinationMigrationError.changedIdentity(sourceKey)
            }
        }
        let a = old["stage"]?.string ?? "", b = new["stage"]?.string ?? ""
        let rootStages: Set<String> = ["root-prepared", "root-committed", "definition-root-prepared", "definition-root-committed"]
        let bootstrapStages: Set<String> = ["bootstrap-prepared", "definition-bootstrap-prepared", "complete"]
        let permittedNewBootstrap = rootStages.contains(a) && bootstrapStages.contains(b)
        guard permittedNewBootstrap || same("changeId") else { throw AnyDestinationMigrationError.changedIdentity(sourceKey) }
        let order: [String: Int] = ["root-prepared": 0, "root-committed": 1, "bootstrap-prepared": 2,
            "block-prepared": 0, "definition-root-prepared": 0, "definition-root-committed": 1,
            "definition-bootstrap-prepared": 2, "definition-property-prepared": 0, "definition-part-prepared": 0,
            "properties-prepared": 0, "immutable-record-prepared": 0, "file-prepared": 0, "file-root-committed": 1, "file-row-committed": 2, "complete": 3]
        // Preserve a terminal native outcome even when deletion projects it to
        // a pre-commit stage. It still halts immediately and cannot be revived.
        if new["outcome"]?.string == "prepared" || new["outcome"]?.string == "committed" {
            guard let oldOrder = order[a], let newOrder = order[b], newOrder >= oldOrder else {
                throw AnyDestinationMigrationError.changedIdentity(sourceKey)
            }
        }
        if let outcome = old["outcome"]?.string, outcome != "prepared" && outcome != "committed",
           new["outcome"]?.string != outcome { throw AnyDestinationMigrationError.changedIdentity(sourceKey) }
    }

    private static func mapping(_ item: AnyDestinationMigrationItem, entry: AnyDestinationJournalEntry) throws -> AnyDestinationMigrationMapping {
        guard let value = entry.receipts.last, isComplete(value),
              let id = value["objectId"]?.string, let fingerprint = value["fingerprint"]?.string,
              let records = value["recordIds"]?.array,
              records.count == item.expectedRecordCount else { throw AnyDestinationMigrationError.changedIdentity(item.sourceKey) }
        let recordIDs = try records.map { value -> String in
            guard let id = value.string else { throw AnyDestinationMigrationError.journalCorrupt }; return id
        }
        var changes: [String] = []
        for receipt in entry.receipts {
            if let change = receipt["changeId"]?.string, !changes.contains(where: { Data($0.utf8) == Data(change.utf8) }) {
                changes.append(change)
            }
        }
        return .init(sourceKey: item.sourceKey, sourceObjectID: item.sourceObjectID, kind: item.operation.kind,
            intentID: entry.intentID, objectID: id, recordIDs: recordIDs, fileID: value["fileId"]?.string,
            fingerprint: fingerprint, signedChangeIDs: changes,
            currentReceiptSHA256: AnyContentDigest.sha256(try AnyDestinationMigrationJournal.encoded(value)))
    }

    private static func requireDisjointCreationFields(object: AnyDestinationReference, owner: AnyDestinationReference,
                                                      patch: AnyDestinationValue, properties: [Data: AnyJSON]) throws {
        guard case .native(let objectID) = object, case .native(let ownerID) = owner,
              case .literal(let patchValue) = patch, let patch = patchValue.object else {
            throw AnyDestinationMigrationError.invalidPlan("resolved property group")
        }
        guard let initial = properties[Data(objectID.utf8)] else {
            throw AnyDestinationMigrationError.invalidPlan("property target was not created by this plan")
        }
        if let original = initial[ownerID]?.object, !Set(original.keys).isDisjoint(with: Set(patch.keys)) {
            throw AnyDestinationMigrationError.invalidPlan("property update replaces an immutable creation field")
        }
    }

    private static func inlinePayload(_ url: URL, size: Int64, digest: String, sourceKey: String) throws -> Data {
        guard url.isFileURL, (0...4095).contains(size) else { throw AnyDestinationMigrationError.payloadMismatch(sourceKey) }
        let fd = open(url.path, O_RDONLY | O_NOFOLLOW | O_CLOEXEC)
        guard fd >= 0 else { throw AnyDestinationMigrationError.payloadMismatch(sourceKey) }
        let handle = FileHandle(fileDescriptor: fd, closeOnDealloc: true); defer { try? handle.close() }
        var info = stat()
        guard fstat(fd, &info) == 0, info.st_mode & mode_t(S_IFMT) == mode_t(S_IFREG), info.st_size == size else {
            throw AnyDestinationMigrationError.payloadMismatch(sourceKey)
        }
        var data = Data()
        while data.count <= 4095 {
            let next = try handle.read(upToCount: 4096 - data.count) ?? Data()
            if next.isEmpty { break }; data.append(next)
        }
        guard Int64(data.count) == size, AnyContentDigest.sha256(data) == digest,
              fstat(fd, &info) == 0, info.st_size == size else { throw AnyDestinationMigrationError.payloadMismatch(sourceKey) }
        return data
    }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration
import PinkhaKit

public enum AnyDestinationMigrationError: Error, Equatable, Sendable {
    case invalidPlan(String)
    case incompleteCoverage(String)
    case unknownReference(String)
    case changedPlan
    case changedIdentity(String)
    case changedSource
    case journalUnavailable
    case journalCorrupt
    case alreadyExecuting
    case nativeTerminal(String, String)
    case unsupportedCapability(String)
    case payloadMismatch(String)
}

/// The outer native capture owns these identities. Per-object JSON alone
/// cannot establish an account, source checkpoint or complete source census.
public struct AnyDestinationSourceBinding: Codable, Equatable, Sendable {
    public let accountID: String
    public let spaceID: String
    public let witnessSHA256: String
    public let captureManifestSHA256: String
    public let semanticPlanSHA256: String
    public let sourceObjectIDs: [String]
    /// Exact original whole-source manifest, required when a source definition
    /// is represented by canonical or embedded coverage. Omitted on legacy
    /// plans, preserving their canonical bytes and original journal identity.
    public let definitionManifestBytes: Data?
    let definitionMembers: [Data: AnyDestinationDefinitionMember]

    public init(accountID: String, spaceID: String, witnessSHA256: String,
                captureManifestSHA256: String, semanticPlanSHA256: String,
                sourceObjectIDs: [String], definitionManifestBytes: Data? = nil) throws {
        guard AnyDestinationPlanChecks.identity(accountID), AnyDestinationPlanChecks.identity(spaceID),
              [witnessSHA256, captureManifestSHA256, semanticPlanSHA256].allSatisfy(AnyDestinationPlanChecks.digest),
              !sourceObjectIDs.isEmpty, sourceObjectIDs.count <= AnyDestinationMigrationPlan.maximumItems,
              sourceObjectIDs.allSatisfy(AnyDestinationPlanChecks.identity),
              Set(sourceObjectIDs.map { Data($0.utf8) }).count == sourceObjectIDs.count else {
            throw AnyDestinationMigrationError.invalidPlan("source binding")
        }
        self.accountID = accountID; self.spaceID = spaceID; self.witnessSHA256 = witnessSHA256
        self.captureManifestSHA256 = captureManifestSHA256; self.semanticPlanSHA256 = semanticPlanSHA256
        self.sourceObjectIDs = sourceObjectIDs
        self.definitionManifestBytes = definitionManifestBytes
        if let definitionManifestBytes {
            definitionMembers = try AnyDestinationDefinitionChecks.members(manifest: definitionManifestBytes,
                accountID: accountID, spaceID: spaceID, witnessSHA256: witnessSHA256,
                manifestSHA256: captureManifestSHA256)
        } else { definitionMembers = [:] }
    }

    /// Complete native-source binding. It includes every native head, not
    /// just trees for which a current object snapshot could be decoded.
    public init(bundle: AnyHeartNativeSpaceBundle, semanticPlanSHA256: String) throws {
        guard let census = bundle.nativeStoreContext?.headCensus else {
            throw AnyDestinationMigrationError.invalidPlan("complete native source head census")
        }
        try self.init(bundle: bundle, semanticPlanSHA256: semanticPlanSHA256,
                      sourceObjectIDs: census.sourceHeadIDs)
    }

    /// Explicit component scope. The current native capture coordinator refuses
    /// this binding unless its identities equal the complete native head census.
    public init(bundle: AnyHeartNativeSpaceBundle, semanticPlanSHA256: String, sourceObjectIDs: [String]) throws {
        try self.init(accountID: bundle.sourceAccountID, spaceID: bundle.sourceSpaceID,
            witnessSHA256: bundle.sourceWitnessSHA256, captureManifestSHA256: bundle.manifestSHA256,
            semanticPlanSHA256: semanticPlanSHA256, sourceObjectIDs: sourceObjectIDs,
            definitionManifestBytes: bundle.manifestBytes)
    }

    private enum CodingKeys: String, CodingKey {
        case accountID, spaceID, witnessSHA256, captureManifestSHA256, semanticPlanSHA256, sourceObjectIDs, definitionManifestBytes
    }
    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        try self.init(accountID: c.decode(String.self, forKey: .accountID),
                      spaceID: c.decode(String.self, forKey: .spaceID),
                      witnessSHA256: c.decode(String.self, forKey: .witnessSHA256),
                      captureManifestSHA256: c.decode(String.self, forKey: .captureManifestSHA256),
                      semanticPlanSHA256: c.decode(String.self, forKey: .semanticPlanSHA256),
                      sourceObjectIDs: c.decode([String].self, forKey: .sourceObjectIDs),
                      definitionManifestBytes: c.decodeIfPresent(Data.self, forKey: .definitionManifestBytes))
    }
}

/// A reference is explicit, including references used as property-map keys.
/// No text scanning, title matching, normalized identity lookup or replacement
/// of a source ID embedded in an arbitrary string is performed by the executor.
public enum AnyDestinationReference: Codable, Equatable, Sendable {
    public enum Slot: Codable, Equatable, Sendable {
        case objectID
        case record(index: Int)
        case fileID
    }
    public enum Encoding: String, Codable, Sendable {
        case rawID, anyURI
        /// Resolved with the validated destination Space, after native file
        /// commitment. Never interpreted as an ordinary object reference.
        case fileURI
    }
    case native(String)
    case mapped(sourceKey: String, slot: Slot, encoding: Encoding)
}

public struct AnyDestinationField: Codable, Equatable, Sendable {
    public let key: AnyDestinationReference
    public let value: AnyDestinationValue
    public init(key: AnyDestinationReference, value: AnyDestinationValue) {
        self.key = key; self.value = value
    }
}

public indirect enum AnyDestinationValue: Codable, Equatable, Sendable {
    /// Literal JSON contains no identity substitution. The semantic mapper must
    /// represent every identity it intends to translate with `reference`.
    case literal(AnyJSON)
    case reference(AnyDestinationReference)
    case array([AnyDestinationValue])
    case object([AnyDestinationField])
}

public struct AnyDestinationRootDefinition: Codable, Equatable, Sendable {
    public let xKey: String
    public let name: String
    public let description: String
    public let iconCID: String
    public let layout: AnyDestinationValue?
    public let hidden: Bool
    public let meta: AnyDestinationValue
    public init(xKey: String, name: String, description: String = "", iconCID: String = "",
                layout: AnyDestinationValue? = nil, hidden: Bool = false,
                meta: AnyDestinationValue = .literal(.object([:]))) {
        self.xKey = xKey; self.name = name; self.description = description; self.iconCID = iconCID
        self.layout = layout; self.hidden = hidden; self.meta = meta
    }
}

/// Draft values are inert until the validated enclosing plan is constructed.
/// The order is definitions, objects, blocks, files, then property updates.
/// Every ordinary object identity therefore exists before a reference cycle is
/// committed, without changing its immutable creation specification.
public enum AnyDestinationMigrationOperation: Codable, Equatable, Sendable {
    case typeDefinition(AnyDestinationRootDefinition)
    case collectionDefinition(AnyDestinationRootDefinition)
    case propertyDefinition(owner: AnyDestinationReference, kind: String, name: String,
                            xKey: String, description: String, scope: String,
                            xFormat: AnyDestinationValue?, index: String?)
    case partDefinition(owner: AnyDestinationReference, draft: AnyDestinationValue)
    case object(type: AnyDestinationReference, collections: [AnyDestinationReference],
                initialProperties: AnyDestinationValue)
    case editorBlock(owner: AnyDestinationReference, dataset: String, type: String, text: String,
                     style: AnyDestinationValue, parent: AnyDestinationReference?, position: String)
    /// Source-scoped semantic markers are resolved only after the native owner
    /// has been allocated. Old ordinary-block encoding remains unchanged.
    case anchoredEditorBlock(owner: AnyDestinationReference, dataset: String, type: String,
                             text: AnyDestinationAnchoredText, style: AnyDestinationValue,
                             parent: AnyDestinationReference?, position: String)
    /// The locator and bytes are supplied separately. The immutable plan binds
    /// byte count and plaintext digest. All variants require separate items.
    case file(owner: AnyDestinationReference, name: String, mime: String,
              size: Int64, contentSHA256: String)
    /// One SET group per object/owner. The original revision is read and
    /// durably recorded by the executor before the first preparation request.
    case propertyUpdate(object: AnyDestinationReference, owner: AnyDestinationReference,
                        patch: AnyDestinationValue)

    /// One source fact row in a native write-once/no-delete dataset. The native
    /// schema is read once after its owned part exists and journaled before prepare.
    case immutableRecord(object: AnyDestinationReference, ownerType: AnyDestinationReference,
                         datasetKey: String, values: AnyDestinationValue)

    var phase: Int {
        switch self {
        case .typeDefinition, .collectionDefinition, .propertyDefinition, .partDefinition: 0
        case .object: 1
        case .editorBlock, .anchoredEditorBlock: 2
        case .file: 3
        case .propertyUpdate: 4
        case .immutableRecord: 5
        }
    }
    var kind: String {
        switch self {
        case .typeDefinition: "typeDefinition"
        case .collectionDefinition: "collectionDefinition"
        case .propertyDefinition: "propertyDefinition"
        case .partDefinition: "partDefinition"
        case .object: "object"
        case .editorBlock, .anchoredEditorBlock: "editorBlock"
        case .file(_, _, _, let size, _): size < 4096 ? "inlineFile" : "file"
        case .propertyUpdate: "propertyUpdate"
        case .immutableRecord: "immutableRecord"
        }
    }
}

public struct AnyDestinationMigrationItem: Codable, Equatable, Sendable {
    public let sourceKey: String
    public let sourceObjectID: String
    public let expectedRecordCount: Int
    public let operation: AnyDestinationMigrationOperation
    public init(sourceKey: String, sourceObjectID: String, expectedRecordCount: Int = 1,
                operation: AnyDestinationMigrationOperation) {
        self.sourceKey = sourceKey; self.sourceObjectID = sourceObjectID
        self.expectedRecordCount = expectedRecordCount; self.operation = operation
    }
}

public struct AnyDestinationCoverage: Codable, Equatable, Sendable {
    /// These closed native-system cases preserve the original witness. A
    /// nonempty KV store, settings object, history or unknown application
    /// object cannot be silently placed in this category.
    public enum SystemKind: String, Codable, Sendable { case nativeACL, emptyNativeKeyValue }
    public enum Disposition: Codable, Equatable, Sendable {
        case mapped(itemSourceKeys: [String])
        /// The fixed path is the source option's exact UTF-8 ID under the
        /// named property's xFormat.options, never an arbitrary JSON path.
        case embeddedOption(propertySourceKey: String, evidence: AnyDestinationDefinitionEvidence,
                            descriptorSHA256: String)
        /// A captured definition binds an existing closed native contract;
        /// there is deliberately no schema mutation or replacement object.
        case canonicalProperty(AnyDestinationCanonicalPropertyBinding)
        /// A separate immutable provenance record may retain a canonical
        /// definition's original bytes. It cannot create a writable schema
        /// shadow or replace the existing native canonical admission.
        case preservedCanonicalProperty(AnyDestinationCanonicalPropertyBinding, immutableItemSourceKeys: [String])
        case preservedEmbeddedOption(propertySourceKey: String, evidence: AnyDestinationDefinitionEvidence,
                                     descriptorSHA256: String, immutableItemSourceKeys: [String])
        case retainedSystem(kind: SystemKind, capturedRowCount: Int, witnessSHA256: String)
        case blocked(reasons: [String])
    }
    public let sourceObjectID: String
    public let disposition: Disposition
    public init(sourceObjectID: String, disposition: Disposition) {
        self.sourceObjectID = sourceObjectID; self.disposition = disposition
    }
}

/// A fully bound, bounded destination plan. A logical plan ID is stable; its
/// SHA binds the exact UTF-8 identities, source checkpoint, coverage and all
/// operation bytes. Decoding always reconstructs and validates this value.
public struct AnyDestinationMigrationPlan: Codable, Sendable {
    public static let version = "pinkha-destination-migration-plan-v1"
    public static let maximumItems = 100_000
    public static let maximumPlanBytes = 32 * 1024 * 1024
    public let source: AnyDestinationSourceBinding
    public let binding: AnyPreparedMigrationPlanBinding
    public let coverage: [AnyDestinationCoverage]
    public let items: [AnyDestinationMigrationItem]
    public let canonicalBytes: Data
    /// Omitted for every original plan. A supplemental property plan may bind
    /// one original namespace through its immutable creation receipt.
    public let importedPropertyNamespace: AnyDestinationImportedPropertyNamespace?

    private struct Target: Codable {
        let accountID: String
        let spaceID: String
        let storeID: String
        let planID: String
    }
    private struct Content: Codable {
        let version: String
        let source: AnyDestinationSourceBinding
        let target: Target
        let coverage: [AnyDestinationCoverage]
        let items: [AnyDestinationMigrationItem]
        let importedPropertyNamespace: AnyDestinationImportedPropertyNamespace?
    }

    public init(source: AnyDestinationSourceBinding, workspace: AnyTorahWorkspace,
                storeID: String, planID: String, coverage: [AnyDestinationCoverage],
                items: [AnyDestinationMigrationItem],
                importedPropertyNamespace: AnyDestinationImportedPropertyNamespace? = nil) throws {
        let provisional = try AnyPreparedMigrationPlanBinding(workspace: workspace, storeID: storeID,
            planID: planID, planSHA256: String(repeating: "0", count: 64))
        try Self.validate(source: source, coverage: coverage, items: items, provisional: provisional,
                          importedPropertyNamespace: importedPropertyNamespace)
        let content = Content(version: Self.version, source: source,
            target: Target(accountID: workspace.accountID, spaceID: workspace.spaceID, storeID: storeID, planID: planID),
            coverage: coverage, items: items, importedPropertyNamespace: importedPropertyNamespace)
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        let bytes = try encoder.encode(content)
        guard bytes.count <= Self.maximumPlanBytes else { throw AnyDestinationMigrationError.invalidPlan("plan size") }
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: bytes, encoded: bytes)
        self.source = source; self.coverage = coverage; self.items = items; self.canonicalBytes = bytes
        self.importedPropertyNamespace = importedPropertyNamespace
        self.binding = try .init(workspace: workspace, storeID: storeID, planID: planID,
                                 planSHA256: AnyContentDigest.sha256(bytes))
    }

    private enum CodingKeys: String, CodingKey { case content, planSHA256 }
    public func encode(to encoder: any Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(JSONDecoder().decode(Content.self, from: canonicalBytes), forKey: .content)
        try c.encode(binding.planSHA256, forKey: .planSHA256)
    }
    public init(from decoder: any Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        let content = try c.decode(Content.self, forKey: .content)
        guard content.version == Self.version else { throw AnyDestinationMigrationError.invalidPlan("version") }
        let target = content.target
        try self.init(source: content.source,
            workspace: .init(accountID: target.accountID, spaceID: target.spaceID),
            storeID: target.storeID, planID: target.planID, coverage: content.coverage, items: content.items,
            importedPropertyNamespace: content.importedPropertyNamespace)
        guard try c.decode(String.self, forKey: .planSHA256) == binding.planSHA256 else {
            throw AnyDestinationMigrationError.changedPlan
        }
    }

    /// Use this entry point for untrusted persisted or transported JSON. It
    /// also rejects duplicate/colliding keys and lossy numeric representations.
    public static func decode(_ data: Data) throws -> Self {
        guard data.count <= Self.maximumPlanBytes + 1024 else { throw AnyDestinationMigrationError.invalidPlan("plan size") }
        let value = try JSONDecoder().decode(Self.self, from: data)
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: data, encoded: encoder.encode(value))
        return value
    }

    public var blockers: [String] {
        coverage.flatMap { entry -> [String] in
            if case .blocked(let reasons) = entry.disposition { return reasons }
            return []
        }
    }

    func requireExecutable() throws {
        guard blockers.isEmpty else { throw AnyDestinationMigrationError.incompleteCoverage(blockers.joined(separator: "; ")) }
    }

    private static func validate(source: AnyDestinationSourceBinding, coverage: [AnyDestinationCoverage],
                                 items: [AnyDestinationMigrationItem], provisional: AnyPreparedMigrationPlanBinding,
                                 importedPropertyNamespace: AnyDestinationImportedPropertyNamespace?) throws {
        try importedPropertyNamespace?.requireSupplement(source: source, binding: provisional, items: items)
        guard !items.isEmpty, items.count <= maximumItems,
              coverage.count == source.sourceObjectIDs.count else {
            throw AnyDestinationMigrationError.invalidPlan("item or coverage count")
        }
        let sourceIDs = Set(source.sourceObjectIDs.map { Data($0.utf8) })
        var keys: [Data: Int] = [:]
        var lastPhase = 0
        var propertyGroups = Set<Data>()
        for (index, item) in items.enumerated() {
            guard AnyPreparedMigrationPlanBinding.validOpaque(item.sourceKey, maximum: 4096),
                  sourceIDs.contains(Data(item.sourceObjectID.utf8)),
                  keys[Data(item.sourceKey.utf8)] == nil,
                  (1...AnyPreparedDefinitionReceipt.maximumRecordIDs).contains(item.expectedRecordCount),
                  item.operation.phase >= lastPhase else {
                throw AnyDestinationMigrationError.invalidPlan("item identity/order")
            }
            if item.operation.kind != "partDefinition", item.expectedRecordCount != 1 {
                throw AnyDestinationMigrationError.invalidPlan("record count")
            }
            try item.operation.validateReferences { reference in
                try AnyDestinationPlanChecks.reference(reference)
                if case .mapped(let key, let slot, _) = reference {
                    guard let earlier = keys[Data(key.utf8)], earlier < index else {
                        throw AnyDestinationMigrationError.unknownReference(key)
                    }
                    let previous = items[earlier]
                    if case .record(let record) = slot, record >= previous.expectedRecordCount {
                        throw AnyDestinationMigrationError.invalidPlan("record reference bound")
                    }
                    if case .fileID = slot, previous.operation.kind != "file" && previous.operation.kind != "inlineFile" {
                        throw AnyDestinationMigrationError.invalidPlan("file reference kind")
                    }
                }
            }
            // Mutations retain same-plan ownership. The sole exception below
            // is a property-only supplement bound to the original namespace
            // prerequisite; it cannot update arbitrary existing objects.
            func mappedOwner(_ reference: AnyDestinationReference, kinds: Set<String>) throws {
                guard case .mapped(let key, .objectID, .rawID) = reference,
                      let owner = keys[Data(key.utf8)], kinds.contains(items[owner].operation.kind) else {
                    throw AnyDestinationMigrationError.invalidPlan("mutation owner must be created by this plan")
                }
            }
            switch item.operation {
            case .propertyDefinition(let owner, _, _, _, _, _, _, _):
                if let namespace = importedPropertyNamespace {
                    guard case .native(let id) = owner,
                          Data(id.utf8) == Data(namespace.ownerID.utf8) else {
                        throw AnyDestinationMigrationError.invalidPlan("external property namespace")
                    }
                } else {
                    try mappedOwner(owner, kinds: ["typeDefinition", "collectionDefinition"])
                }
            case .partDefinition(let owner, _):
                try mappedOwner(owner, kinds: ["typeDefinition"])
            case .editorBlock(let owner, _, _, _, _, _, _), .file(let owner, _, _, _, _):
                try mappedOwner(owner, kinds: ["object"])
            case .anchoredEditorBlock(let owner, _, _, let text, _, _, _):
                try mappedOwner(owner, kinds: ["object"])
                guard case .mapped(let key, .objectID, .rawID) = owner,
                      let ownerIndex = keys[Data(key.utf8)],
                      Data(text.sourceSpaceID.utf8) == Data(source.spaceID.utf8),
                      Data(text.sourceObjectID.utf8) == Data(item.sourceObjectID.utf8),
                      Data(items[ownerIndex].sourceObjectID.utf8) == Data(item.sourceObjectID.utf8) else {
                    throw AnyDestinationMigrationError.invalidPlan("semantic anchor source owner")
                }
            case .immutableRecord(let object, let ownerType, let datasetKey, let values):
                try mappedOwner(object, kinds: ["object"])
                try mappedOwner(ownerType, kinds: ["typeDefinition"])
                guard case .mapped(let objectKey, .objectID, .rawID) = object,
                      let objectIndex = keys[Data(objectKey.utf8)],
                      case .object(let actualType, _, _) = items[objectIndex].operation,
                      actualType == ownerType else {
                    throw AnyDestinationMigrationError.invalidPlan("immutable record object/type ownership")
                }
                try AnyDestinationImmutableRecordChecks.requireOwnedDeclaration(
                    items: Array(items.prefix(index)), ownerType: ownerType, datasetKey: datasetKey, values: values)
            case .propertyUpdate(let object, let owner, let patch):
                try mappedOwner(object, kinds: ["object"])
                if case .native(let literal) = owner {
                    guard Data(literal.utf8) == Data("any".utf8) else {
                        throw AnyDestinationMigrationError.invalidPlan("property owner")
                    }
                } else { try mappedOwner(owner, kinds: ["typeDefinition", "collectionDefinition"]) }
                if case .mapped(let objectKey, _, _) = object,
                   let sourceIndex = keys[Data(objectKey.utf8)],
                   case .object(_, _, let initial) = items[sourceIndex].operation,
                   let created = try initial.resolved(AnyDestinationPlanChecks.placeholder).object,
                   let original = created[try AnyDestinationPlanChecks.placeholder(owner)]?.object,
                   let later = try patch.resolved(AnyDestinationPlanChecks.placeholder).object,
                   !Set(original.keys).isDisjoint(with: Set(later.keys)) {
                    throw AnyDestinationMigrationError.invalidPlan("property update replaces an immutable creation field")
                }
            default: break
            }
            // Run the existing production constructors against distinct inert
            // validation IDs. No source ID is submitted as a destination ID.
            try item.operation.validateShape(binding: provisional, sourceKey: item.sourceKey)
            if case .propertyUpdate(let object, let owner, _) = item.operation {
                let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
                let group = try encoder.encode([object, owner])
                guard propertyGroups.insert(group).inserted else {
                    throw AnyDestinationMigrationError.invalidPlan("duplicate property object/owner group")
                }
            }
            keys[Data(item.sourceKey.utf8)] = index; lastPhase = item.operation.phase
        }
        var covered = Set<Data>(), represented = Set<Data>(), canonicalAddresses = Set<Data>()
        let itemSourceIDs = Set(items.map { Data($0.sourceObjectID.utf8) })
        func preserveImmutable(_ itemKeys: [String], sourceID: Data) throws {
            guard !itemKeys.isEmpty else {
                throw AnyDestinationMigrationError.invalidPlan("preserved definition record coverage")
            }
            for key in itemKeys {
                let raw = Data(key.utf8)
                guard let index = keys[raw], represented.insert(raw).inserted,
                      Data(items[index].sourceObjectID.utf8) == sourceID else {
                    throw AnyDestinationMigrationError.invalidPlan("preserved definition record coverage")
                }
                guard case .immutableRecord = items[index].operation else {
                    throw AnyDestinationMigrationError.invalidPlan("preserved definition requires immutable records")
                }
            }
        }
        for entry in coverage {
            let id = Data(entry.sourceObjectID.utf8)
            guard sourceIDs.contains(id), covered.insert(id).inserted else {
                throw AnyDestinationMigrationError.invalidPlan("coverage identity")
            }
            switch entry.disposition {
            case .mapped(let itemKeys):
                guard !itemKeys.isEmpty else { throw AnyDestinationMigrationError.incompleteCoverage(entry.sourceObjectID) }
                for key in itemKeys {
                    let raw = Data(key.utf8)
                    guard let index = keys[raw], represented.insert(raw).inserted,
                          Data(items[index].sourceObjectID.utf8) == id else {
                        throw AnyDestinationMigrationError.invalidPlan("coverage mapping")
                    }
                }
            case .embeddedOption(let propertyKey, let evidence, let descriptorSHA256):
                try evidence.requireSource(source, objectID: entry.sourceObjectID)
                guard !itemSourceIDs.contains(id), let propertyIndex = keys[Data(propertyKey.utf8)] else {
                    throw AnyDestinationMigrationError.invalidPlan("shadowed or absent embedded option")
                }
                try AnyDestinationDefinitionChecks.embeddedOption(evidence, descriptorSHA256: descriptorSHA256,
                                                                   property: items[propertyIndex])
            case .canonicalProperty(let binding):
                try binding.requireSource(source, objectID: entry.sourceObjectID)
                try binding.validate()
                let address = AnyPreparedMigrationPlanBinding.material([binding.ownerID, binding.propertyID])
                guard !itemSourceIDs.contains(id), canonicalAddresses.insert(address).inserted else {
                    throw AnyDestinationMigrationError.invalidPlan("shadowed or duplicate canonical property")
                }
            case .preservedCanonicalProperty(let binding, let itemKeys):
                try binding.requireSource(source, objectID: entry.sourceObjectID)
                try binding.validate()
                let address = AnyPreparedMigrationPlanBinding.material([binding.ownerID, binding.propertyID])
                guard canonicalAddresses.insert(address).inserted else {
                    throw AnyDestinationMigrationError.invalidPlan("duplicate preserved canonical property")
                }
                try preserveImmutable(itemKeys, sourceID: id)
            case .preservedEmbeddedOption(let propertyKey, let evidence, let descriptorSHA256, let itemKeys):
                try evidence.requireSource(source, objectID: entry.sourceObjectID)
                guard let propertyIndex = keys[Data(propertyKey.utf8)] else {
                    throw AnyDestinationMigrationError.invalidPlan("absent preserved embedded option")
                }
                try AnyDestinationDefinitionChecks.embeddedOption(evidence, descriptorSHA256: descriptorSHA256,
                                                                   property: items[propertyIndex])
                try preserveImmutable(itemKeys, sourceID: id)
            case .retainedSystem(let kind, let count, let witness):
                guard witness == source.witnessSHA256, !itemSourceIDs.contains(id) else {
                    throw AnyDestinationMigrationError.invalidPlan("system preservation")
                }
                try AnyDestinationSystemCoverageChecks.require(source: source, sourceID: entry.sourceObjectID,
                                                               kind: kind, capturedRowCount: count)
            case .blocked(let reasons):
                guard !reasons.isEmpty, reasons.count <= 128,
                      reasons.allSatisfy({ AnyPreparedMigrationPlanBinding.validOpaque($0, maximum: 4096) }) else {
                    throw AnyDestinationMigrationError.invalidPlan("coverage blocker")
                }
            }
        }
        guard represented == Set(keys.keys) else { throw AnyDestinationMigrationError.invalidPlan("unaccounted operation") }
    }
}

enum AnyDestinationPlanChecks {
    static func identity(_ value: String) -> Bool {
        AnyPreparedMigrationPlanBinding.validOpaque(value, maximum: 4096)
    }
    static func digest(_ value: String) -> Bool { AnyNativeCreationIdentity.isHex(value, count: 64) }
    static func reference(_ value: AnyDestinationReference) throws {
        switch value {
        case .native(let id):
            guard identity(id), id.utf8.count <= 4096 else { throw AnyDestinationMigrationError.invalidPlan("literal key") }
        case .mapped(let sourceKey, let slot, let encoding):
            guard identity(sourceKey) else { throw AnyDestinationMigrationError.invalidPlan("reference key") }
            if case .record(let index) = slot, !(0..<2048).contains(index) {
                throw AnyDestinationMigrationError.invalidPlan("reference slot")
            }
            switch (slot, encoding) {
            case (_, .rawID), (.objectID, .anyURI), (.fileID, .fileURI): break
            default: throw AnyDestinationMigrationError.invalidPlan("reference URI namespace")
            }
        }
    }
    static func placeholder(_ value: AnyDestinationReference) throws -> String {
        try reference(value)
        switch value {
        case .native(let value): return value
        case .mapped(let key, let slot, let encoding):
            let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
            let token = AnyContentDigest.sha256(try encoder.encode(slot) + Data(key.utf8))
            switch encoding {
            case .rawID: return "validation-" + token
            case .anyURI: return "any://validation-" + token
            case .fileURI:
                return try AnyNativeFileReference(spaceID: "validation-space", fileID: "validation-" + token).uri
            }
        }
    }
}

extension AnyDestinationValue {
    func references(_ visit: (AnyDestinationReference) throws -> Void, depth: Int = 0) throws {
        guard depth <= 32 else { throw AnyDestinationMigrationError.invalidPlan("value depth") }
        switch self {
        case .literal(let value):
            let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
            let bytes = try encoder.encode(value)
            guard bytes.count <= 1_048_576 else { throw AnyDestinationMigrationError.invalidPlan("value size") }
            try AnyTorahSourceJSONGuard.validateRoundTrip(original: bytes, encoded: bytes)
        case .reference(let reference): try visit(reference)
        case .array(let values):
            guard values.count <= 65_536 else { throw AnyDestinationMigrationError.invalidPlan("array bound") }
            for value in values { try value.references(visit, depth: depth + 1) }
        case .object(let fields):
            guard fields.count <= 65_536 else { throw AnyDestinationMigrationError.invalidPlan("field bound") }
            for field in fields { try visit(field.key); try field.value.references(visit, depth: depth + 1) }
        }
    }

    func resolved(_ resolve: (AnyDestinationReference) throws -> String) throws -> AnyJSON {
        switch self {
        case .literal(let value): return value
        case .reference(let reference): return .string(try resolve(reference))
        case .array(let values): return .array(try values.map { try $0.resolved(resolve) })
        case .object(let fields):
            var object: [String: AnyJSON] = [:]
            var bytes = Set<Data>()
            for field in fields {
                let key = try resolve(field.key)
                // Swift String dictionaries use canonical equivalence. Refuse
                // a collision rather than merging distinct UTF-8 field names.
                guard bytes.insert(Data(key.utf8)).inserted, object[key] == nil else {
                    throw AnyDestinationMigrationError.invalidPlan("resolved field collision")
                }
                object[key] = try field.value.resolved(resolve)
            }
            return .object(object)
        }
    }
}

extension AnyDestinationMigrationOperation {
    func validateReferences(_ visit: (AnyDestinationReference) throws -> Void) throws {
        switch self {
        case .typeDefinition(let seed), .collectionDefinition(let seed):
            try seed.meta.references(visit); try seed.layout?.references(visit)
        case .propertyDefinition(let owner, _, _, _, _, _, let format, _):
            try visit(owner); try format?.references(visit)
        case .partDefinition(let owner, let draft): try visit(owner); try draft.references(visit)
        case .object(let type, let collections, let properties):
            try visit(type); for collection in collections { try visit(collection) }; try properties.references(visit)
        case .editorBlock(let owner, _, _, _, let style, let parent, _),
             .anchoredEditorBlock(let owner, _, _, _, let style, let parent, _):
            try visit(owner); if let parent { try visit(parent) }; try style.references(visit)
        case .file(let owner, _, _, _, _): try visit(owner)
        case .propertyUpdate(let object, let owner, let patch):
            try visit(object); try visit(owner); try patch.references(visit)
        case .immutableRecord(let object, let owner, _, let values):
            try visit(object); try visit(owner); try values.references(visit)
        }
    }

    func validateShape(binding: AnyPreparedMigrationPlanBinding, sourceKey: String) throws {
        let resolve = AnyDestinationPlanChecks.placeholder
        switch self {
        case .typeDefinition(let seed):
            _ = try AnyPreparedDefinitionIntent.type(binding: binding, sourceKey: sourceKey, xKey: seed.xKey,
                name: seed.name, description: seed.description, iconCID: seed.iconCID,
                layout: seed.layout?.resolved(resolve), hidden: seed.hidden, meta: seed.meta.resolved(resolve))
        case .collectionDefinition(let seed):
            guard seed.layout == nil else { throw AnyDestinationMigrationError.invalidPlan("collection layout") }
            _ = try AnyPreparedDefinitionIntent.collection(binding: binding, sourceKey: sourceKey, xKey: seed.xKey,
                name: seed.name, description: seed.description, iconCID: seed.iconCID,
                hidden: seed.hidden, meta: seed.meta.resolved(resolve))
        case .propertyDefinition(let owner, let kind, let name, let xKey, let description, let scope, let format, let index):
            guard let kind = AnyPreparedDefinitionIntent.PropertyKind(rawValue: kind),
                  let scope = AnyPreparedDefinitionIntent.PropertyScope(rawValue: scope) else {
                throw AnyDestinationMigrationError.invalidPlan("property vocabulary")
            }
            _ = try AnyPreparedDefinitionIntent.property(binding: binding, sourceKey: sourceKey, ownerID: resolve(owner),
                kind: kind, name: name, xKey: xKey, description: description, scope: scope,
                xFormat: format?.resolved(resolve), index: index)
        case .partDefinition(let owner, let draft):
            _ = try AnyPreparedDefinitionIntent.part(binding: binding, sourceKey: sourceKey,
                                                     ownerID: resolve(owner), draft: draft.resolved(resolve))
        case .object(let type, let collections, let properties):
            _ = try AnyPreparedMigrationIntent.object(binding: binding, sourceKey: sourceKey,
                typeID: resolve(type), collections: collections.map(resolve), initialProperties: properties.resolved(resolve))
        case .editorBlock(let owner, let dataset, let type, let text, let style, let parent, let position):
            if type != "code", AnyInlineMarkdown(text).runs.contains(where: {
                $0.link.map(PinkhaSemanticTextAnchor.isReservedMarkerURL) == true
            }) {
                throw AnyDestinationMigrationError.invalidPlan("semantic anchors require a scoped migration operation")
            }
            _ = try AnyPreparedMigrationIntent.block(binding: binding, sourceKey: sourceKey, objectID: resolve(owner),
                dataset: dataset, type: type, text: text, style: style.resolved(resolve),
                parentID: parent.map(resolve) ?? "", position: position)
        case .anchoredEditorBlock(let owner, let dataset, let type, let text, let style, let parent, let position):
            guard type != "code" else {
                throw AnyDestinationMigrationError.invalidPlan("semantic anchor in literal code")
            }
            let resolved = try text.resolved(destinationSpaceID: binding.workspace.spaceID,
                                             destinationObjectID: resolve(owner))
            _ = try AnyPreparedMigrationIntent.block(binding: binding, sourceKey: sourceKey, objectID: resolve(owner),
                dataset: dataset, type: type, text: resolved, style: style.resolved(resolve),
                parentID: parent.map(resolve) ?? "", position: position)
        case .file(let owner, let name, let mime, let size, let digest):
            guard (0...AnyPreparedFileIntent.maximumBytes).contains(size), AnyDestinationPlanChecks.digest(digest) else {
                throw AnyDestinationMigrationError.invalidPlan("file bounds")
            }
            _ = try AnyPreparedFileIntent(binding: binding, sourceKey: sourceKey, ownerObjectID: resolve(owner),
                name: name, mime: mime, size: max(4096, size), contentSHA256: digest)
        case .immutableRecord(let object, let owner, let key, let values):
            _ = try AnyPreparedImmutableRecordIntent.ownedDataset(ownerTypeID: resolve(owner), key: key)
            guard AnyEditorBlock.validID(try resolve(object)), let fields = try values.resolved(resolve).object,
                  !fields.isEmpty, fields.count <= AnyPreparedImmutableRecordIntent.maximumFields,
                  fields.keys.allSatisfy(AnyPreparedImmutableRecordIntent.validField) else {
                throw AnyDestinationMigrationError.invalidPlan("immutable record values")
            }
        case .propertyUpdate(let object, let owner, let patch):
            guard let values = try patch.resolved(resolve).object else {
                throw AnyDestinationMigrationError.invalidPlan("property patch")
            }
            _ = try AnyPreparedPropertyUpdateIntent(binding: binding, sourceKey: sourceKey,
                objectID: resolve(object), ownerID: resolve(owner), patch: values, expectedApplySequence: 1)
        }
    }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

public enum AnyDestinationContentVerificationError: Error, Equatable, Sendable {
    case invalidProgress
    case mismatch(sourceKey: String, field: String)
    case changedDuringRead(String)
}

public struct AnyDestinationContentObservation: Codable, Sendable, Equatable {
    public let sourceKey: String
    public let kind: String
    public let objectID: String
    public let semanticSHA256: String
}

public struct AnyDestinationFileAvailability: Codable, Sendable, Equatable {
    public let fileID: String
    public let byteCount: Int64
    public let plaintextSHA256: String
    public let cached: Bool
    public let durable: Bool
}

/// Current content of the admitted operations, read through ordinary native
/// APIs. This is not an atomic Space snapshot and does not certify unsupported
/// source semantics, history, account/ACL migration or network file custody.
public struct AnyDestinationContentVerification: Codable, Sendable {
    public let planSHA256: String
    public let sourceManifestSHA256: String
    public let destinationAccountID: String
    public let destinationSpaceID: String
    public let destinationStoreID: String
    public let observations: [AnyDestinationContentObservation]
    public let files: [AnyDestinationFileAvailability]
    public let retainedSourceSystemObjectIDs: [String]
    public var comparedOperationCount: Int { observations.count }
}

public struct AnyDestinationMigrationVerifier: Sendable {
    private let client: AnyHTTPClient
    public init(client: AnyHTTPClient) { self.client = client }

    /// The caller must retain the original capture authority. A reconciled
    /// journal is necessary but insufficient: definitions, properties, bodies,
    /// hierarchy, reference cycles and plaintext files are compared here.
    public func verify(
        plan: AnyDestinationMigrationPlan,
        progress: AnyDestinationMigrationProgress,
        verifySource: @escaping @Sendable (AnyDestinationSourceBinding) async throws -> Void,
        authorize: @escaping @Sendable () async throws -> Void
    ) async throws -> AnyDestinationContentVerification {
        try plan.requireExecutable()
        guard progress.allItemsReconciled, progress.totalItems == plan.items.count,
              progress.mappings.count == plan.items.count, progress.verificationIntents.count == plan.items.count,
              progress.binding == plan.binding,
              try Self.bytes(progress.source) == Self.bytes(plan.source),
              Data(client.expectedAccountID.utf8) == Data(plan.binding.workspace.accountID.utf8) else {
            throw AnyDestinationContentVerificationError.invalidProgress
        }
        let admit: AnyDestinationAuthorization = {
            try Task.checkCancellation(); try await verifySource(plan.source)
            try await authorize(); try Task.checkCancellation()
        }
        try await admit()
        // Reopen the exact advertised contracts/store, including canonical
        // property admission. A new process cannot silently substitute a store.
        let driver = try await AnyDestinationNativeClients.open(client: client, plan: plan, authorize: admit)
        if let namespace = plan.importedPropertyNamespace {
            try await namespace.observe(using: driver, authorize: admit)
        }
        let prefix = ["v1", "spaces", plan.binding.workspace.spaceID]
        @Sendable func read(_ suffix: [String], body: AnyJSON? = nil,
                            query: [String: String] = [:]) async throws -> AnyJSON {
            try await admit()
            let value = try await client.requestJSON(method: body == nil ? "GET" : "POST",
                path: prefix + suffix, body: body, query: query, maximumResponseBytes: 8 << 20, authorize: admit)
            try await admit()
            return value
        }
        @Sendable func verifyReceipts() async throws {
            for (intent, mapping) in zip(progress.verificationIntents, progress.mappings) {
                guard intent.identity.id == mapping.intentID else {
                    throw AnyDestinationContentVerificationError.invalidProgress
                }
                let current = try await driver.status(intent, authorize: admit)
                guard current["stage"]?.string == "complete", current["outcome"]?.string == "committed",
                      AnyContentDigest.sha256(try Self.bytes(current)) == mapping.currentReceiptSHA256 else {
                    throw Self.failure(mapping.sourceKey, "current native receipt")
                }
            }
        }
        try await verifyReceipts()
        var mappings: [Data: AnyDestinationMigrationMapping] = [:]
        for (item, mapping) in zip(plan.items, progress.mappings) {
            guard Data(item.sourceKey.utf8) == Data(mapping.sourceKey.utf8),
                  Data(item.sourceObjectID.utf8) == Data(mapping.sourceObjectID.utf8),
                  item.operation.kind == mapping.kind, mapping.recordIDs.count == item.expectedRecordCount,
                  AnyEditorBlock.validID(mapping.objectID),
                  mapping.recordIDs.allSatisfy(AnyEditorBlock.validID),
                  Set(mapping.recordIDs.map { Data($0.utf8) }).count == mapping.recordIDs.count,
                  mappings.updateValue(mapping, forKey: Data(item.sourceKey.utf8)) == nil else {
                throw AnyDestinationContentVerificationError.invalidProgress
            }
        }
        let immutableMappings = mappings
        let resolved = try plan.items.map { item in
            try item.operation.resolved(destinationSpaceID: plan.binding.workspace.spaceID) { reference in
                try Self.resolve(reference, in: immutableMappings, destinationSpaceID: plan.binding.workspace.spaceID)
            }
        }
        var roots: [Data: String] = [:]
        var objectIndexes: [Data: Int] = [:]
        for (index, operation) in resolved.enumerated() {
            let mapping = progress.mappings[index]
            switch operation {
            case .typeDefinition: roots[Data(mapping.objectID.utf8)] = "types"
            case .collectionDefinition: roots[Data(mapping.objectID.utf8)] = "collections"
            case .object: objectIndexes[Data(mapping.objectID.utf8)] = index
            default: break
            }
        }
        var definitionsBefore: [String: AnyJSON] = [:]
        var objectsBefore: [Data: AnyJSON] = [:]
        var propertyKinds: [Data: [Data: String]] = [:]
        var observations: [AnyDestinationContentObservation] = []
        var fileAvailability: [AnyDestinationFileAvailability] = []
        var observed: [Data: AnyJSON] = [:]

        if let namespace = plan.importedPropertyNamespace {
            // The original collection has other definitions already. Compare
            // this supplement's exact new rows, retaining the whole observed
            // list for the final stability check, without claiming it created
            // or owns those earlier rows.
            let ownerID = namespace.ownerID
            roots[Data(ownerID.utf8)] = "collections"
            let rootPath = ["collections", ownerID]
            let root = try await read(rootPath)
            try namespace.requireCurrentRoot(root)
            definitionsBefore[rootPath.joined(separator: "/")] = root
            let propertyPath = rootPath + ["properties"]
            let response = try await read(propertyPath)
            let rows = try Self.array(response["properties"], namespace.mapping.sourceKey, "properties")
            guard rows.count <= 4096 else { throw AnyEngineError.readLimit }
            var allIDs = Set<Data>()
            for row in rows {
                guard let id = row["id"]?.string, AnyEditorBlock.validID(id),
                      allIDs.insert(Data(id.utf8)).inserted else {
                    throw Self.failure(namespace.mapping.sourceKey, "unique native property IDs")
                }
            }
            var createdIDs = Set<Data>(), kinds: [Data: String] = [:]
            for (index, operation) in resolved.enumerated() {
                let item = plan.items[index], mapping = progress.mappings[index]
                guard case .propertyDefinition(.native(let owner), let kind, let name, let xKey,
                                              let description, let scope, let format, let searchIndex) = operation,
                      Data(owner.utf8) == Data(ownerID.utf8),
                      Data(mapping.objectID.utf8) == Data(ownerID.utf8),
                      mapping.recordIDs.count == 1,
                      createdIDs.insert(Data(mapping.recordIDs[0].utf8)).inserted else {
                    throw AnyDestinationContentVerificationError.invalidProgress
                }
                let id = mapping.recordIDs[0]
                let actual = try Self.unique(rows, id: id, key: "id", sourceKey: item.sourceKey)
                let expected = try AnyDestinationContentProjection.property(id: id, kind: kind,
                    name: name, xKey: xKey, description: description, scope: scope,
                    format: format, index: searchIndex)
                try Self.equal(AnyDestinationContentProjection.property(actual), expected,
                               item.sourceKey, "supplemental property definition")
                observed[Data(item.sourceKey.utf8)] = expected
                kinds[Data(id.utf8)] = kind
            }
            propertyKinds[Data(ownerID.utf8)] = kinds
            definitionsBefore[propertyPath.joined(separator: "/")] = response
        }

        // Compare whole owned definition lists, not only a found first match.
        // Extra properties/parts on a newly created definition are a mismatch.
        for (index, operation) in resolved.enumerated() {
            let mapping = progress.mappings[index], item = plan.items[index]
            let route: String
            let seed: AnyDestinationRootDefinition
            switch operation {
            case .typeDefinition(let value): route = "types"; seed = value
            case .collectionDefinition(let value): route = "collections"; seed = value
            default: continue
            }
            let path = [route, mapping.objectID]
            let actual = try await read(path)
            let expected = try AnyDestinationContentProjection.root(seed, id: mapping.objectID, type: route == "types")
            try Self.equal(AnyDestinationContentProjection.root(actual, type: route == "types"), expected,
                           item.sourceKey, "definition")
            definitionsBefore[path.joined(separator: "/")] = actual
            observed[Data(item.sourceKey.utf8)] = expected
            let propertiesPath = path + ["properties"]
            let propertyResponse = try await read(propertiesPath)
            let propertyValues = try Self.array(propertyResponse["properties"], item.sourceKey, "properties")
            let propertyIndexes = resolved.indices.filter {
                if case .propertyDefinition(let owner, _, _, _, _, _, _, _) = resolved[$0] {
                    return (try? Self.native(owner)) == mapping.objectID
                }
                return false
            }
            guard propertyValues.count == propertyIndexes.count else { throw Self.failure(item.sourceKey, "property count") }
            var kinds: [Data: String] = [:]
            for propertyIndex in propertyIndexes {
                let propertyItem = plan.items[propertyIndex], propertyMapping = progress.mappings[propertyIndex]
                guard case .propertyDefinition(_, let kind, let name, let xKey, let description, let scope,
                                              let format, let searchIndex) = resolved[propertyIndex] else {
                    throw AnyDestinationContentVerificationError.invalidProgress
                }
                let id = propertyMapping.recordIDs[0]
                let value = try Self.unique(propertyValues, id: id, key: "id", sourceKey: propertyItem.sourceKey)
                let expected = try AnyDestinationContentProjection.property(id: id, kind: kind, name: name,
                    xKey: xKey, description: description, scope: scope, format: format, index: searchIndex)
                try Self.equal(AnyDestinationContentProjection.property(value), expected, propertyItem.sourceKey, "property definition")
                observed[Data(propertyItem.sourceKey.utf8)] = expected
                kinds[Data(id.utf8)] = kind
            }
            propertyKinds[Data(mapping.objectID.utf8)] = kinds
            definitionsBefore[propertiesPath.joined(separator: "/")] = propertyResponse
            if route == "types" {
                let partsPath = path + ["parts"]
                let partResponse = try await read(partsPath)
                let values = try Self.array(partResponse["parts"], item.sourceKey, "parts")
                let indexes = resolved.indices.filter {
                    if case .partDefinition(let owner, _) = resolved[$0] { return (try? Self.native(owner)) == mapping.objectID }
                    return false
                }
                guard values.count == indexes.count else { throw Self.failure(item.sourceKey, "part count") }
                for partIndex in indexes {
                    let partItem = plan.items[partIndex], partMapping = progress.mappings[partIndex]
                    guard case .partDefinition(_, let draft) = resolved[partIndex] else {
                        throw AnyDestinationContentVerificationError.invalidProgress
                    }
                    let value = try Self.unique(values, id: partMapping.recordIDs[0], key: "id", sourceKey: partItem.sourceKey)
                    let expected = try AnyDestinationContentProjection.part(draft: Self.literal(draft),
                        owner: mapping.objectID, recordIDs: partMapping.recordIDs)
                    try Self.equal(AnyDestinationContentProjection.part(value), expected, partItem.sourceKey, "compiled part")
                    observed[Data(partItem.sourceKey.utf8)] = expected
                }
                definitionsBefore[partsPath.joined(separator: "/")] = partResponse
            }
        }

        for (index, operation) in resolved.enumerated() {
            guard case .object(let type, let collections, let initial) = operation else { continue }
            let item = plan.items[index], mapping = progress.mappings[index]
            let object = try await read(["objects", mapping.objectID])
            let record = try Self.objectRecord(object, id: mapping.objectID, spaceID: plan.binding.workspace.spaceID)
            objectsBefore[Data(mapping.objectID.utf8)] = object
            let typeID = try Self.native(type)
            try Self.equal(record["any"]?["type"], .string(typeID), item.sourceKey, "object type")
            let collectionIDs = try collections.map { try Self.native($0) }
            let actualCollections = try Self.array(record["any"]?["collections"] ?? .array([]), item.sourceKey, "collections")
            guard actualCollections.count == collectionIDs.count,
                  Set(actualCollections.compactMap { $0.string.map { Data($0.utf8) } }) == Set(collectionIDs.map { Data($0.utf8) }) else {
                throw Self.failure(item.sourceKey, "object collections")
            }
            guard var properties = try Self.literal(initial).object else { throw AnyDestinationContentVerificationError.invalidProgress }
            for updateIndex in resolved.indices {
                if case .propertyUpdate(let target, let owner, let patch) = resolved[updateIndex],
                   try Self.native(target) == mapping.objectID {
                    let ownerID = try Self.native(owner)
                    var fields = properties[ownerID]?.object ?? [:]
                    guard let values = try Self.literal(patch).object else { throw AnyDestinationContentVerificationError.invalidProgress }
                    for (key, value) in values { fields[key] = value }
                    properties[ownerID] = .object(fields)
                }
            }
            // A native JSON null is an unset in this specific properties API.
            // Empty strings and empty arrays remain present and distinct.
            for owner in [typeID] + collectionIDs {
                if properties[owner] == nil { properties[owner] = .object([:]) }
            }
            var projection: [String: AnyJSON] = ["id": .string(mapping.objectID), "type": .string(typeID),
                "collections": .array(collectionIDs.sorted().map(AnyJSON.string))]
            for (owner, value) in properties {
                guard let expectedFields = value.object else { throw AnyDestinationContentVerificationError.invalidProgress }
                let actualFields = record[owner]?.object ?? [:]
                var expected: [String: AnyJSON] = [:]
                for (key, value) in expectedFields {
                    if value == .null {
                        guard actualFields[key] == nil else { throw Self.failure(item.sourceKey, "unset property") }
                    } else {
                        let kind = propertyKinds[Data(owner.utf8)]?[Data(key.utf8)]
                        let canonical = try AnyDestinationContentProjection.propertyValue(value, kind: kind)
                        let actual = try actualFields[key].map { try AnyDestinationContentProjection.propertyValue($0, kind: kind) }
                        try Self.equal(actual, canonical, item.sourceKey, "property value")
                        expected[key] = canonical
                    }
                }
                if owner != "any", roots[Data(owner.utf8)] != nil,
                   Set(actualFields.keys.map { Data($0.utf8) }) != Set(expected.keys.map { Data($0.utf8) }) {
                    throw Self.failure(item.sourceKey, "extra or missing property value")
                }
                projection[owner] = .object(expected)
            }
            observed[Data(item.sourceKey.utf8)] = .object(projection)
        }

        struct BlockGroup: Hashable { let owner: String; let dataset: String }
        var groups: [BlockGroup: [Int]] = [:]
        for (index, operation) in resolved.enumerated() {
            if case .editorBlock(let owner, let dataset, _, _, _, _, _) = operation {
                groups[.init(owner: try Self.native(owner), dataset: dataset), default: []].append(index)
            } else if case .immutableRecord(let object, let owner, let key, _) = operation {
                let dataset = try AnyPreparedImmutableRecordIntent.ownedDataset(ownerTypeID: Self.native(owner), key: key)
                groups[.init(owner: try Self.native(object), dataset: dataset), default: []].append(index)
            }
        }
        // Also inspect empty datasets declared by this plan. Otherwise a new
        // unexpected body on an object with zero planned blocks could escape.
        for index in resolved.indices {
            guard case .object(let type, _, _) = resolved[index] else { continue }
            let typeID = try Self.native(type), objectID = progress.mappings[index].objectID
            for partIndex in resolved.indices {
                guard case .partDefinition(let owner, _) = resolved[partIndex],
                      try Self.native(owner) == typeID,
                      let datasets = observed[Data(plan.items[partIndex].sourceKey.utf8)]?["datasets"]?.array else { continue }
                for dataset in datasets {
                    guard let collection = dataset["collection"]?.string else {
                        throw AnyDestinationContentVerificationError.invalidProgress
                    }
                    let group = BlockGroup(owner: objectID, dataset: collection)
                    if groups[group] == nil { groups[group] = [] }
                }
            }
        }
        for (group, indexes) in groups {
            var rows: [AnyJSON] = [], offset = 0
            repeat {
                let response = try await read(["query"], body: .object([
                    "objectId": .string(group.owner), "dataset": .string(group.dataset),
                    "sort": .array([.string("id")]), "limit": .integer(256),
                    "offset": .integer(Int64(offset)), "includeTotal": .bool(true)
                ]))
                let page = try Self.array(response["records"], group.owner, "block records")
                guard response["total"]?.integer == Int64(indexes.count), (indexes.isEmpty || !page.isEmpty),
                      page.count <= 256, page.count <= indexes.count - offset,
                      response["hasNext"]?.bool == (offset + page.count < indexes.count) else {
                    throw Self.failure(group.owner, "complete block census")
                }
                rows.append(contentsOf: page); offset += page.count
            } while offset < indexes.count
            guard Set(rows.compactMap { $0["id"]?.string.map { Data($0.utf8) } }).count == indexes.count else {
                throw Self.failure(group.owner, "duplicate block identity")
            }
            for index in indexes {
                let item = plan.items[index], mapping = progress.mappings[index]
                if case .immutableRecord = resolved[index] {
                    guard case .immutableRecord(let intent) = progress.verificationIntents[index] else {
                        throw AnyDestinationContentVerificationError.invalidProgress
                    }
                    let row = try Self.unique(rows, id: mapping.recordIDs[0], key: "id", sourceKey: item.sourceKey)
                    guard mapping.signedChangeIDs.count == 1 else {
                        throw Self.failure(item.sourceKey, "one signed immutable creation")
                    }
                    let changeID = mapping.signedChangeIDs[0]
                    var selected: AnyJSON?, cursor: String?
                    var cursors = Set<Data>(), versions = Set<Data>()
                    for page in 0..<64 {
                        var query = ["dataset": intent.schema.dataset, "recordId": mapping.recordIDs[0],
                                     "coalesce": "false", "limit": "200"]
                        if let cursor { query["cursor"] = cursor }
                        let history = try await read(["objects", intent.objectID, "history"], query: query)
                        guard let changes = history["changes"]?.array, changes.count <= 200,
                              history["cursor"] == nil || history["cursor"]?.string != nil else {
                            throw Self.failure(item.sourceKey, "native immutable history page")
                        }
                        for value in changes {
                            let change = try AnyNativeHistoryChange(native: value)
                            guard versions.insert(Data(change.version.utf8)).inserted else {
                                throw Self.failure(item.sourceKey, "duplicate native history version")
                            }
                            if Data(change.version.utf8) == Data(changeID.utf8) { selected = value }
                        }
                        let next = history["cursor"]?.string ?? ""
                        guard next.utf8.count <= 8192, !next.utf8.contains(0),
                              next.isEmpty || (!changes.isEmpty && cursors.insert(Data(next.utf8)).inserted) else {
                            throw Self.failure(item.sourceKey, "native immutable history cursor")
                        }
                        if selected != nil || next.isEmpty { break }
                        guard page < 63 else { throw Self.failure(item.sourceKey, "bounded native creation history") }
                        cursor = next
                    }
                    guard let selected else { throw Self.failure(item.sourceKey, "signed creation absent from native history") }
                    // Every identifier is a separate encoded path component,
                    // including native record IDs that contain a slash.
                    let snapshot = try await read(["objects", intent.objectID, "history", changeID,
                        "datasets", intent.schema.dataset, "records", mapping.recordIDs[0]])
                    let authority = try AnyDestinationImmutableRecordAuthority(change: selected, snapshot: snapshot,
                        intent: intent, recordID: mapping.recordIDs[0], expectedChangeID: changeID)
                    let projection = try Self.immutableRecordProjection(row, intent: intent, authority: authority)
                    try Self.equal(projection,
                        Self.immutableRecordProjection(authority.recordAtChange, intent: intent, authority: authority),
                        item.sourceKey, "current immutable record versus signed creation causal cut")
                    observed[Data(item.sourceKey.utf8)] = projection
                    continue
                }
                guard case .editorBlock(_, _, let type, let text, let style, let parent, let position) = resolved[index] else {
                    throw AnyDestinationContentVerificationError.invalidProgress
                }
                let row = try Self.unique(rows, id: mapping.recordIDs[0], key: "id", sourceKey: item.sourceKey)
                let expected = AnyJSON.object(["id": .string(mapping.recordIDs[0]), "type": .string(type), "text": .string(text),
                    "style": try Self.literal(style), "parentId": .string(try parent.map(Self.native) ?? ""), "position": .string(position)])
                let actual = AnyJSON.object(["id": row["id"] ?? .null, "type": row["type"] ?? .null,
                    "text": row["text"] ?? .string(""), "style": row["style"] ?? .object([:]),
                    "parentId": row["nav"]?["parentId"] ?? .string(""), "position": row["nav"]?["pos"] ?? .null])
                try Self.equal(actual, expected, item.sourceKey, "block text/style/hierarchy")
                observed[Data(item.sourceKey.utf8)] = expected
            }
        }
        for (index, operation) in resolved.enumerated() {
            guard case .file(let owner, let name, let mime, let size, let digest) = operation else { continue }
            let item = plan.items[index], mapping = progress.mappings[index]
            guard let fileID = mapping.fileID else { throw AnyDestinationContentVerificationError.invalidProgress }
            let ownerID = try Self.native(owner), path = ["files", fileID]
            let before = try await read(path)
            let expected = AnyJSON.object(["fileId": .string(fileID), "objectId": .string(ownerID),
                "name": .string(name), "mime": .string(mime), "size": .integer(size), "inline": .bool(size < 4096),
                "variant": .string(""), "variantOf": .string("")])
            try Self.equal(AnyDestinationContentProjection.file(before), expected, item.sourceKey, "file metadata")
            let content = try await client.readFileContentDigest(spaceID: plan.binding.workspace.spaceID,
                fileID: fileID, size: size, mime: mime, authorize: admit)
            guard content.byteCount == size, content.sha256 == digest else { throw Self.failure(item.sourceKey, "plaintext file bytes") }
            let after = try await read(path)
            try Self.equal(AnyDestinationContentProjection.file(after), expected, item.sourceKey, "file metadata after read")
            guard after["cached"]?.bool == true, let durable = after["durable"]?.bool,
                  try Self.bytes(before["rootCid"]) == Self.bytes(after["rootCid"]) else {
                throw Self.failure(item.sourceKey, "file cache/content identity")
            }
            if size < 4096 {
                guard durable, after["rootCid"] == nil || after["rootCid"]?.string == "" else {
                    throw Self.failure(item.sourceKey, "inline file tier")
                }
            } else if after["rootCid"]?.string?.isEmpty != false { throw Self.failure(item.sourceKey, "encrypted file content address") }
            observed[Data(item.sourceKey.utf8)] = .object(["metadata": expected, "plaintextSHA256": .string(digest)])
            fileAvailability.append(.init(fileID: fileID, byteCount: size, plaintextSHA256: digest, cached: true, durable: durable))
        }
        // The native file list is bounded to one extra row to detect duplicates
        // without loading unrelated objects or an unbounded workspace listing.
        for (owner, index) in objectIndexes {
            let id = progress.mappings[index].objectID
            let files = resolved.indices.compactMap { fileIndex -> String? in
                if case .file(let ref, _, _, _, _) = resolved[fileIndex],
                   (try? Self.native(ref)).map({ Data($0.utf8) }) == owner { return progress.mappings[fileIndex].fileID }
                return nil
            }
            let listing = try await read(["files"], query: ["objectId": id, "limit": String(files.count + 1)])
            let actual = try Self.array(listing["files"], id, "file census")
            guard actual.count == files.count,
                  Set(actual.compactMap { $0["fileId"]?.string.map { Data($0.utf8) } }) == Set(files.map { Data($0.utf8) }) else {
                throw Self.failure(id, "complete file census")
            }
        }
        for (index, operation) in resolved.enumerated() {
            guard case .propertyUpdate(let object, let owner, let patch) = operation else { continue }
            let id = try Self.native(object), ownerID = try Self.native(owner), item = plan.items[index]
            // The complete final property state (including cycles) was compared
            // on the real object above; retain this operation's exact patch too.
            guard objectsBefore[Data(id.utf8)] != nil else { throw AnyDestinationContentVerificationError.invalidProgress }
            observed[Data(item.sourceKey.utf8)] = .object(["objectId": .string(id), "ownerId": .string(ownerID),
                                                        "patch": try Self.literal(patch)])
        }

        // Detect changes while the comparison was running. This is explicitly
        // still a series of native reads, not a global transactional snapshot.
        for (path, before) in definitionsBefore {
            let after = try await read(path.split(separator: "/").map(String.init))
            guard try Self.bytes(after) == Self.bytes(before) else {
                throw AnyDestinationContentVerificationError.changedDuringRead(path)
            }
        }
        for (id, before) in objectsBefore {
            guard let value = String(data: id, encoding: .utf8) else { throw AnyDestinationContentVerificationError.invalidProgress }
            let after = try await read(["objects", value])
            guard try Self.bytes(after) == Self.bytes(before) else {
                throw AnyDestinationContentVerificationError.changedDuringRead(value)
            }
        }
        for (item, mapping) in zip(plan.items, progress.mappings) {
            guard let value = observed[Data(item.sourceKey.utf8)] else { throw AnyDestinationContentVerificationError.invalidProgress }
            observations.append(.init(sourceKey: item.sourceKey, kind: item.operation.kind, objectID: mapping.objectID,
                                      semanticSHA256: AnyContentDigest.sha256(try Self.bytes(value))))
        }
        try await verifyReceipts()
        if let namespace = plan.importedPropertyNamespace {
            try await namespace.observe(using: driver, authorize: admit)
        }
        try await admit()
        return .init(planSHA256: plan.binding.planSHA256, sourceManifestSHA256: plan.source.captureManifestSHA256,
            destinationAccountID: plan.binding.workspace.accountID, destinationSpaceID: plan.binding.workspace.spaceID,
            destinationStoreID: plan.binding.storeID, observations: observations, files: fileAvailability,
            retainedSourceSystemObjectIDs: plan.coverage.compactMap {
                if case .retainedSystem = $0.disposition { return $0.sourceObjectID }; return nil
            })
    }

    /// Native source fact values and runtime stamps are compared independently.
    /// The receipt does not substitute for this ordinary dataset readback.
    static func immutableRecordProjection(_ row: AnyJSON, intent: AnyPreparedImmutableRecordIntent,
                                          authority: AnyDestinationImmutableRecordAuthority) throws -> AnyJSON {
        guard authority.intentID == intent.intentID, authority.specSHA256 == intent.specSHA256,
              row["id"]?.string.map({ Data($0.utf8) }) == Data(authority.recordID.utf8),
              let fields = intent.schema.declaration["properties"]?.object else {
            throw AnyDestinationContentVerificationError.invalidProgress
        }
        var values: [String: AnyJSON] = [:], stamps: [String: AnyJSON] = [:]
        for (key, field) in fields {
            if let stamp = field["x-stamp"]?.string, stamp != "none" {
                guard let actual = row[key] else { throw failure(intent.sourceKey, "missing native immutable stamp") }
                switch stamp {
                case "creator":
                    guard let identity = actual.string, AnyEditorBlock.validID(identity), identity.utf8.count <= 256,
                          Data(identity.utf8) == Data(authority.author.utf8) else {
                        throw failure(intent.sourceKey, "native immutable creator")
                    }
                    stamps[key] = actual
                case "createTime":
                    let normalized = try AnyDestinationContentProjection.propertyValue(actual, kind: "datetime")
                    guard normalized.integer == authority.timestampMilliseconds else {
                        throw failure(intent.sourceKey, "native immutable timestamp differs from signed creation")
                    }
                    stamps[key] = normalized
                default: throw AnyDestinationContentVerificationError.invalidProgress
                }
            } else {
                let kind = field["type"]?.string
                let expected = try intent.values[key].map { try AnyDestinationContentProjection.propertyValue($0, kind: kind) }
                let actual = try row[key].map { try AnyDestinationContentProjection.propertyValue($0, kind: kind) }
                try equal(actual, expected, intent.sourceKey, "immutable source value:" + key)
                if let expected { values[key] = expected }
            }
        }
        return .object(["objectId": .string(intent.objectID), "ownerTypeId": .string(intent.schema.ownerTypeID),
            "dataset": .string(intent.schema.dataset), "schemaSHA256": .string(intent.schema.nativeSHA256),
            "values": .object(values), "nativeStamps": .object(stamps),
            "signedCreation": .object(["changeId": .string(authority.changeID), "author": .string(authority.author),
                "authorClockTimestampSeconds": .integer(authority.timestampSeconds)])])
    }

    static func bytes<T: Encodable>(_ value: T) throws -> Data {
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        return try encoder.encode(value)
    }
    static func equal(_ actual: AnyJSON?, _ expected: AnyJSON?, _ sourceKey: String, _ field: String) throws {
        guard try bytes(actual) == bytes(expected) else { throw failure(sourceKey, field) }
    }
    static func failure(_ sourceKey: String, _ field: String) -> AnyDestinationContentVerificationError {
        .mismatch(sourceKey: sourceKey, field: field)
    }
    static func native(_ ref: AnyDestinationReference) throws -> String {
        guard case .native(let value) = ref else { throw AnyDestinationContentVerificationError.invalidProgress }; return value
    }
    static func literal(_ value: AnyDestinationValue) throws -> AnyJSON {
        guard case .literal(let value) = value else { throw AnyDestinationContentVerificationError.invalidProgress }; return value
    }
    static func array(_ value: AnyJSON?, _ sourceKey: String, _ field: String) throws -> [AnyJSON] {
        guard let values = value?.array else { throw failure(sourceKey, field) }; return values
    }
    static func unique(_ values: [AnyJSON], id: String, key: String, sourceKey: String) throws -> AnyJSON {
        let matches = values.filter { $0[key]?.string.map({ Data($0.utf8) }) == Data(id.utf8) }
        guard matches.count == 1 else { throw failure(sourceKey, key) }; return matches[0]
    }
    static func objectRecord(_ value: AnyJSON, id: String, spaceID: String) throws -> AnyJSON {
        guard value["objectId"]?.string.map({ Data($0.utf8) }) == Data(id.utf8),
              let record = value["record"], record.object != nil,
              record["id"]?.string.map({ Data($0.utf8) }) == Data(id.utf8),
              record["spaceId"]?.string.map({ Data($0.utf8) }) == Data(spaceID.utf8),
              let sequence = record["_applySeq"]?.integer, sequence > 0 else { throw failure(id, "object identity/sequence") }
        return record
    }
    static func resolve(_ reference: AnyDestinationReference,
                        in mappings: [Data: AnyDestinationMigrationMapping], destinationSpaceID: String) throws -> String {
        guard case .mapped(let key, let slot, let encoding) = reference else { return try native(reference) }
        guard let mapping = mappings[Data(key.utf8)] else { throw AnyDestinationContentVerificationError.invalidProgress }
        let result: String
        switch slot {
        case .objectID: result = mapping.objectID
        case .record(let index):
            guard mapping.recordIDs.indices.contains(index) else { throw AnyDestinationContentVerificationError.invalidProgress }
            result = mapping.recordIDs[index]
        case .fileID:
            guard let id = mapping.fileID else { throw AnyDestinationContentVerificationError.invalidProgress }; result = id
        }
        switch encoding {
        case .rawID: return result
        case .anyURI: return "any://" + result
        case .fileURI: return try AnyNativeFileReference(spaceID: destinationSpaceID, fileID: result).uri
        }
    }
}

