import Foundation
import PinkhaAnyIntegration

public enum AnyHeartNativeSourceAccountError: Error, Equatable, Sendable {
    case invalidLifecycle, invalidAuthority, inactiveCapture, sessionCloseFailed
}

/// An in-memory response from the app's real WalletCreateSession call.
/// The controller takes ownership before validating the response, so an
/// unexpected account/scope can never leak a newly allocated native session.
public struct AnyHeartNativeSourceSessionGrant: Sendable, CustomStringConvertible,
                                               CustomDebugStringConvertible {
    fileprivate let token: String
    fileprivate let accountID: String
    fileprivate let isFull: Bool
    fileprivate let isAppAssociated: Bool

    public init(sessionToken: String, accountID: String,
                isFull: Bool, isAppAssociated: Bool) {
        token = sessionToken; self.accountID = accountID
        self.isFull = isFull; self.isAppAssociated = isAppAssociated
    }

    public var description: String { "AnyHeartNativeSourceSessionGrant(redacted)" }
    public var debugDescription: String { description }

    fileprivate func session(expectedAccountID: String, spaceID: String) throws -> AnyHeartNativeSourceSession {
        guard isFull, !isAppAssociated, Data(accountID.utf8) == Data(expectedAccountID.utf8) else {
            throw AnyHeartNativeSourceAccountError.invalidAuthority
        }
        return try .init(sessionToken: token, accountID: accountID, spaceID: spaceID)
    }
}

/// Inject the original app's masked WalletCreateSession/WalletCloseSession
/// calls. The create callback returns the actual response, including a token
/// whose account/scope is unexpected; the controller must close that token.
public struct AnyHeartNativeSourceSessionAuthority: Sendable {
    public typealias Create = @Sendable (_ expectedAccountID: String) async throws -> AnyHeartNativeSourceSessionGrant
    public typealias Close = @Sendable (_ ownedSessionToken: String) async throws -> Void
    fileprivate let create: Create
    fileprivate let close: Close

    public init(create: @escaping Create, close: @escaping Close) {
        self.create = create; self.close = close
    }
}

/// Owns the additional native account session used for one source review.
/// Invalidation drains real native work before closing only this owned token.
/// A close failure remains explicit and retryable; account/engine ownership
/// must not transfer until invalidate has returned successfully.
public actor AnyHeartNativeSourceAccountController {
    public enum State: Equatable, Sendable {
        case idle, acquiringSession, capturing, ready, validating
        case invalidating(AnyHeartNativeSourceCaptureCoordinator.InvalidationReason)
        case sessionCloseFailed
    }

    public private(set) var state: State = .idle
    private let authority: AnyHeartNativeSourceSessionAuthority
    private let bridge: AnyHeartNativeSourceBridge
    private let privateDirectory: URL
    private var lifecycleID: UUID?
    private var invalidation: AnyHeartNativeSourceCaptureCoordinator.InvalidationReason?
    private var grant: AnyHeartNativeSourceSessionGrant?
    private var coordinator: AnyHeartNativeSourceCaptureCoordinator?
    private var captureTask: Task<AnyHeartNativeSourceCaptureReview, Error>?
    private var validationTask: Task<Void, Error>?
    private var cleanupTask: Task<Void, Error>?

    public init(authority: AnyHeartNativeSourceSessionAuthority,
                bridge: AnyHeartNativeSourceBridge, privateDirectory: URL) throws {
        // Apply the same source-root contract before acquiring any authority.
        _ = try AnyHeartNativeSourceCaptureCoordinator(bridge: bridge, privateDirectory: privateDirectory)
        self.authority = authority; self.bridge = bridge; self.privateDirectory = privateDirectory
    }

    public func capture(accountID: String, spaceID: String) async throws -> AnyHeartNativeSourceCaptureReview {
        guard lifecycleID == nil, cleanupTask == nil, state == .idle else {
            throw AnyHeartNativeSourceAccountError.invalidLifecycle
        }
        guard [accountID, spaceID].allSatisfy({
            !$0.isEmpty && $0.utf8.count <= 4096 && !$0.contains("\0")
        }) else { throw AnyHeartNativeSourceAccountError.invalidAuthority }
        try Task.checkCancellation()
        let id = UUID()
        lifecycleID = id; invalidation = nil; state = .acquiringSession
        let task = Task { try await self.performCapture(id: id, accountID: accountID, spaceID: spaceID) }
        captureTask = task
        return try await withTaskCancellationHandler {
            do {
                let review = try await task.value
                try Task.checkCancellation()
                try requireActive(id)
                return review
            } catch {
                let original = error
                try await invalidate(id: id, reason: error is CancellationError ? .userCancelled : .released)
                throw original
            }
        } onCancel: {
            // The caller's catch also awaits this same cleanup, including a
            // late mint. This task only signals cancellation promptly.
            Task { try? await self.invalidate(id: id, reason: .userCancelled) }
        }
    }

    public func revalidate(source: AnyDestinationSourceBinding) async throws {
        guard state == .ready, let id = lifecycleID, let coordinator, invalidation == nil else {
            throw AnyHeartNativeSourceAccountError.inactiveCapture
        }
        try Task.checkCancellation()
        state = .validating
        let task = Task { try await self.performValidation(id: id, source: source, coordinator: coordinator) }
        validationTask = task
        try await withTaskCancellationHandler {
            do {
                try await task.value
                try Task.checkCancellation()
                try requireActive(id)
            } catch {
                let original = error
                try await invalidate(id: id, reason: error is CancellationError ? .userCancelled : .nativeValidationFailed)
                throw original
            }
        } onCancel: {
            Task { try? await self.invalidate(id: id, reason: .userCancelled) }
        }
    }

    public func invalidate(reason: AnyHeartNativeSourceCaptureCoordinator.InvalidationReason) async throws {
        guard let id = lifecycleID else { return }
        try await invalidate(id: id, reason: reason)
    }

    public func cancel() async throws { try await invalidate(reason: .userCancelled) }
    public func release() async throws { try await invalidate(reason: .released) }

    private func performCapture(id: UUID, accountID: String, spaceID: String) async throws -> AnyHeartNativeSourceCaptureReview {
        try Task.checkCancellation()
        try requireActive(id)
        let authority = self.authority
        // Do not cancel this task. Invocation checks cancellation after its
        // native call; cancelling it could hide a successfully minted token.
        let minted = try await Task.detached(priority: .userInitiated) {
            try await authority.create(accountID)
        }.value
        grant = minted
        try Task.checkCancellation()
        try requireActive(id)
        let session = try minted.session(expectedAccountID: accountID, spaceID: spaceID)
        let coordinator = try AnyHeartNativeSourceCaptureCoordinator(bridge: bridge, privateDirectory: privateDirectory)
        self.coordinator = coordinator; state = .capturing
        let review = try await coordinator.capture(session: session, requestID: "app-source-" + id.uuidString)
        try Task.checkCancellation()
        try requireActive(id)
        state = .ready
        return review
    }

    private func performValidation(id: UUID, source: AnyDestinationSourceBinding,
                                   coordinator: AnyHeartNativeSourceCaptureCoordinator) async throws {
        try await coordinator.revalidate(source: source)
        try Task.checkCancellation()
        try requireActive(id)
        state = .ready
    }

    private func requireActive(_ id: UUID) throws {
        guard lifecycleID == id, invalidation == nil else {
            throw AnyHeartNativeSourceAccountError.inactiveCapture
        }
    }

    private func invalidate(id: UUID, reason: AnyHeartNativeSourceCaptureCoordinator.InvalidationReason) async throws {
        guard lifecycleID == id else { return }
        if let cleanupTask { try await cleanupTask.value; return }
        invalidation = invalidation ?? reason
        state = .invalidating(invalidation ?? reason)
        let task = Task { try await self.drainAndClose(id: id) }
        cleanupTask = task
        try await task.value
    }

    private func drainAndClose(id: UUID) async throws {
        captureTask?.cancel(); validationTask?.cancel()
        if let coordinator { await coordinator.invalidate(invalidation ?? .released) }
        // Await completion even after cancellation. The native mint/capture/
        // validate callbacks can finish late and still own native resources.
        if let captureTask { _ = await captureTask.result }
        if let validationTask { _ = await validationTask.result }
        if let coordinator { await coordinator.invalidate(invalidation ?? .released) }
        if let grant, !grant.token.isEmpty {
            let authority = self.authority, token = grant.token
            do {
                // A caller cancelling its engine switch must not hide the
                // result of closing the token either.
                try await Task.detached { try await authority.close(token) }.value
            } catch {
                state = .sessionCloseFailed; cleanupTask = nil
                throw AnyHeartNativeSourceAccountError.sessionCloseFailed
            }
        }
        guard lifecycleID == id else { throw AnyHeartNativeSourceAccountError.invalidLifecycle }
        grant = nil; coordinator = nil; captureTask = nil; validationTask = nil
        lifecycleID = nil; invalidation = nil; cleanupTask = nil; state = .idle
    }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

public enum AnyHeartNativeSourceCaptureCoordinatorError: Error, Equatable, Sendable {
    case invalidSession, invalidRequest, invalidLifecycle, inactiveCapture, sourceBinding
}

/// This value is deliberately not Codable. A native session token is never
/// written to the captured bundle, migration journal or presentation model.
public struct AnyHeartNativeSourceSession: Sendable, CustomStringConvertible, CustomDebugStringConvertible {
    public let accountID: String
    public let spaceID: String
    fileprivate let token: String

    public init(sessionToken: String, accountID: String, spaceID: String) throws {
        guard !sessionToken.isEmpty, sessionToken.utf8.count <= 16_384, !sessionToken.contains("\0"),
              [accountID, spaceID].allSatisfy({ !$0.isEmpty && $0.utf8.count <= 4096 && !$0.contains("\0") }) else {
            throw AnyHeartNativeSourceCaptureCoordinatorError.invalidSession
        }
        self.token = sessionToken; self.accountID = accountID; self.spaceID = spaceID
    }

    public var description: String { "AnyHeartNativeSourceSession(redacted)" }
    public var debugDescription: String { description }
}

/// The shipping app injects its actual ServicePinkha* exports. Blocking Go
/// calls must run away from the main actor. No second native library is linked
/// by this shared module; cancellation/release use the same loaded runtime.
public struct AnyHeartNativeSourceBridge: Sendable {
    public typealias Capture = @Sendable (
        _ sessionToken: String, _ accountID: String, _ spaceID: String,
        _ privateDirectory: String, _ requestID: String
    ) async throws -> Data
    public typealias Validate = @Sendable (
        _ sessionToken: String, _ requestID: String, _ manifestSHA256: String
    ) async throws -> Void
    public typealias Control = @Sendable (_ sessionToken: String, _ requestID: String) -> Bool

    fileprivate let capture: Capture
    fileprivate let validate: Validate
    fileprivate let cancel: Control
    fileprivate let release: Control

    public init(capture: @escaping Capture, validate: @escaping Validate,
                cancel: @escaping Control, release: @escaping Control) {
        self.capture = capture; self.validate = validate
        self.cancel = cancel; self.release = release
    }
}

/// A review of the complete captured census. Successful capture and current
/// authorization do not turn a semantic draft into permission to migrate.
public struct AnyHeartNativeSourceCaptureReview: Sendable {
    public struct UnmappedObject: Sendable {
        public let sourceObjectID: String
        public let nativeType: Int64
        public let reason: String
    }

    public let descriptor: AnyHeartNativeCaptureDescriptor
    public let bundle: AnyHeartNativeSpaceBundle
    public let definitionPlan: AnyHeartNativeDefinitionPlan
    public let currentPagePlans: [AnyHeartNativePageComposition]
    public let unmappedObjects: [UnmappedObject]
    public let pinkhaSource: AnyHeartNativePinkhaSource?
    public let pinkhaSourceIssue: String?
    public var permitsDestinationWrites: Bool { false }

    fileprivate init(descriptor: AnyHeartNativeCaptureDescriptor, bundle: AnyHeartNativeSpaceBundle) throws {
        self.descriptor = descriptor; self.bundle = bundle
        let definitions = try AnyHeartNativeDefinitionPlan(catalog: .init(bundle: bundle))
        definitionPlan = definitions
        do {
            pinkhaSource = try AnyHeartNativePinkhaSource.discover(in: bundle)
            pinkhaSourceIssue = nil
        } catch {
            // Preserve the complete capture review when a source schema is
            // incomplete or ambiguous. No source error grants destination writes.
            pinkhaSource = nil
            pinkhaSourceIssue = String(describing: error)
        }
        let candidates = bundle.objects.filter {
            $0.nativeType == 16 && $0.objectTypes.count == 1 &&
            definitions.type(sourceURL: $0.objectTypes[0])?.definition.recommendedLayout == 0
        }
        let bindings = candidates.map {
            AnyHeartNativeDefinitionPlan.ObjectBinding(sourceObjectID: $0.sourceObjectID,
                destinationSourceKey: AnyHeartNativePageComposition.objectSourceKey(
                    spaceID: bundle.sourceSpaceID, objectID: $0.sourceObjectID))
        }
        var pages: [AnyHeartNativePageComposition] = [], unmapped: [UnmappedObject] = []
        let definitionIDs = Set((definitions.catalog.types.map(\.objectID) +
            definitions.catalog.relations.map(\.objectID) + definitions.catalog.options.map(\.objectID)).map { Data($0.utf8) })
        for object in bundle.objects where !definitionIDs.contains(Data(object.sourceObjectID.utf8)) {
            try Task.checkCancellation()
            guard candidates.contains(where: { Data($0.sourceObjectID.utf8) == Data(object.sourceObjectID.utf8) }) else {
                unmapped.append(.init(sourceObjectID: object.sourceObjectID, nativeType: object.nativeType,
                    reason: "native-object-kind-or-layout-has-no-qualified-current-page-map"))
                continue
            }
            do {
                pages.append(try .init(bundle: bundle, sourceObjectID: object.sourceObjectID,
                                       definitions: definitions, objects: bindings))
            } catch {
                unmapped.append(.init(sourceObjectID: object.sourceObjectID, nativeType: object.nativeType,
                                      reason: String(describing: error)))
            }
        }
        let snapshotIDs = Set(bundle.objects.map { Data($0.sourceObjectID.utf8) })
        for tree in bundle.trees where !snapshotIDs.contains(Data(tree.objectID.utf8)) {
            unmapped.append(.init(sourceObjectID: tree.objectID, nativeType: tree.nativeType,
                reason: tree.status + ":native-settings-history-or-tombstone-mapping-required"))
        }
        if let census = bundle.nativeStoreContext?.headCensus {
            unmapped.append(.init(sourceObjectID: census.nativeACLID, nativeType: -1,
                reason: "native-acl-original-retained:destination-permissions-mapping-required"))
        }
        currentPagePlans = pages; unmappedObjects = unmapped
    }

    /// Bind a future full semantic plan to this exact original source census.
    /// This creates no destination plan and bypasses no semantic coverage gate.
    public func sourceBinding(semanticPlanSHA256: String) throws -> AnyDestinationSourceBinding {
        try .init(bundle: bundle, semanticPlanSHA256: semanticPlanSHA256)
    }

    fileprivate func requireSameSource(_ source: AnyDestinationSourceBinding) throws {
        func exact(_ a: String, _ b: String) -> Bool { Data(a.utf8) == Data(b.utf8) }
        guard let census = bundle.nativeStoreContext?.headCensus,
              exact(source.accountID, bundle.sourceAccountID), exact(source.spaceID, bundle.sourceSpaceID),
              source.captureManifestSHA256 == bundle.manifestSHA256,
              source.witnessSHA256 == bundle.sourceWitnessSHA256,
              source.definitionManifestBytes == bundle.manifestBytes,
              Set(source.sourceObjectIDs.map { Data($0.utf8) }) ==
                Set(census.sourceHeadIDs.map { Data($0.utf8) }) else {
            throw AnyHeartNativeSourceCaptureCoordinatorError.sourceBinding
        }
    }
}

/// Owns one capture lifecycle. Create a new coordinator for a new capture,
/// including after process restart. Invalidate it on account or engine switch.
/// Native cancellation is cooperative; a late reply is discarded and released.
public actor AnyHeartNativeSourceCaptureCoordinator {
    public enum InvalidationReason: Equatable, Sendable {
        case accountChanged, engineChanged, userCancelled, released, nativeValidationFailed
    }
    public enum State: Equatable, Sendable {
        case idle, capturing, ready, validating, failed
        case invalidated(InvalidationReason)
    }

    public private(set) var state: State = .idle
    private let bridge: AnyHeartNativeSourceBridge
    private let privateDirectory: URL
    private var session: AnyHeartNativeSourceSession?
    private var requestID: String?
    private var review: AnyHeartNativeSourceCaptureReview?
    private var pendingRead: Task<AnyHeartNativeSourceCaptureReview, Error>?

    public init(bridge: AnyHeartNativeSourceBridge, privateDirectory: URL) throws {
        guard privateDirectory.isFileURL, privateDirectory.path.hasPrefix("/"),
              !privateDirectory.path.contains("\0") else {
            throw AnyHeartNativeCaptureError.privateDirectory
        }
        self.bridge = bridge; self.privateDirectory = privateDirectory
    }

    public func capture(session: AnyHeartNativeSourceSession,
                        requestID: String) async throws -> AnyHeartNativeSourceCaptureReview {
        guard state == .idle else { throw AnyHeartNativeSourceCaptureCoordinatorError.invalidLifecycle }
        guard !requestID.isEmpty, requestID.utf8.count <= 128, requestID.utf8.allSatisfy({
            (48...57).contains($0) || (65...90).contains($0) || (97...122).contains($0) || $0 == 45 || $0 == 95
        }) else { throw AnyHeartNativeSourceCaptureCoordinatorError.invalidRequest }
        try Task.checkCancellation()
        self.session = session; self.requestID = requestID; state = .capturing
        let bridge = self.bridge, parent = privateDirectory
        do {
            let bytes = try await withTaskCancellationHandler {
                try await bridge.capture(session.token, session.accountID, session.spaceID, parent.path, requestID)
            } onCancel: { _ = bridge.cancel(session.token, requestID) }
            try Task.checkCancellation()
            guard state == .capturing else { throw AnyHeartNativeSourceCaptureCoordinatorError.inactiveCapture }
            let read = Task.detached(priority: .userInitiated) {
                let descriptor = try AnyHeartNativeCaptureDescriptor(data: bytes,
                    expectedAccountID: session.accountID, expectedSpaceID: session.spaceID, expectedRequestID: requestID)
                let bundle = try descriptor.loadBundle(under: parent)
                return try AnyHeartNativeSourceCaptureReview(descriptor: descriptor, bundle: bundle)
            }
            pendingRead = read
            let result = try await withTaskCancellationHandler { try await read.value }
                onCancel: { read.cancel(); _ = bridge.cancel(session.token, requestID) }
            pendingRead = nil
            try Task.checkCancellation()
            guard state == .capturing else { throw AnyHeartNativeSourceCaptureCoordinatorError.inactiveCapture }
            review = result; state = .ready
            return result
        } catch {
            pendingRead?.cancel(); pendingRead = nil
            _ = bridge.release(session.token, requestID)
            if state == .capturing {
                state = error is CancellationError ? .invalidated(.userCancelled) : .failed
            }
            self.session = nil; self.requestID = nil; review = nil
            throw error
        }
    }

    /// Supply this to the executor's verifySource callback. This is a fresh
    /// native authority/checkpoint read, separate from semantic admission and
    /// from the destination's own authorization callback.
    public func revalidate(source: AnyDestinationSourceBinding) async throws {
        guard state == .ready, let session, let requestID, let review else {
            throw AnyHeartNativeSourceCaptureCoordinatorError.inactiveCapture
        }
        try review.requireSameSource(source)
        try Task.checkCancellation()
        state = .validating
        let bridge = self.bridge
        do {
            try await withTaskCancellationHandler {
                try await bridge.validate(session.token, requestID, review.descriptor.manifestSHA256)
            } onCancel: { _ = bridge.cancel(session.token, requestID) }
            try Task.checkCancellation()
            guard state == .validating else { throw AnyHeartNativeSourceCaptureCoordinatorError.inactiveCapture }
            state = .ready
        } catch {
            if state == .validating {
                state = .invalidated(error is CancellationError ? .userCancelled : .nativeValidationFailed)
            }
            _ = bridge.release(session.token, requestID)
            self.session = nil; self.requestID = nil; self.review = nil
            throw error
        }
    }

    /// Releases only native metadata/cancellation slots. Original source
    /// files are retained for review and recovery; no source account is closed.
    public func invalidate(_ reason: InvalidationReason) {
        state = .invalidated(reason)
        pendingRead?.cancel(); pendingRead = nil
        if let session, let requestID {
            _ = bridge.cancel(session.token, requestID)
            _ = bridge.release(session.token, requestID)
        }
        session = nil; requestID = nil; review = nil
    }

    public func cancel() { invalidate(.userCancelled) }
    public func release() { invalidate(.released) }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

/// Imports the supported current content and preserves every original native
/// head in an immutable, typed source catalog backed by a reversible file.
/// This deliberately does not activate unused types, replace native ACLs,
/// transplant source history into target history, or admit unsupported layouts.
public struct AnyHeartNativeSourcePreservation: Sendable {
    public static let contract = "pinkha-heart-native-source-preservation-v1"
    public static let capturedContract = "pinkha-heart-native-source-preservation-v2"
    public static let datasetKey = "heart_source_catalog"
    public struct Record: Sendable {
        public let sourceHeadID: String
        public let role: String
        public let sourceKey: String
        public let snapshotSHA256: String?
        public let jsonViewSHA256: String?
    }
    public let bundle: AnyHeartNativeSpaceBundle
    public let definitionEvidence: AnyHeartNativeDefinitionEvidence
    public var recoveredDefinitions: AnyHeartNativeRecoveredDefinitions? { definitionEvidence.recoveredDefinitions }
    public var preservationContract: String {
        definitionEvidence.kind == .recoveredOriginal ? Self.contract : Self.capturedContract
    }
    public let currentContent: AnyHeartNativeContentComposition
    public let archive: AnyHeartNativePreservationArchive
    public let records: [Record]
    public let uninstantiatedDefinitionIDs: [String]
    public let preservedContextIDs: [String]
    public let items: [AnyDestinationMigrationItem]
    public let coverage: [AnyDestinationCoverage]
    public let contentSHA256: String
    public let archiveItemSourceKey: String
    public let catalogObjectSourceKey: String
    public let catalogTypeSourceKey: String
    public var allImportedTypesUsable: Bool { false }
    public var permitsWholeSourceAdmission: Bool { false }
    public var changesDestinationACL: Bool { false }
    public var sourceHistoryBecameTargetHistory: Bool { false }

    public init(bundle: AnyHeartNativeSpaceBundle, recoveredDefinitions: AnyHeartNativeRecoveredDefinitions,
                archive: AnyHeartNativePreservationArchive) throws {
        try self.init(bundle: bundle, definitionEvidence: .recoveredOriginal(recoveredDefinitions), archive: archive)
    }

    /// Only a complete directly captured descriptor census can use this route.
    /// It does not construct or relax the historical recovery envelope.
    public init(capturedBundle bundle: AnyHeartNativeSpaceBundle,
                archive: AnyHeartNativePreservationArchive) throws {
        try self.init(bundle: bundle, definitionEvidence: .capturedComplete, archive: archive)
    }

    public init(bundle: AnyHeartNativeSpaceBundle, definitionEvidence: AnyHeartNativeDefinitionEvidence,
                archive: AnyHeartNativePreservationArchive) throws {
        let catalog = try definitionEvidence.catalog(bundle: bundle)
        let expectedArchive: AnyHeartNativePreservationArchive.Binding
        switch definitionEvidence {
        case .recoveredOriginal(let recovered): expectedArchive = try .init(bundle: bundle, recovered: recovered)
        case .capturedComplete: expectedArchive = try .init(capturedBundle: bundle)
        }
        let recovery = definitionEvidence.recoveredDefinitions
        let contract = definitionEvidence.kind == .recoveredOriginal ? Self.contract : Self.capturedContract
        guard archive.binding == expectedArchive,
              let context = bundle.nativeStoreContext, let census = context.headCensus,
              context.unmappedCollectionNames.isEmpty, bundle.sourceGaps.isEmpty,
              bundle.resolverUnmapped.isEmpty, bundle.fileVariants.isEmpty, bundle.fileReferences.isEmpty,
              bundle.issues.allSatisfy({
                  definitionEvidence.kind == .recoveredOriginal &&
                  $0.code == "compiled-definition-descriptors-not-captured" && $0.field == "BundledDefinitionsUsed"
              }) else { throw AnyDestinationMigrationError.invalidPlan("full preservation source contract") }
        // Reconstruct every member from the actual file. The v1 route includes
        // independently qualified recovery; the v2 route has capture members only.
        let decoded = try AnyHeartNativePreservationArchive.restore(archive.bytes, expected: archive.binding)
        guard decoded.bundle.manifestBytes == bundle.manifestBytes,
              decoded.definitionEvidence.kind == definitionEvidence.kind,
              decoded.recoveredDefinitions?.manifestBytes == recovery?.manifestBytes else {
            throw AnyDestinationMigrationError.changedSource
        }
        let current = try AnyHeartNativeContentComposition(bundle: bundle)
        _ = try current.definitions.admittedSchemaItems()
        for page in current.pages { _ = try page.admittedSelectedItems(current.selection) }
        let activeIDs = Set(current.selection.executedSourceObjectIDs.map { Data($0.utf8) })
        let contentIDs = Set(current.selection.objects.map { Data($0.sourceObjectID.utf8) })
        let selectedTypeIDs = Set(current.definitions.types.map { Data($0.definition.objectID.utf8) })
        let byID = Dictionary(uniqueKeysWithValues: bundle.objects.map { (Data($0.sourceObjectID.utf8), $0) })
        let trees = Dictionary(uniqueKeysWithValues: bundle.trees.map { (Data($0.objectID.utf8), $0) })
        let definitionIDs = Set((catalog.types.map(\.objectID) + catalog.relations.map(\.objectID) +
                                 catalog.options.map(\.objectID)).map { Data($0.utf8) })
        let unused = definitionIDs.subtracting(activeIDs)
        // Only actual content instances participate in this proof. Definition
        // objects use their own meta-types; empty Home/Archive/Workspace/Widgets
        // are preserved as source context, never invented destination objects.
        for object in current.selection.objects {
            guard let captured = byID[Data(object.sourceObjectID.utf8)],
                  captured.objectTypes.count == 1,
                  let type = catalog.type(url: captured.objectTypes[0]),
                  selectedTypeIDs.contains(Data(type.objectID.utf8)),
                  !unused.contains(Data(type.objectID.utf8)) else {
                throw AnyDestinationMigrationError.invalidPlan("uninstantiated definition proof")
            }
        }
        var contexts: [String] = []
        for object in bundle.objects {
            let id = Data(object.sourceObjectID.utf8)
            if definitionIDs.contains(id) || contentIDs.contains(id) { continue }
            let known: [Int64: String] = [32: "home", 48: "archive", 518: "ws", 112: "widget"]
            guard known[object.nativeType].map({ Data($0.utf8) == Data(object.uniqueKey.utf8) }) == true,
                  object.blocks.count == 1, object.blocks[0].contentKind == "smartblock",
                  object.blocks[0].childIDs.isEmpty, object.issues.isEmpty else {
                throw AnyDestinationMigrationError.incompleteCoverage("unsupported instantiated source object")
            }
            contexts.append(object.sourceObjectID)
        }
        guard byID.count == bundle.objects.count, let anchor = current.selection.objects.first else {
            throw AnyDestinationMigrationError.invalidPlan("source catalog anchor")
        }
        let suffix = AnyContentDigest.sha256(AnyPreparedMigrationPlanBinding.material([
            contract, bundle.manifestSHA256, recovery?.manifestSHA256 ?? definitionEvidence.kind.rawValue,
        ]))
        let typeKey = "heart-source-catalog-type:" + suffix
        let objectKey = "heart-source-catalog-object:" + suffix
        let fileKey = "heart-source-catalog-file:" + suffix
        let owner = AnyDestinationReference.mapped(sourceKey: typeKey, slot: .objectID, encoding: .rawID)
        let object = AnyDestinationReference.mapped(sourceKey: objectKey, slot: .objectID, encoding: .rawID)
        let definitionField = definitionEvidence.kind == .recoveredOriginal
            ? "sourceRecoveryManifestSHA256" : "sourceDefinitionEvidence"
        let definitionValue = recovery?.manifestSHA256 ?? definitionEvidence.kind.rawValue
        let ordinaryStrings = ["sourceHeadID", "sourceRole", "sourceNativeType", "sourceUniqueKey",
            "sourceTreeJSON", "sourceSnapshotBase64", "sourceViewJSON", "sourceSnapshotSHA256",
            "sourceViewSHA256", "sourceCaptureManifestSHA256", definitionField, "archiveURI"]
        let fields: [AnyJSON] = ordinaryStrings.map {
            .object(["key": .string($0), "kind": .string("string"), "required": .bool(true)])
        } + [.object(["key": .string("snapshotPresent"), "kind": .string("boolean"), "required": .bool(true)]),
             .object(["key": .string("importedBy"), "stamp": .string("creator")]),
             .object(["key": .string("importedAt"), "stamp": .string("createTime")])]
        var added: [AnyDestinationMigrationItem] = [
            .init(sourceKey: typeKey, sourceObjectID: anchor.sourceObjectID, operation: .typeDefinition(.init(
                xKey: "heart_source_catalog_" + suffix, name: "Original Heart source catalog",
                description: "Immutable source definitions, context and provenance; unsupported types remain inactive.",
                meta: .literal(.object(["preservationContract": .string(contract),
                    "sourceCaptureManifestSHA256": .string(bundle.manifestSHA256),
                    definitionField: .string(definitionValue)]))))),
            .init(sourceKey: typeKey + ":records-part", sourceObjectID: anchor.sourceObjectID,
                expectedRecordCount: fields.count + 2,
                operation: .partDefinition(owner: owner, draft: .literal(.object([
                    "key": .string(Self.datasetKey), "name": .string("Original source records"),
                    "datasets": .array([.object(["key": .string(Self.datasetKey), "module": .string("records"),
                        "deleteBy": .string("none"), "fields": .array(fields)])]),
                ])))),
            .init(sourceKey: objectKey, sourceObjectID: anchor.sourceObjectID,
                operation: .object(type: owner, collections: [], initialProperties: .literal(.object([
                    "any": .object(["name": .string("Original Heart source")]),
                ])))),
            .init(sourceKey: fileKey, sourceObjectID: anchor.sourceObjectID,
                operation: .file(owner: object, name: "Original Heart source.pinkha-heart-source",
                    mime: AnyHeartNativePreservationArchive.mimeType, size: Int64(archive.bytes.count),
                    contentSHA256: archive.sha256)),
        ]
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        func jsonText(_ value: AnyJSON) throws -> String {
            String(decoding: try encoder.encode(value), as: UTF8.self)
        }
        var records: [Record] = []
        let headIDs = census.sourceHeadIDs.sorted { Data($0.utf8).lexicographicallyPrecedes(Data($1.utf8)) }
        guard Set(headIDs.map { Data($0.utf8) }).count == headIDs.count else {
            throw AnyDestinationMigrationError.invalidPlan("duplicate native source head")
        }
        for id in headIDs {
            let rawID = Data(id.utf8), snapshot = byID[Data(id.utf8)], tree = trees[Data(id.utf8)]
            let role: String
            if let snapshot {
                guard tree != nil else { throw AnyDestinationMigrationError.invalidPlan("snapshot without native tree") }
                if contentIDs.contains(rawID) { role = "active-current-content" }
                else if definitionIDs.contains(rawID) {
                    let base: String
                    switch snapshot.nativeType {
                    case 521: base = "relation-definition"
                    case 528: base = "type-definition"
                    case 529: base = "relation-option"
                    default: throw AnyDestinationMigrationError.invalidPlan("definition native kind")
                    }
                    role = (unused.contains(rawID) ? "uninstantiated-" : "active-schema-") + base
                } else if contexts.contains(where: { Data($0.utf8) == rawID }) {
                    role = "source-context"
                } else { throw AnyDestinationMigrationError.incompleteCoverage(id) }
            } else if let tree {
                guard tree.nativeType == -1, tree.status == "space-settings-retained" else {
                    throw AnyDestinationMigrationError.incompleteCoverage("unrepresented native source tree")
                }
                role = "original-space-settings"
            } else if rawID == Data(census.nativeACLID.utf8), census.capturedACLRowCount > 0 {
                role = "original-native-acl"
            } else if census.defaultKeyValueID.map({ Data($0.utf8) == rawID }) == true,
                      context.classification(named: id)?.kind == .emptyDefaultKeyValue {
                role = "original-empty-native-kv"
            } else { throw AnyDestinationMigrationError.incompleteCoverage("unrepresented native source head") }
            let recordKey = "heart-source-catalog-record:" + AnyContentDigest.sha256(
                AnyPreparedMigrationPlanBinding.material([suffix, id]))
            let literals: [String: AnyJSON] = [
                "sourceHeadID": .string(id), "sourceRole": .string(role),
                "sourceNativeType": .string(tree.map { String($0.nativeType) } ?? ""),
                "sourceUniqueKey": .string(snapshot?.uniqueKey ?? ""),
                "sourceTreeJSON": .string(try jsonText(tree?.raw ?? .null)),
                "snapshotPresent": .bool(snapshot != nil),
                "sourceSnapshotBase64": .string(snapshot?.protobufBytes.base64EncodedString() ?? ""),
                "sourceViewJSON": .string(snapshot.map { String(decoding: $0.jsonViewBytes, as: UTF8.self) } ?? ""),
                "sourceSnapshotSHA256": .string(snapshot?.snapshotSHA256 ?? ""),
                "sourceViewSHA256": .string(snapshot?.viewSHA256 ?? ""),
                "sourceCaptureManifestSHA256": .string(bundle.manifestSHA256),
                definitionField: .string(definitionValue),
            ]
            // Stay below the existing native immutable-record request bound,
            // including the actual resolved file URI and JSON envelope.
            guard try encoder.encode(AnyJSON.object(literals)).count <= 192 * 1024 else {
                throw AnyDestinationMigrationError.invalidPlan("preserved source row size")
            }
            let values = AnyDestinationValue.object(literals.keys.sorted().map {
                .init(key: .native($0), value: .literal(literals[$0]!))
            } + [.init(key: .native("archiveURI"),
                value: .reference(.mapped(sourceKey: fileKey, slot: .fileID, encoding: .fileURI)))])
            added.append(.init(sourceKey: recordKey, sourceObjectID: id,
                operation: .immutableRecord(object: object, ownerType: owner, datasetKey: Self.datasetKey, values: values)))
            records.append(.init(sourceHeadID: id, role: role, sourceKey: recordKey,
                snapshotSHA256: snapshot?.snapshotSHA256, jsonViewSHA256: snapshot?.viewSHA256))
        }
        guard Set(bundle.objects.map { Data($0.sourceObjectID.utf8) }).isSubset(of: Set(headIDs.map { Data($0.utf8) })) else {
            throw AnyDestinationMigrationError.invalidPlan("snapshot outside native source census")
        }
        let items = (current.items + added).enumerated().sorted {
            let left = $0.element.operation.phase, right = $1.element.operation.phase
            return left == right ? $0.offset < $1.offset : left < right
        }.map(\.element)
        let activeCoverage = Dictionary(uniqueKeysWithValues:
            current.coverage.map { (Data($0.sourceObjectID.utf8), $0.disposition) })
        let coverage = headIDs.map { id -> AnyDestinationCoverage in
            let keys = items.filter { Data($0.sourceObjectID.utf8) == Data(id.utf8) }.map(\.sourceKey)
            let disposition: AnyDestinationCoverage.Disposition
            switch activeCoverage[Data(id.utf8)] {
            case .canonicalProperty(let binding):
                disposition = .preservedCanonicalProperty(binding, immutableItemSourceKeys: keys)
            case .embeddedOption(let propertyKey, let evidence, let descriptorSHA256):
                disposition = .preservedEmbeddedOption(propertySourceKey: propertyKey, evidence: evidence,
                    descriptorSHA256: descriptorSHA256, immutableItemSourceKeys: keys)
            default: disposition = .mapped(itemSourceKeys: keys)
            }
            return .init(sourceObjectID: id, disposition: disposition)
        }
        struct Material: Encodable {
            let contract: String
            let sourceManifestSHA256: String
            let recoveredManifestSHA256: String?
            let definitionEvidence: String?
            let currentContentSHA256: String
            let archiveSHA256: String
            let unusedDefinitionIDs: [String]
            let sourceContextIDs: [String]
            let allImportedTypesUsable: Bool
            let items: [AnyDestinationMigrationItem]
            let coverage: [AnyDestinationCoverage]
        }
        let unusedIDs = unused.map { String(decoding: $0, as: UTF8.self) }.sorted {
            Data($0.utf8).lexicographicallyPrecedes(Data($1.utf8))
        }
        contexts.sort { Data($0.utf8).lexicographicallyPrecedes(Data($1.utf8)) }
        let material = try encoder.encode(Material(contract: contract,
            sourceManifestSHA256: bundle.manifestSHA256, recoveredManifestSHA256: recovery?.manifestSHA256,
            definitionEvidence: definitionEvidence.kind == .capturedComplete ? definitionEvidence.kind.rawValue : nil,
            currentContentSHA256: current.contentSHA256, archiveSHA256: archive.sha256,
            unusedDefinitionIDs: unusedIDs, sourceContextIDs: contexts,
            allImportedTypesUsable: false, items: items, coverage: coverage))
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: material, encoded: material)
        self.bundle = bundle; self.definitionEvidence = definitionEvidence; currentContent = current
        self.archive = archive; self.records = records; uninstantiatedDefinitionIDs = unusedIDs
        preservedContextIDs = contexts; self.items = items; self.coverage = coverage
        contentSHA256 = AnyContentDigest.sha256(material)
        archiveItemSourceKey = fileKey; catalogObjectSourceKey = objectKey; catalogTypeSourceKey = typeKey
    }

    /// Explicit full-source preservation scope. The live-source coordinator's
    /// existing semantic admission remains unchanged and cannot accept this as
    /// a claim that every retained source type/layout is usable.
    public func preservationPlan(workspace: AnyTorahWorkspace, storeID: String,
                                 planID: String) throws -> AnyDestinationMigrationPlan {
        // Independently reconstruct the accepted active-content source/coverage
        // contract; do not replace canonical property proofs with catalog rows.
        _ = try currentContent.currentContentPlan(workspace: workspace, storeID: storeID,
                                                  planID: planID)
        return try .init(source: .init(bundle: bundle, semanticPlanSHA256: contentSHA256),
            workspace: workspace, storeID: storeID, planID: planID, coverage: coverage, items: items)
    }
}

