import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

public enum AnyNativeImportedCatalogError: Error, Equatable, Sendable {
    case invalidOriginalPlan
    case missingHead(String)
    case snapshotNotCaptured(String)
    case changedSource(String)
}

/// The original immutable catalog record. Its address identifies retained
/// source data, never a replacement destination Type or writable property.
public struct AnyNativeImportedCatalogEntry: Sendable {
    public let sourceObjectID: String
    public let objectID: String
    public let ownerTypeID: String
    public let dataset: String
    public let recordID: String
    public let role: String
    public let nativeTypeText: String
    public let sourceUniqueKey: String
    public let definitionEvidenceKind: AnyHeartNativeDefinitionEvidence.Kind
    public let archiveURI: String
    /// nil means this source head has no captured object snapshot. Its exact
    /// retained row can still be inspected without inventing an empty object.
    public let evidence: AnyDestinationDefinitionEvidence?
    public let originalTreeJSON: Data
    public var permitsDestinationWrites: Bool { false }
    let sourceKey: String
    let values: [String: AnyJSON]
    let mapping: AnyDestinationMigrationMapping
}

/// Routes the complete original catalog from its already committed plan. No
/// original operation is prepared or replayed. Native reads subsequently bind
/// each address to the original immutable intent and signed creation.
public struct AnyNativeImportedCatalogDirectory: Sendable {
    public let binding: AnyPreparedMigrationPlanBinding
    public let source: AnyDestinationSourceBinding
    public let entries: [AnyNativeImportedCatalogEntry]
    public var permitsWholeSourceAdmission: Bool { false }
    private let byID: [Data: AnyNativeImportedCatalogEntry]

    public init(plan: AnyDestinationMigrationPlan, mappings: [AnyDestinationMigrationMapping]) throws {
        // These existing constructors validate complete mapping cardinality,
        // ordered source keys, signed IDs and every retained Page source fact.
        _ = try AnyNativeImportedDefinitionDirectory(plan: plan, mappings: mappings)
        _ = try AnyNativeImportedSourceFactsDirectory(plan: plan, mappings: mappings)
        guard !plan.source.definitionMembers.isEmpty else { throw AnyNativeImportedCatalogError.invalidOriginalPlan }
        var keyed: [Data: AnyDestinationMigrationMapping] = [:]
        for mapping in mappings {
            guard keyed.updateValue(mapping, forKey: Data(mapping.sourceKey.utf8)) == nil else {
                throw AnyNativeImportedCatalogError.invalidOriginalPlan
            }
        }
        let immutableMappings = keyed
        var catalog: [Data: AnyNativeImportedCatalogEntry] = [:], addresses = Set<Data>()
        for (index, item) in plan.items.enumerated() {
            let operation = try item.operation.resolved(destinationSpaceID: plan.binding.workspace.spaceID) {
                try AnyDestinationMigrationVerifier.resolve($0, in: immutableMappings,
                    destinationSpaceID: plan.binding.workspace.spaceID)
            }
            guard case .immutableRecord(.native(let object), .native(let owner), let key, .literal(let raw)) = operation,
                  key == AnyHeartNativeSourcePreservation.datasetKey else { continue }
            let mapping = mappings[index]
            guard let values = raw.object,
                  let definitionKind = AnyNativeImportedCatalogChecks.definitionKind(values),
                  mapping.recordIDs.count == 1, mapping.signedChangeIDs.count == 1, mapping.fileID == nil,
                  AnyNativeImportedCatalogChecks.same(mapping.objectID, object),
                  values["sourceHeadID"]?.string.map({ AnyNativeImportedCatalogChecks.same($0, item.sourceObjectID) }) == true,
                  values["sourceCaptureManifestSHA256"] == .string(plan.source.captureManifestSHA256),
                  let captured = values["snapshotPresent"]?.bool,
                  case .immutableRecord(_, let originalOwner, _, _) = item.operation else {
                throw AnyNativeImportedCatalogError.invalidOriginalPlan
            }
            try AnyDestinationImmutableRecordChecks.requireOwnedDeclaration(items: plan.items,
                ownerType: originalOwner, datasetKey: key, values: .literal(raw))
            let dataset = try AnyPreparedImmutableRecordIntent.ownedDataset(ownerTypeID: owner, key: key)
            let address = AnyPreparedMigrationPlanBinding.material([object, dataset, mapping.recordIDs[0]])
            guard addresses.insert(address).inserted else { throw AnyNativeImportedCatalogError.invalidOriginalPlan }
            let evidence = try AnyNativeImportedCatalogChecks.evidence(values, source: plan.source,
                sourceObjectID: item.sourceObjectID, captured: captured)
            let tree = Data(values["sourceTreeJSON"]!.string!.utf8)
            guard tree.count <= 262_144 else { throw AnyEngineError.readLimit }
            let parsedTree = try JSONDecoder().decode(AnyJSON.self, from: tree)
            try AnyTorahSourceJSONGuard.validateRoundTrip(original: tree,
                encoded: AnyDestinationDefinitionChecks.bytes(parsedTree))
            let entry = AnyNativeImportedCatalogEntry(sourceObjectID: item.sourceObjectID, objectID: object,
                ownerTypeID: owner, dataset: dataset, recordID: mapping.recordIDs[0],
                role: values["sourceRole"]!.string!, nativeTypeText: values["sourceNativeType"]!.string!,
                sourceUniqueKey: values["sourceUniqueKey"]!.string!, definitionEvidenceKind: definitionKind,
                archiveURI: values["archiveURI"]!.string!,
                evidence: evidence, originalTreeJSON: tree, sourceKey: item.sourceKey, values: values, mapping: mapping)
            guard catalog.updateValue(entry, forKey: Data(item.sourceObjectID.utf8)) == nil else {
                throw AnyNativeImportedCatalogError.invalidOriginalPlan
            }
        }
        guard Set(catalog.keys) == Set(plan.source.sourceObjectIDs.map({ Data($0.utf8) })),
              Set(catalog.values.filter({ $0.evidence != nil }).map({ Data($0.sourceObjectID.utf8) })) ==
                Set(plan.source.definitionMembers.keys) else {
            throw AnyNativeImportedCatalogError.invalidOriginalPlan
        }
        self.binding = plan.binding; self.source = plan.source; self.byID = catalog
        entries = catalog.values.sorted {
            Data($0.sourceObjectID.utf8).lexicographicallyPrecedes(Data($1.sourceObjectID.utf8))
        }
    }

    public func entry(sourceObjectID: String) -> AnyNativeImportedCatalogEntry? { byID[Data(sourceObjectID.utf8)] }
}

public struct AnyNativeImportedCatalogSnapshot: Sendable {
    public let workspace: AnyTorahWorkspace
    public let generation: UUID
    public let engineStartedAt: String
    public let sourceAccountID: String
    public let sourceWitnessSHA256: String
    public let sourceManifestSHA256: String
    public let entry: AnyNativeImportedCatalogEntry
    /// This is the destination import signer and clock, not source authorship.
    public let creation: AnyNativeImportedSourceFactsCreation
    public let raw: AnyJSON
    public var permitsDestinationWrites: Bool { false }
    public var originalHistoryReconstructed: Bool { false }
    public var provesCurrentSourceValues: Bool { false }
}

/// A read-only facade over the existing immutable records, history and native
/// membership APIs. It preserves all source snapshots/unknown fields and the
/// no-snapshot distinction. Equal reads bound one local observation; no atomic
/// whole-Space, source-history decryption or cross-peer barrier is asserted.
public struct AnyNativeImportedCatalogStore: Sendable {
    public let workspace: AnyTorahWorkspace
    private let client: AnyHTTPClient

    public init(client: AnyHTTPClient, workspace: AnyTorahWorkspace) throws {
        guard AnyNativeImportedCatalogChecks.same(client.expectedAccountID, workspace.accountID) else {
            throw AnyHostError.wrongWorkspace
        }
        self.client = client; self.workspace = workspace
    }

    public func read(sourceObjectID: String, directory: AnyNativeImportedCatalogDirectory,
                     lease: AnyHostLease) async throws -> AnyNativeImportedCatalogSnapshot {
        try await validate(directory, lease: lease)
        guard let entry = directory.entry(sourceObjectID: sourceObjectID) else {
            throw AnyNativeImportedCatalogError.missingHead(sourceObjectID)
        }
        try await membership(lease)
        let reader = try await AnyNativePreparedImmutableRecord.open(client: client, workspace: workspace,
            authorize: { try await lease.validate() })
        let schema = try await reader.schema(ownerTypeID: entry.ownerTypeID, dataset: entry.dataset,
            authorize: { try await lease.validate() })
        try AnyNativeImportedCatalogChecks.schema(schema, definitionEvidenceKind: entry.definitionEvidenceKind)
        let intent = try AnyPreparedImmutableRecordIntent(binding: directory.binding, sourceKey: entry.sourceKey,
            objectID: entry.objectID, schema: schema, values: entry.values)
        guard intent.intentID == entry.mapping.intentID else { throw AnyNativeImportedCatalogError.changedSource(sourceObjectID) }
        let before = try await reader.status(intent, authorize: { try await lease.validate() })
        try AnyNativeImportedCatalogChecks.receipt(before, entry: entry)
        let first = try await row(entry, lease: lease)
        let authority = try await creation(entry, intent: intent, lease: lease)
        let observed = try AnyDestinationMigrationVerifier.immutableRecordProjection(first, intent: intent, authority: authority)
        let original = try AnyDestinationMigrationVerifier.immutableRecordProjection(authority.recordAtChange,
            intent: intent, authority: authority)
        guard try AnyDestinationDefinitionChecks.bytes(observed) == AnyDestinationDefinitionChecks.bytes(original),
              let values = observed["values"]?.object,
              try AnyDestinationDefinitionChecks.bytes(.object(values)) == AnyDestinationDefinitionChecks.bytes(.object(entry.values)) else {
            throw AnyNativeImportedCatalogError.changedSource(sourceObjectID)
        }
        let second = try await row(entry, lease: lease)
        let after = try await reader.status(intent, authorize: { try await lease.validate() })
        try AnyNativeImportedCatalogChecks.receipt(after, entry: entry)
        guard before == after,
              try AnyDestinationDefinitionChecks.bytes(first) == AnyDestinationDefinitionChecks.bytes(second) else {
            throw AnyNativeImportedCatalogError.changedSource(sourceObjectID)
        }
        try await membership(lease)
        try await validate(directory, lease: lease)
        return .init(workspace: workspace, generation: lease.generation, engineStartedAt: lease.engineStartedAt,
            sourceAccountID: directory.source.accountID, sourceWitnessSHA256: directory.source.witnessSHA256,
            sourceManifestSHA256: directory.source.captureManifestSHA256, entry: entry,
            creation: .init(changeID: authority.changeID, destinationAuthor: authority.author,
                destinationAuthorClockSeconds: authority.timestampSeconds), raw: second)
    }

    private func validate(_ directory: AnyNativeImportedCatalogDirectory, lease: AnyHostLease) async throws {
        for candidate in [directory.binding.workspace, lease.workspace] {
            guard AnyNativeImportedCatalogChecks.same(candidate.accountID, workspace.accountID),
                  AnyNativeImportedCatalogChecks.same(candidate.spaceID, workspace.spaceID) else { throw AnyHostError.wrongWorkspace }
        }
        try await lease.validate()
        try Task.checkCancellation()
    }

    private func request(_ suffix: [String], body: AnyJSON? = nil, query: [String: String] = [:],
                         lease: AnyHostLease) async throws -> AnyJSON {
        try await lease.validate()
        // POST is used only for the existing read-only query endpoint.
        let value = try await client.requestJSON(method: body == nil ? "GET" : "POST",
            path: ["v1", "spaces", workspace.spaceID] + suffix, body: body, query: query,
            maximumResponseBytes: 4 * 1024 * 1024, authorize: { try await lease.validate() })
        try await lease.validate()
        return value
    }

    private func membership(_ lease: AnyHostLease) async throws {
        let value = try await request(["members", "me"], lease: lease)
        guard value["identity"]?.string.map({ AnyNativeImportedCatalogChecks.same($0, workspace.accountID) }) == true else {
            throw AnyHostError.wrongWorkspace
        }
        try AnyHTTPTorahTargetAccess.validateMember(value, workspace: workspace, intent: .read)
    }

    private func row(_ entry: AnyNativeImportedCatalogEntry, lease: AnyHostLease) async throws -> AnyJSON {
        let response = try await request(["query"], body: .object([
            "objectId": .string(entry.objectID), "dataset": .string(entry.dataset),
            "filter": .object(["id": .string(entry.recordID)]),
            "limit": .integer(2), "offset": .integer(0), "includeTotal": .bool(true)
        ]), lease: lease)
        guard response["total"] == .integer(1), response["hasNext"] == .bool(false),
              let rows = response["records"]?.array, rows.count == 1,
              rows[0]["id"]?.string.map({ AnyNativeImportedCatalogChecks.same($0, entry.recordID) }) == true else {
            throw AnyNativeImportedCatalogError.changedSource(entry.sourceObjectID)
        }
        return rows[0]
    }

    private func creation(_ entry: AnyNativeImportedCatalogEntry, intent: AnyPreparedImmutableRecordIntent,
                          lease: AnyHostLease) async throws -> AnyDestinationImmutableRecordAuthority {
        let changeID = entry.mapping.signedChangeIDs[0]
        var selected: AnyJSON?, cursor: String?, cursors = Set<Data>(), versions = Set<Data>()
        for page in 0..<64 {
            var query = ["dataset": entry.dataset, "recordId": entry.recordID, "coalesce": "false", "limit": "200"]
            if let cursor { query["cursor"] = cursor }
            let response = try await request(["objects", entry.objectID, "history"], query: query, lease: lease)
            guard let changes = response["changes"]?.array, changes.count <= 200,
                  response["cursor"] == nil || response["cursor"]?.string != nil else {
                throw AnyNativeHistoryError.malformedResponse
            }
            for value in changes {
                let change = try AnyNativeHistoryChange(native: value)
                guard versions.insert(Data(change.version.utf8)).inserted else { throw AnyNativeHistoryError.paginationChanged }
                if AnyNativeImportedCatalogChecks.same(change.version, changeID) { selected = value }
            }
            let next = response["cursor"]?.string ?? ""
            guard next.utf8.count <= 8192, !next.utf8.contains(0),
                  next.isEmpty || (!changes.isEmpty && cursors.insert(Data(next.utf8)).inserted) else {
                throw AnyNativeHistoryError.paginationChanged
            }
            if selected != nil || next.isEmpty { break }
            guard page < 63 else { throw AnyNativeHistoryError.paginationLimit }
            cursor = next
        }
        guard let selected else { throw AnyNativeHistoryError.versionNotFound }
        let snapshot = try await request(["objects", entry.objectID, "history", changeID,
            "datasets", entry.dataset, "records", entry.recordID], lease: lease)
        return try .init(change: selected, snapshot: snapshot, intent: intent,
            recordID: entry.recordID, expectedChangeID: changeID)
    }
}

enum AnyNativeImportedCatalogChecks {
    static let stringFields: Set<String> = ["sourceHeadID", "sourceRole", "sourceNativeType", "sourceUniqueKey",
        "sourceTreeJSON", "sourceSnapshotBase64", "sourceViewJSON", "sourceSnapshotSHA256",
        "sourceViewSHA256", "sourceCaptureManifestSHA256", "sourceRecoveryManifestSHA256", "archiveURI"]
    static let ordinaryFields = stringFields.union(["snapshotPresent"])
    static let capturedStringFields = stringFields.subtracting(["sourceRecoveryManifestSHA256"])
        .union(["sourceDefinitionEvidence"])
    static let capturedOrdinaryFields = capturedStringFields.union(["snapshotPresent"])

    /// Closed, disjoint catalog versions. A direct capture has no recovery SHA,
    /// including no empty/null placeholder or caller-created recovery receipt.
    static func definitionKind(_ values: [String: AnyJSON]) -> AnyHeartNativeDefinitionEvidence.Kind? {
        if Set(values.keys) == ordinaryFields,
           stringFields.allSatisfy({ values[$0]?.string != nil }),
           values["sourceRecoveryManifestSHA256"]?.string.map(AnyDestinationPlanChecks.digest) == true {
            return .recoveredOriginal
        }
        if Set(values.keys) == capturedOrdinaryFields,
           capturedStringFields.allSatisfy({ values[$0]?.string != nil }),
           values["sourceDefinitionEvidence"] == .string(AnyHeartNativeDefinitionEvidence.Kind.capturedComplete.rawValue) {
            return .capturedComplete
        }
        return nil
    }

    static func same(_ a: String, _ b: String) -> Bool { a.utf8.elementsEqual(b.utf8) }

    static func evidence(_ values: [String: AnyJSON], source: AnyDestinationSourceBinding,
                         sourceObjectID: String, captured: Bool) throws -> AnyDestinationDefinitionEvidence? {
        if !captured {
            guard source.definitionMembers[Data(sourceObjectID.utf8)] == nil,
                  ["sourceSnapshotBase64", "sourceViewJSON", "sourceSnapshotSHA256", "sourceViewSHA256", "sourceUniqueKey"]
                    .allSatisfy({ values[$0] == .string("") }) else {
                throw AnyNativeImportedCatalogError.changedSource(sourceObjectID)
            }
            return nil
        }
        guard let encoded = values["sourceSnapshotBase64"]?.string,
              let protobuf = Data(base64Encoded: encoded), protobuf.base64EncodedString() == encoded,
              let view = values["sourceViewJSON"]?.string else { throw AnyNativeImportedCatalogError.changedSource(sourceObjectID) }
        let evidence = try AnyDestinationDefinitionEvidence(sourceSpaceID: source.spaceID,
            sourceObjectID: sourceObjectID, protobufBytes: protobuf, jsonViewBytes: Data(view.utf8))
        try evidence.requireSource(source, objectID: sourceObjectID)
        guard values["sourceSnapshotSHA256"] == .string(evidence.snapshotSHA256),
              values["sourceViewSHA256"] == .string(evidence.viewSHA256),
              values["sourceNativeType"] == .string(String(evidence.snapshot.nativeType)),
              values["sourceUniqueKey"]?.string.map({ same($0, evidence.snapshot.uniqueKey) }) == true else {
            throw AnyNativeImportedCatalogError.changedSource(sourceObjectID)
        }
        return evidence
    }

    static func receipt(_ receipt: AnyPreparedImmutableRecordReceipt, entry: AnyNativeImportedCatalogEntry) throws {
        guard receipt.isCompleteAndCurrent, receipt.fingerprint == entry.mapping.fingerprint,
              same(receipt.objectID, entry.objectID), receipt.recordIDs.map({ Data($0.utf8) }) == [Data(entry.recordID.utf8)],
              same(receipt.changeID, entry.mapping.signedChangeIDs[0]) else {
            throw AnyNativeImportedCatalogError.changedSource(entry.sourceObjectID)
        }
    }

    static func schema(_ schema: AnyPreparedImmutableRecordSchema,
                       definitionEvidenceKind: AnyHeartNativeDefinitionEvidence.Kind = .recoveredOriginal) throws {
        let stringFields = definitionEvidenceKind == .recoveredOriginal ? Self.stringFields : capturedStringFields
        let ordinaryFields = definitionEvidenceKind == .recoveredOriginal ? Self.ordinaryFields : capturedOrdinaryFields
        guard let fields = schema.declaration["properties"]?.object,
              Set(fields.keys) == ordinaryFields.union(["importedBy", "importedAt"]),
              let required = schema.declaration["required"]?.array, required.count == ordinaryFields.count,
              required.allSatisfy({ $0.string != nil }), Set(required.compactMap(\.string)) == ordinaryFields,
              stringFields.allSatisfy({ fields[$0]?["type"] == .string("string") }),
              fields["snapshotPresent"]?["type"] == .string("boolean"),
              fields["importedBy"]?["x-stamp"] == .string("creator"),
              fields["importedAt"]?["x-stamp"] == .string("createTime") else {
            throw AnyNativeImportedCatalogError.invalidOriginalPlan
        }
    }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

public enum AnyNativeImportedContentContextError: Error, Equatable, Sendable {
    case invalidReference
    case changedContentCheckpoint
    case missingContentCheckpoint
    case unmappedDocument(String)
    case changedDocument(String)
}

/// A separate editable-content view of the existing completed preservation
/// checkpoint. That whole plan already contains current content and its distinct
/// immutable catalog carrier. No second execution or new checkpoint is needed.
/// Neither locator grants current native authority.
public struct AnyNativeImportedContentContextReference: Codable, Sendable {
    public static let version = "pinkha-native-imported-content-context-v1"
    public static let maximumBytes = 4096
    public let contract: String
    public let checkpointScope: String
    public let preservationReferenceSHA256: String
    public let contentPlanID: String
    public let contentPlanSHA256: String
    public let contentCheckpointSHA256: String
    public let contentSHA256: String
    public var grantsNativeAuthority: Bool { false }

    public init(preservationReference: AnyNativeImportedContextReference,
                preservation: AnyHeartNativeSourcePreservation,
                checkpoint: AnyDestinationSavedCheckpoint) throws {
        let exactPreservation = try AnyNativeImportedContextReference(
            networkID: preservationReference.destinationNetworkID, preservation: preservation,
            checkpoint: checkpoint,
            supplementalCanonicalDefinitions: preservationReference.supplementalCanonicalDefinitions)
        let plan = checkpoint.plan
        guard try exactPreservation.encoded() == preservationReference.encoded(),
              checkpoint.intents.count == plan.items.count,
              checkpoint.mappings.count == plan.items.count,
              checkpoint.checkpointSHA256 == preservationReference.checkpointSHA256 else {
            throw AnyNativeImportedContentContextError.invalidReference
        }
        // ff103's preservationPlan contains current.items + added, sorted by
        // the original phases. Project by the exact source keys, retaining the
        // original whole-plan binding and receipts; never rebind native intents.
        let current = preservation.currentContent
        _ = try current.currentContentPlan(workspace: plan.binding.workspace,
            storeID: plan.binding.storeID, planID: plan.binding.planID)
        let keys = Set(current.items.map { Data($0.sourceKey.utf8) })
        let projection = plan.items.filter { keys.contains(Data($0.sourceKey.utf8)) }
        guard keys.count == current.items.count,
              projection.count == current.items.count,
              try AnyDestinationMigrationJournal.encoded(projection) ==
                AnyDestinationMigrationJournal.encoded(current.items) else {
            throw AnyNativeImportedContentContextError.invalidReference
        }
        contract = Self.version; checkpointScope = "completed-preservation-current-content"
        preservationReferenceSHA256 = AnyContentDigest.sha256(try preservationReference.encoded())
        contentPlanID = plan.binding.planID; contentPlanSHA256 = plan.binding.planSHA256
        contentCheckpointSHA256 = checkpoint.checkpointSHA256; contentSHA256 = current.contentSHA256
        try validate()
    }

    public func binding(preservation: AnyNativeImportedContextReference) throws -> AnyPreparedMigrationPlanBinding {
        try validate()
        guard AnyContentDigest.sha256(try preservation.encoded()) == preservationReferenceSHA256,
              Self.same(contentPlanID, preservation.planID),
              contentPlanSHA256 == preservation.planSHA256,
              contentCheckpointSHA256 == preservation.checkpointSHA256 else {
            throw AnyNativeImportedContentContextError.invalidReference
        }
        return try .init(workspace: preservation.binding.workspace, storeID: preservation.storeID,
                         planID: contentPlanID, planSHA256: contentPlanSHA256)
    }

    public func encoded() throws -> Data {
        try validate()
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        let bytes = try encoder.encode(self)
        guard bytes.count <= Self.maximumBytes else { throw AnyEngineError.readLimit }
        return bytes
    }

    public static func decode(_ bytes: Data) throws -> Self {
        guard !bytes.isEmpty, bytes.count <= maximumBytes else { throw AnyEngineError.readLimit }
        let value = try JSONDecoder().decode(Self.self, from: bytes)
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: bytes, encoded: value.encoded())
        return value
    }

    private func validate() throws {
        guard Self.same(contract, Self.version),
              Self.same(checkpointScope, "completed-preservation-current-content"),
              [preservationReferenceSHA256, contentPlanID, contentPlanSHA256,
               contentCheckpointSHA256, contentSHA256].allSatisfy(AnyDestinationPlanChecks.digest) else {
            throw AnyNativeImportedContentContextError.invalidReference
        }
    }

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case contract, checkpointScope, preservationReferenceSHA256, contentPlanID, contentPlanSHA256
        case contentCheckpointSHA256, contentSHA256
    }

    public init(from decoder: any Decoder) throws {
        let all = try decoder.container(keyedBy: AnyImportedContentCodingKey.self)
        guard Set(all.allKeys.map(\.stringValue)) == Set(CodingKeys.allCases.map(\.rawValue)) else {
            throw AnyNativeImportedContentContextError.invalidReference
        }
        let c = try decoder.container(keyedBy: CodingKeys.self)
        contract = try c.decode(String.self, forKey: .contract)
        checkpointScope = try c.decode(String.self, forKey: .checkpointScope)
        preservationReferenceSHA256 = try c.decode(String.self, forKey: .preservationReferenceSHA256)
        contentPlanID = try c.decode(String.self, forKey: .contentPlanID)
        contentPlanSHA256 = try c.decode(String.self, forKey: .contentPlanSHA256)
        contentCheckpointSHA256 = try c.decode(String.self, forKey: .contentCheckpointSHA256)
        contentSHA256 = try c.decode(String.self, forKey: .contentSHA256)
        try validate()
    }

    static func same(_ a: String, _ b: String) -> Bool { Data(a.utf8) == Data(b.utf8) }
    static func sameWorkspace(_ a: AnyTorahWorkspace, _ b: AnyTorahWorkspace) -> Bool {
        same(a.accountID, b.accountID) && same(a.spaceID, b.spaceID)
    }
}

/// This address comes from the completed content plan's exact object operation.
/// It is never a catalog carrier, title search, Type alias or caller-selected ID.
/// Current existence, Type and native receipts are checked by withDocument.
public struct AnyNativeImportedDocumentEntry: Sendable {
    public let sourceSpaceID: String
    public let sourceObjectID: String
    public let sourceTypeObjectID: String
    public let sourceSnapshotSHA256: String
    public let sourceJSONViewSHA256: String
    public let sourceKey: String
    public let objectID: String
    public let nativeTypeID: String
    public let creationIntentID: String
    public var grantsNativeAuthority: Bool { false }
    let intent: AnyPreparedMigrationIntent
    let mapping: AnyDestinationMigrationMapping

    /// Identity checks on a read response. The caller still owns current native
    /// READ and run/lease admission; parsing this value grants no authority.
    func requireCurrentObject(_ response: AnyJSON) throws {
        let record = try AnyDestinationMigrationVerifier.objectRecord(
            response, id: objectID, spaceID: intent.binding.workspace.spaceID)
        guard record["any"]?["type"]?.string.map({ Data($0.utf8) }) == Data(nativeTypeID.utf8) else {
            throw AnyNativeImportedContentContextError.changedDocument(objectID)
        }
    }

    func requireCurrentReceipt(_ receipt: AnyPreparedMigrationReceipt) throws {
        // Editable content may differ from its original values. Its immutable
        // creation identity must still exist; deletion/obsolescence refuse.
        guard receipt.stage == .complete,
              receipt.outcome == .committed || receipt.outcome == .committedModified,
              receipt.intent.intentID == creationIntentID,
              receipt.intent.specBytes == intent.specBytes,
              AnyNativeImportedContextReference.sameBinding(receipt.intent.binding, intent.binding),
              receipt.fingerprint == mapping.fingerprint,
              receipt.objectID.map({ Data($0.utf8) }) == Data(objectID.utf8),
              receipt.recordIDs.map({ Data($0.utf8) }) == [Data(objectID.utf8)],
              let expectedChange = mapping.signedChangeIDs.last,
              receipt.changeID.map({ Data($0.utf8) }) == Data(expectedChange.utf8) else {
            throw AnyNativeImportedContentContextError.changedDocument(objectID)
        }
    }
}

/// The editable routing context is separate from the immutable catalog context.
/// All source definitions remain represented; only definitions actually present
/// in this completed plan have native addresses. Unsupported Types stay nil.
public struct AnyNativeImportedContentContext: Sendable {
    public let reference: AnyNativeImportedContentContextReference
    public let savedPlan: AnyDestinationMigrationPlan
    public let mappings: [AnyDestinationMigrationMapping]
    public let definitionDirectory: AnyNativeImportedDefinitionDirectory
    public let ordinaryProperties: AnyNativeImportedOrdinaryPropertyContext?
    public let sourceFactsDirectory: AnyNativeImportedSourceFactsDirectory
    public let typeReferences: AnyHeartNativeTypeReferencePlan
    public let documents: [AnyNativeImportedDocumentEntry]
    public var permitsMigrationReplay: Bool { false }
    public var qualifiesWholeSourceBehavior: Bool { false }
    public var provesCurrentNativeState: Bool { false }
    private let byDestination: [Data: Int]
    private let bySource: [Data: Int]

    init(reference: AnyNativeImportedContentContextReference,
         preservationReference: AnyNativeImportedContextReference,
         preservation: AnyHeartNativeSourcePreservation,
         checkpoint: AnyDestinationSavedCheckpoint,
         catalog: AnyHeartNativeDefinitionCatalog,
         catalogCarrierObjectIDs: [String],
         ordinaryProperties: AnyNativeImportedOrdinaryPropertyContext? = nil) throws {
        let expected = try AnyNativeImportedContentContextReference(
            preservationReference: preservationReference, preservation: preservation, checkpoint: checkpoint)
        let composition = preservation.currentContent
        guard try reference.encoded() == expected.encoded(),
              checkpoint.intents.count == checkpoint.plan.items.count,
              checkpoint.mappings.count == checkpoint.plan.items.count else {
            throw AnyNativeImportedContentContextError.changedContentCheckpoint
        }
        let plan = checkpoint.plan, mappings = checkpoint.mappings
        let base = try AnyNativeImportedDefinitionDirectory(plan: plan, mappings: mappings)
        var supplements: [AnyDestinationCanonicalPropertyBinding] = []
        for binding in preservationReference.supplementalCanonicalDefinitions {
            try binding.validate()
            let evidence = binding.evidence
            if let present = base.definition(sourceObjectID: evidence.sourceObjectID) {
                guard present.canonical,
                      present.address == .property(ownerKind: .type,
                        key: try .init(ownerID: binding.ownerID, propertyID: binding.propertyID)),
                      Self.same(present.sourceUniqueKey, evidence.snapshot.uniqueKey),
                      present.sourceSnapshotSHA256 == evidence.snapshotSHA256,
                      present.sourceJSONViewSHA256 == evidence.viewSHA256 else {
                    throw AnyNativeImportedContentContextError.changedContentCheckpoint
                }
            } else { supplements.append(binding) }
        }
        let originalDefinitions = try AnyNativeImportedDefinitionDirectory(plan: plan, mappings: mappings,
            supplementalCanonicalDefinitions: supplements)
        let definitions: AnyNativeImportedDefinitionDirectory
        if let ordinaryProperties {
            try ordinaryProperties.requirePreservation(preservationReference, checkpoint: checkpoint)
            definitions = try ordinaryProperties.merging(into: originalDefinitions)
        } else { definitions = originalDefinitions }
        let sourceFacts = try AnyNativeImportedSourceFactsDirectory(plan: plan, mappings: mappings)
        let references = try AnyHeartNativeTypeReferencePlan(catalog: catalog, directory: definitions)
        let documents = try Self.documentEntries(plan: plan, mappings: mappings,
            composition: composition, definitions: definitions, sourceFacts: sourceFacts,
            catalogCarrierObjectIDs: catalogCarrierObjectIDs)
        var bySource: [Data: Int] = [:], byDestination: [Data: Int] = [:]
        for (index, entry) in documents.enumerated() {
            guard bySource.updateValue(index, forKey: Data(entry.sourceObjectID.utf8)) == nil,
                  byDestination.updateValue(index, forKey: Data(entry.objectID.utf8)) == nil else {
                throw AnyNativeImportedContentContextError.changedContentCheckpoint
            }
        }
        self.reference = reference; savedPlan = plan; self.mappings = mappings
        definitionDirectory = definitions; sourceFactsDirectory = sourceFacts; typeReferences = references
        self.ordinaryProperties = ordinaryProperties
        self.documents = documents; self.bySource = bySource; self.byDestination = byDestination
        try Task.checkCancellation()
    }

    /// Shared pure correspondence used by the owner and focused source controls.
    /// It proves routing from exact plan operations, never current native access.
    static func documentEntries(
        plan: AnyDestinationMigrationPlan, mappings: [AnyDestinationMigrationMapping],
        composition: AnyHeartNativeContentComposition,
        definitions: AnyNativeImportedDefinitionDirectory,
        sourceFacts: AnyNativeImportedSourceFactsDirectory,
        catalogCarrierObjectIDs: [String]
    ) throws -> [AnyNativeImportedDocumentEntry] {
        let keys = Set(composition.items.map { Data($0.sourceKey.utf8) })
        let projection = plan.items.filter { keys.contains(Data($0.sourceKey.utf8)) }
        guard mappings.count == plan.items.count, keys.count == composition.items.count,
              Self.same(plan.source.accountID, composition.bundle.sourceAccountID),
              Self.same(plan.source.spaceID, composition.bundle.sourceSpaceID),
              plan.source.captureManifestSHA256 == composition.bundle.manifestSHA256,
              plan.source.witnessSHA256 == composition.bundle.sourceWitnessSHA256,
              plan.source.definitionManifestBytes == composition.bundle.manifestBytes,
              AnyNativeImportedContextReference.sameBinding(plan.binding, definitions.binding),
              AnyNativeImportedContextReference.sameBinding(plan.binding, sourceFacts.binding),
              try AnyDestinationMigrationJournal.encoded(projection) ==
                AnyDestinationMigrationJournal.encoded(composition.items) else {
            throw AnyNativeImportedContentContextError.changedContentCheckpoint
        }
        var keyed: [Data: AnyDestinationMigrationMapping] = [:]
        for mapping in mappings {
            guard keyed.updateValue(mapping, forKey: Data(mapping.sourceKey.utf8)) == nil else {
                throw AnyNativeImportedContentContextError.changedContentCheckpoint
            }
        }
        let immutableMappings = keyed
        let carriers = Set(catalogCarrierObjectIDs.map { Data($0.utf8) })
        var documents: [AnyNativeImportedDocumentEntry] = []
        var bySource: [Data: Int] = [:], byDestination: [Data: Int] = [:]
        for selected in composition.selection.objects {
            try Task.checkCancellation()
            let sourceKey = AnyHeartNativePageComposition.objectSourceKey(
                spaceID: plan.source.spaceID, objectID: selected.sourceObjectID)
            let indexes = plan.items.indices.filter { Self.same(plan.items[$0].sourceKey, sourceKey) }
            guard indexes.count == 1, let index = indexes.first,
                  Self.same(plan.items[index].sourceObjectID, selected.sourceObjectID),
                  plan.items[index].operation.kind == "object" else {
                throw AnyNativeImportedContentContextError.changedContentCheckpoint
            }
            let operation = try plan.items[index].operation.resolved(
                destinationSpaceID: plan.binding.workspace.spaceID) {
                try AnyDestinationMigrationVerifier.resolve($0, in: immutableMappings,
                    destinationSpaceID: plan.binding.workspace.spaceID)
            }
            guard case .object(.native(let typeID), let collections, .literal(let initial)) = operation,
                  let type = definitions.definition(sourceObjectID: selected.typeObjectID),
                  type.address == .type(objectID: typeID),
                  let facts = sourceFacts.entry(sourceObjectID: selected.sourceObjectID) else {
                throw AnyNativeImportedContentContextError.changedContentCheckpoint
            }
            let intent = try AnyPreparedMigrationIntent.object(binding: plan.binding, sourceKey: sourceKey,
                typeID: typeID, collections: collections.map(AnyDestinationMigrationVerifier.native),
                initialProperties: initial)
            let mapping = mappings[index]
            guard Self.same(mapping.sourceKey, sourceKey),
                  Self.same(mapping.sourceObjectID, selected.sourceObjectID),
                  Self.same(mapping.intentID, intent.intentID),
                  mapping.kind == "object", mapping.fileID == nil,
                  mapping.recordIDs.map({ Data($0.utf8) }) == [Data(mapping.objectID.utf8)],
                  Self.same(facts.objectID, mapping.objectID), Self.same(facts.ownerTypeID, typeID),
                  facts.sourceSnapshotSHA256 == selected.snapshotSHA256,
                  facts.sourceJSONViewSHA256 == selected.jsonViewSHA256,
                  !carriers.contains(Data(mapping.objectID.utf8)),
                  bySource[Data(selected.sourceObjectID.utf8)] == nil,
                  byDestination[Data(mapping.objectID.utf8)] == nil else {
                throw AnyNativeImportedContentContextError.changedContentCheckpoint
            }
            bySource[Data(selected.sourceObjectID.utf8)] = documents.count
            byDestination[Data(mapping.objectID.utf8)] = documents.count
            documents.append(.init(sourceSpaceID: plan.source.spaceID,
                sourceObjectID: selected.sourceObjectID, sourceTypeObjectID: selected.typeObjectID,
                sourceSnapshotSHA256: selected.snapshotSHA256, sourceJSONViewSHA256: selected.jsonViewSHA256,
                sourceKey: sourceKey, objectID: mapping.objectID, nativeTypeID: typeID,
                creationIntentID: intent.intentID, intent: intent, mapping: mapping))
        }
        guard !documents.isEmpty,
              Set(sourceFacts.entries.map { Data($0.sourceObjectID.utf8) }) == Set(bySource.keys),
              documents.count == composition.selection.objects.count else {
            throw AnyNativeImportedContentContextError.changedContentCheckpoint
        }
        return documents
    }

    public func document(destinationObjectID: String) -> AnyNativeImportedDocumentEntry? {
        byDestination[Data(destinationObjectID.utf8)].map { documents[$0] }
    }

    public func document(sourceObjectID: String) -> AnyNativeImportedDocumentEntry? {
        bySource[Data(sourceObjectID.utf8)].map { documents[$0] }
    }

    private static func same(_ a: String, _ b: String) -> Bool {
        AnyNativeImportedContentContextReference.same(a, b)
    }
}

private struct AnyImportedContentCodingKey: CodingKey {
    let stringValue: String
    var intValue: Int? { nil }
    init?(stringValue: String) { self.stringValue = stringValue }
    init?(intValue: Int) { return nil }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration
#if canImport(Darwin)
import Darwin
#elseif canImport(Glibc)
import Glibc
#endif

/// A source file can already be in private app storage, or can be fetched once
/// through the existing native Files API into an explicitly new private path.
/// No destination import/prepare/commit route is called by either choice.
public enum AnyNativeImportedContextArchiveSource: Sendable {
    case retainedFile(URL)
    case nativeDownload(to: URL)
}

/// The cold-open result keeps historical source data and current native routing
/// separate. A mapped Type ID remains a routing hint: the existing definition
/// and Type-reference stores check its current native state when it is used.
public struct AnyNativeImportedContext: Sendable {
    public let reference: AnyNativeImportedContextReference
    public let workspace: AnyTorahWorkspace
    public let generation: UUID
    public let engineStartedAt: String
    public let engineBinding: AnyNativeAccountRunBinding
    public let savedPlan: AnyDestinationMigrationPlan
    public let mappings: [AnyDestinationMigrationMapping]
    public let sourceCatalog: AnyHeartNativeDefinitionCatalog
    public let definitionDirectory: AnyNativeImportedDefinitionDirectory
    public let catalogDirectory: AnyNativeImportedCatalogDirectory
    public let typeReferences: AnyHeartNativeTypeReferencePlan
    public let observedCatalogRecordCount: Int
    /// nil for a preservation-only open. A catalog carrier never fills this.
    public let content: AnyNativeImportedContentContext?
    /// A separate completed supplement, admitted through current native reads.
    public let ordinaryProperties: AnyNativeImportedOrdinaryPropertyContext?
    public var originalHistoryReconstructed: Bool { false }
    public var permitsMigrationReplay: Bool { false }
    public var qualifiesWholeSourceBehavior: Bool { false }
    public var isAtomicWholeSpaceObservation: Bool { false }
}

/// Owns presentation work within the *existing* AnyApplicationSession. It does
/// not create a new account/Space session or mint a replacement lease. Closing
/// this context cancels and drains only work registered through withContext.
public actor AnyNativeImportedContextOwner {
    public nonisolated let workspace: AnyTorahWorkspace
    public nonisolated let generation: UUID
    private let session: AnyApplicationSession
    private let client: AnyHTTPClient
    private let context: AnyNativeImportedContext
    private let ordinaryJournalDirectory: URL?
    private var closed = false
    private var calls: [UUID: @Sendable () -> Void] = [:]
    private var drainWaiters: [CheckedContinuation<Void, Never>] = []

    private init(session: AnyApplicationSession, client: AnyHTTPClient,
                 context: AnyNativeImportedContext, ordinaryJournalDirectory: URL? = nil) {
        self.session = session; self.client = client; self.context = context
        self.ordinaryJournalDirectory = ordinaryJournalDirectory
        workspace = context.workspace; generation = context.generation
    }

    /// Restores the exact saved plan/mapping and complete admitted source file.
    /// It checks every original catalog row through the existing signed native
    /// reader, but does not demand that ordinary documents still equal their
    /// initial imported contents. No missing journal/archive is repaired.
    public static func open(
        client: AnyHTTPClient, session: AnyApplicationSession,
        reference: AnyNativeImportedContextReference, journalDirectory: URL,
        archiveSource: AnyNativeImportedContextArchiveSource
    ) async throws -> AnyNativeImportedContextOwner {
        try await open(client: client, session: session, reference: reference,
            journalDirectory: journalDirectory, archiveSource: archiveSource, completedContent: nil)
    }

    /// Opens the real current-content projection of the already completed whole
    /// preservation checkpoint. The separate locator identifies that view; it
    /// never creates a second plan, repeats migration or uses the catalog carrier
    /// as a document. Source keys and native intents retain the original binding.
    public static func openContent(
        client: AnyHTTPClient, session: AnyApplicationSession,
        preservationReference: AnyNativeImportedContextReference,
        preservationJournalDirectory: URL,
        contentReference: AnyNativeImportedContentContextReference,
        archiveSource: AnyNativeImportedContextArchiveSource
    ) async throws -> AnyNativeImportedContextOwner {
        _ = try contentReference.binding(preservation: preservationReference)
        return try await open(client: client, session: session, reference: preservationReference,
            journalDirectory: preservationJournalDirectory, archiveSource: archiveSource,
            completedContent: contentReference)
    }

    /// Explicitly adds the completed Ordinary14 namespace to the existing
    /// content view. It opens no session, replays no migration, and never repairs
    /// a missing journal. Both caller-supplied locators remain non-authoritative.
    public static func openContent(
        client: AnyHTTPClient, session: AnyApplicationSession,
        preservationReference: AnyNativeImportedContextReference,
        preservationJournalDirectory: URL,
        contentReference: AnyNativeImportedContentContextReference,
        ordinaryPropertyReference: AnyNativeImportedOrdinaryPropertyReference,
        ordinaryPropertyJournalDirectory: URL,
        archiveSource: AnyNativeImportedContextArchiveSource
    ) async throws -> AnyNativeImportedContextOwner {
        _ = try contentReference.binding(preservation: preservationReference)
        _ = try ordinaryPropertyReference.binding(preservation: preservationReference)
        return try await open(client: client, session: session, reference: preservationReference,
            journalDirectory: preservationJournalDirectory, archiveSource: archiveSource,
            completedContent: contentReference, completedOrdinary: ordinaryPropertyReference,
            ordinaryJournalDirectory: ordinaryPropertyJournalDirectory)
    }

    private static func open(
        client: AnyHTTPClient, session: AnyApplicationSession,
        reference: AnyNativeImportedContextReference, journalDirectory: URL,
        archiveSource: AnyNativeImportedContextArchiveSource,
        completedContent: AnyNativeImportedContentContextReference?,
        completedOrdinary: AnyNativeImportedOrdinaryPropertyReference? = nil,
        ordinaryJournalDirectory: URL? = nil
    ) async throws -> AnyNativeImportedContextOwner {
        guard (completedOrdinary == nil) == (ordinaryJournalDirectory == nil),
              completedOrdinary == nil || completedContent != nil else {
            throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
        }
        if let completedOrdinary { _ = try completedOrdinary.binding(preservation: reference) }
        try requireScope(client: client, session: session, reference: reference)
        let context = try await session.perform { lease in
            guard lease.generation == session.generation,
                  AnyImportedContextAdmission.sameWorkspace(lease.workspace, reference.binding.workspace) else {
                throw AnyHostError.wrongWorkspace
            }
            try await lease.validate()
            let run = try await client.nativeAccountRunBinding(expectedNetworkID: reference.destinationNetworkID)
            let admission = AnyImportedContextAdmission(client: client, lease: lease, binding: run)
            try await admission.validate()
            // Private journal content is not read until current authority and
            // the same existing application lease have both been admitted.
            let checkpoint = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
                journalDirectory: journalDirectory, binding: reference.binding)
            guard checkpoint.checkpointSHA256 == reference.checkpointSHA256,
                  AnyNativeImportedContextReference.sameBinding(checkpoint.plan.binding, reference.binding) else {
                throw AnyNativeImportedContextError.changedCheckpoint
            }
            let archive = try AnyImportedContextArchiveIntent(checkpoint: checkpoint, reference: reference)
            let before = try await archive.currentReceipt(admission)
            let file: URL
            switch archiveSource {
            case .retainedFile(let path): file = path
            case .nativeDownload(let path):
                _ = try await client.downloadFileContent(
                    spaceID: reference.binding.workspace.spaceID, fileID: archive.fileID,
                    size: archive.intent.size, mime: archive.intent.mime, to: path,
                    expectedSHA256: archive.intent.contentSHA256,
                    authorize: { try await admission.validate() })
                file = path
            }
            try await admission.validate()
            let bytes = try AnyImportedContextPrivateArchive.read(file,
                expectedBytes: reference.archiveBytes, expectedSHA256: reference.archiveSHA256)
            let expected = try reference.expectedArchiveBinding()
            let reopened = try AnyHeartNativePreservationArchive(restoring: bytes, expected: expected)
            let restored = try AnyHeartNativePreservationArchive.restore(bytes, expected: expected)
            let preservation = try AnyHeartNativeSourcePreservation(bundle: restored.bundle,
                definitionEvidence: restored.definitionEvidence, archive: reopened)
            let exactPlan = try preservation.preservationPlan(workspace: reference.binding.workspace,
                storeID: reference.binding.storeID, planID: reference.binding.planID)
            guard exactPlan.canonicalBytes == checkpoint.plan.canonicalBytes,
                  Data(preservation.archiveItemSourceKey.utf8) == Data(reference.archiveSourceKey.utf8) else {
                throw AnyNativeImportedContextError.changedCheckpoint
            }
            var definitions = try AnyNativeImportedDefinitionDirectory(plan: checkpoint.plan,
                mappings: checkpoint.mappings,
                supplementalCanonicalDefinitions: reference.supplementalCanonicalDefinitions)
            let directory = try AnyNativeImportedCatalogDirectory(plan: checkpoint.plan, mappings: checkpoint.mappings)
            let catalog = try restored.definitionEvidence.catalog(bundle: restored.bundle)
            let ordinary: AnyNativeImportedOrdinaryPropertyContext?
            if let completedOrdinary {
                guard let ordinaryJournalDirectory else {
                    throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
                }
                try await admission.validate()
                let ordinaryBinding = try completedOrdinary.binding(preservation: reference)
                let savedOrdinary = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
                    journalDirectory: ordinaryJournalDirectory, binding: ordinaryBinding)
                let value = try AnyNativeImportedOrdinaryPropertyContext(reference: completedOrdinary,
                    preservationReference: reference, bundle: restored.bundle,
                    completedPreservationPlan: checkpoint.plan,
                    completedPreservationMappings: checkpoint.mappings, checkpoint: savedOrdinary)
                definitions = try value.merging(into: definitions)
                try await admission.validateOrdinary(value, definitions: definitions,
                    journalDirectory: ordinaryJournalDirectory)
                ordinary = value
            } else { ordinary = nil }
            let references = try AnyHeartNativeTypeReferencePlan(catalog: catalog, directory: definitions)
            let reader = try AnyNativeImportedCatalogStore(client: client, workspace: reference.binding.workspace)
            for entry in directory.entries {
                try await admission.validate()
                let current = try await reader.read(sourceObjectID: entry.sourceObjectID,
                                                     directory: directory, lease: lease)
                guard current.generation == lease.generation,
                      Data(current.engineStartedAt.utf8) == Data(lease.engineStartedAt.utf8),
                      current.entry.evidence == entry.evidence,
                      Data(current.entry.sourceObjectID.utf8) == Data(entry.sourceObjectID.utf8) else {
                    throw AnyNativeImportedContextError.changedArchive
                }
                try await admission.validate()
            }
            let content: AnyNativeImportedContentContext?
            if let completedContent {
                try await admission.validate()
                let contentBinding = try completedContent.binding(preservation: reference)
                guard AnyNativeImportedContextReference.sameBinding(contentBinding, checkpoint.plan.binding) else {
                    throw AnyNativeImportedContentContextError.changedContentCheckpoint
                }
                let value = try AnyNativeImportedContentContext(reference: completedContent,
                    preservationReference: reference, preservation: preservation, checkpoint: checkpoint,
                    catalog: catalog, catalogCarrierObjectIDs: directory.entries.map(\.objectID),
                    ordinaryProperties: ordinary)
                let definitionsReader = try AnyNativeImportedDefinitionStore(client: client,
                    workspace: lease.workspace)
                for entry in value.definitionDirectory.entries {
                    try await admission.validate()
                    let observed = try await definitionsReader.read(sourceObjectID: entry.sourceObjectID,
                        directory: value.definitionDirectory, lease: lease)
                    guard observed.generation == lease.generation,
                          Data(observed.engineStartedAt.utf8) == Data(lease.engineStartedAt.utf8) else {
                        throw AnyNativeImportedContentContextError.changedContentCheckpoint
                    }
                    try await admission.validate()
                }
                for entry in value.documents {
                    try await admission.validateDocument(entry, content: value)
                }
                content = value
            } else { content = nil }
            let after = try await archive.currentReceipt(admission)
            guard try AnyHostCanonical.bytes(before, maximumBytes: 65_536) ==
                AnyHostCanonical.bytes(after, maximumBytes: 65_536) else {
                throw AnyNativeImportedContextError.changedArchive
            }
            try await admission.validate()
            return AnyNativeImportedContext(reference: reference, workspace: lease.workspace,
                generation: lease.generation, engineStartedAt: lease.engineStartedAt,
                engineBinding: run, savedPlan: checkpoint.plan, mappings: checkpoint.mappings,
                sourceCatalog: catalog, definitionDirectory: definitions, catalogDirectory: directory,
                typeReferences: references, observedCatalogRecordCount: directory.entries.count,
                content: content, ordinaryProperties: ordinary)
        }
        // The original session performs its last asynchronous run check before
        // this separate delivery observation. The final shared journal read and
        // comparison contain no await inside the active parent actor boundary.
        return try await session.deliverImportedContextObservation {
            let finalCheckpoint = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
                journalDirectory: journalDirectory, binding: reference.binding)
            guard finalCheckpoint.checkpointSHA256 == reference.checkpointSHA256,
                  finalCheckpoint.plan.canonicalBytes == context.savedPlan.canonicalBytes else {
                throw AnyNativeImportedContextError.changedCheckpoint
            }
            if let completedContent {
                guard let content = context.content,
                      finalCheckpoint.checkpointSHA256 == completedContent.contentCheckpointSHA256,
                      finalCheckpoint.plan.canonicalBytes == content.savedPlan.canonicalBytes else {
                    throw AnyNativeImportedContentContextError.changedContentCheckpoint
                }
            }
            if let ordinary = context.ordinaryProperties {
                guard let ordinaryJournalDirectory else {
                    throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
                }
                try ordinary.requirePreservation(reference, checkpoint: finalCheckpoint)
                let finalOrdinary = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
                    journalDirectory: ordinaryJournalDirectory, binding: ordinary.savedPlan.binding)
                try ordinary.requireCheckpoint(finalOrdinary)
            }
            // Original content remains the original182 checkpoint. The optional
            // supplement is a distinct checkpoint. These are sequential local
            // delivery observations, not an atomic pair or whole-Space proof.
            return AnyNativeImportedContextOwner(session: session, client: client, context: context,
                ordinaryJournalDirectory: ordinaryJournalDirectory)
        }
    }

    /// A document/property consumer takes this existing lease into the native
    /// stores. No private cached source value is returned from a retired owner.
    public func withContext<Value: Sendable>(
        _ operation: @escaping @Sendable (AnyNativeImportedContext, AnyHostLease) async throws -> Value
    ) async throws -> Value {
        try requireActive()
        let id = UUID(), session = self.session, client = self.client, captured = context
        let ordinaryJournal = ordinaryJournalDirectory
        let task = Task<Value, Error> {
            try await session.perform { lease in
                guard lease.generation == captured.generation,
                      AnyImportedContextAdmission.sameWorkspace(lease.workspace, captured.workspace),
                      Data(lease.engineStartedAt.utf8) == Data(captured.engineStartedAt.utf8) else {
                    throw AnyHostError.wrongWorkspace
                }
                try await self.requireActive()
                let admission = AnyImportedContextAdmission(client: client, lease: lease,
                                                             binding: captured.engineBinding)
                try await admission.validate()
                if let ordinary = captured.ordinaryProperties {
                    guard let ordinaryJournal else {
                        throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
                    }
                    try await admission.validateOrdinary(ordinary, definitions: captured.definitionDirectory,
                        journalDirectory: ordinaryJournal)
                }
                let value = try await operation(captured, lease)
                if let ordinary = captured.ordinaryProperties {
                    guard let ordinaryJournal else {
                        throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
                    }
                    try await admission.validateOrdinary(ordinary, definitions: captured.definitionDirectory,
                        journalDirectory: ordinaryJournal)
                }
                try await admission.validate()
                try await self.requireActive()
                return value
            }
        }
        calls[id] = { task.cancel() }
        defer { finish(id) }
        return try await withTaskCancellationHandler {
            let value = try await task.value
            try requireActive()
            let delivered = try await session.deliverImportedContextObservation {
                if let ordinary = captured.ordinaryProperties {
                    guard let ordinaryJournal else {
                        throw AnyNativeImportedOrdinaryPropertyContextError.missingCheckpoint
                    }
                    let finalCheckpoint = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
                        journalDirectory: ordinaryJournal, binding: ordinary.savedPlan.binding)
                    try ordinary.requireCheckpoint(finalCheckpoint)
                }
                return value
            }
            try requireActive()
            return delivered
        } onCancel: { task.cancel() }
    }

    /// Resolve an actual editable destination document, preserving its source
    /// identity after ordinary edits. Current native READ, immutable source
    /// facts, original create identity and the selected Type are checked before
    /// and after the consumer. No catalog, xKey or display-name fallback exists.
    public func withDocument<Value: Sendable>(
        destinationObjectID: String,
        _ operation: @escaping @Sendable (
            AnyNativeImportedDocumentEntry, AnyNativeImportedContentContext, AnyHostLease
        ) async throws -> Value
    ) async throws -> Value {
        let client = self.client
        return try await withContext { context, lease in
            guard let content = context.content else {
                throw AnyNativeImportedContentContextError.missingContentCheckpoint
            }
            guard let entry = content.document(destinationObjectID: destinationObjectID) else {
                throw AnyNativeImportedContentContextError.unmappedDocument(destinationObjectID)
            }
            let admission = AnyImportedContextAdmission(client: client, lease: lease,
                binding: context.engineBinding)
            try await admission.validateDocument(entry, content: content)
            let value = try await operation(entry, content, lease)
            try await admission.validateDocument(entry, content: content)
            return value
        }
    }

    public func closeAndDrain() async {
        closed = true
        for cancel in calls.values { cancel() }
        if !calls.isEmpty {
            await withCheckedContinuation { continuation in drainWaiters.append(continuation) }
        }
    }

    public var isActive: Bool {
        get async {
            let parentActive = await session.isActive
            return !closed && parentActive
        }
    }

    private func requireActive() throws {
        guard !closed else { throw AnyNativeImportedContextError.closed }
        try Task.checkCancellation()
    }

    private func finish(_ id: UUID) {
        calls.removeValue(forKey: id)
        if calls.isEmpty {
            let waiting = drainWaiters; drainWaiters.removeAll()
            for continuation in waiting { continuation.resume() }
        }
    }

    private static func requireScope(client: AnyHTTPClient, session: AnyApplicationSession,
                                     reference: AnyNativeImportedContextReference) throws {
        guard Data(client.expectedAccountID.utf8) == Data(reference.destinationAccountID.utf8),
              AnyImportedContextAdmission.sameWorkspace(session.workspace, reference.binding.workspace) else {
            throw AnyHostError.wrongWorkspace
        }
    }
}

/// A final local observation on the existing parent actor. It performs no
/// native request and does not claim an atomic remote ACL or whole-Space read.
/// Parent retirement cannot interleave with the synchronous callback.
private extension AnyApplicationSession {
    func deliverImportedContextObservation<Value: Sendable>(
        _ operation: @Sendable () throws -> Value
    ) throws -> Value {
        guard isActive else { throw AnyHostError.sessionClosed }
        try Task.checkCancellation()
        let value = try operation()
        try Task.checkCancellation()
        return value
    }
}

private struct AnyImportedContextAdmission: Sendable {
    let client: AnyHTTPClient
    let lease: AnyHostLease
    let binding: AnyNativeAccountRunBinding

    func validate() async throws {
        guard Data(binding.accountID.utf8) == Data(lease.workspace.accountID.utf8),
              Data(client.expectedAccountID.utf8) == Data(lease.workspace.accountID.utf8) else {
            throw AnyHostError.wrongWorkspace
        }
        try await lease.validate()
        try await client.requireNativeAccountRun(binding)
        let value = try await client.requestJSON(method: "GET",
            path: ["v1", "spaces", lease.workspace.spaceID, "members", "me"],
            maximumResponseBytes: 65_536, authorize: { try await lease.validate() })
        guard value["identity"]?.string.map({ Data($0.utf8) }) == Data(lease.workspace.accountID.utf8) else {
            throw AnyHostError.wrongWorkspace
        }
        // Ordinary account membership owns the private saved checkpoint. A
        // public guest-key identity is not substituted for this account.
        try AnyHTTPTorahTargetAccess.validateMember(value, workspace: lease.workspace, intent: .read)
        try await client.requireNativeAccountRun(binding)
        try await lease.validate()
    }

    func get(_ path: [String]) async throws -> AnyJSON {
        try await validate()
        let value = try await client.requestJSON(method: "GET", path: path,
            maximumResponseBytes: 65_536, authorize: { try await validate() })
        try await validate()
        return value
    }

    func validateOrdinary(_ ordinary: AnyNativeImportedOrdinaryPropertyContext,
                          definitions: AnyNativeImportedDefinitionDirectory,
                          journalDirectory: URL) async throws {
        guard Self.sameWorkspace(ordinary.savedPlan.binding.workspace, lease.workspace),
              AnyNativeImportedContextReference.sameBinding(definitions.binding, ordinary.namespace.binding),
              definitions.supplementalPropertyBindings.count == 1,
              AnyNativeImportedContextReference.sameBinding(
                definitions.supplementalPropertyBindings[0], ordinary.savedPlan.binding) else {
            throw AnyHostError.wrongWorkspace
        }
        try await validate()
        let before = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
            journalDirectory: journalDirectory, binding: ordinary.savedPlan.binding)
        try ordinary.requireCheckpoint(before)
        let driver = try await AnyDestinationNativeClients.open(client: client, plan: ordinary.savedPlan,
            authorize: { try await validate() })
        let reader = try AnyNativeImportedDefinitionStore(client: client, workspace: lease.workspace)
        try await ordinary.observe(using: driver, authorize: { try await validate() }) { sourceID in
            let observed = try await reader.read(sourceObjectID: sourceID,
                directory: definitions, lease: lease)
            guard Self.sameWorkspace(observed.workspace, lease.workspace),
                  observed.generation == lease.generation,
                  Data(observed.engineStartedAt.utf8) == Data(lease.engineStartedAt.utf8),
                  observed.matchesOriginalDescriptor, observed.nativeCreationOutcome == "committed",
                  observed.entry.intent.map({ AnyNativeImportedContextReference.sameBinding(
                    $0.binding, ordinary.savedPlan.binding) }) == true else {
                throw AnyNativeImportedOrdinaryPropertyContextError.changedDefinition(sourceID)
            }
        }
        let after = try AnyDestinationMigrationExecutor.readCompletedCheckpoint(
            journalDirectory: journalDirectory, binding: ordinary.savedPlan.binding)
        try ordinary.requireCheckpoint(after)
        try await validate()
    }

    func validateDocument(_ entry: AnyNativeImportedDocumentEntry,
                          content: AnyNativeImportedContentContext) async throws {
        guard Self.sameWorkspace(content.savedPlan.binding.workspace, lease.workspace),
              content.document(destinationObjectID: entry.objectID)?.sourceObjectID.utf8
                .elementsEqual(entry.sourceObjectID.utf8) == true else {
            throw AnyHostError.wrongWorkspace
        }
        try await validate()
        let migration = try await AnyNativePreparedMigration.open(client: client, workspace: lease.workspace,
            authorize: { try await validate() })
        guard Data(migration.capabilities.storeID.utf8) == Data(content.savedPlan.binding.storeID.utf8) else {
            throw AnyPreparedMigrationError.changedStore
        }
        let before = try await migration.status(entry.intent, authorize: { try await validate() })
        try entry.requireCurrentReceipt(before)
        let facts = try AnyNativeImportedSourceFactsStore(client: client, workspace: lease.workspace)
        let source = try await facts.read(sourceObjectID: entry.sourceObjectID,
            directory: content.sourceFactsDirectory, lease: lease)
        guard source.generation == lease.generation,
              Data(source.engineStartedAt.utf8) == Data(lease.engineStartedAt.utf8),
              Data(source.entry.objectID.utf8) == Data(entry.objectID.utf8),
              source.entry.sourceSnapshotSHA256 == entry.sourceSnapshotSHA256,
              source.entry.sourceJSONViewSHA256 == entry.sourceJSONViewSHA256 else {
            throw AnyNativeImportedContentContextError.changedDocument(entry.objectID)
        }
        try await validate()
        let raw = try await client.requestJSON(method: "GET",
            path: ["v1", "spaces", lease.workspace.spaceID, "objects", entry.objectID],
            maximumResponseBytes: 8 * 1024 * 1024, authorize: { try await validate() })
        try entry.requireCurrentObject(raw)
        let after = try await migration.status(entry.intent, authorize: { try await validate() })
        try entry.requireCurrentReceipt(after)
        guard before == after else {
            throw AnyNativeImportedContentContextError.changedDocument(entry.objectID)
        }
        try await validate()
    }

    static func sameWorkspace(_ a: AnyTorahWorkspace, _ b: AnyTorahWorkspace) -> Bool {
        Data(a.accountID.utf8) == Data(b.accountID.utf8) &&
            Data(a.spaceID.utf8) == Data(b.spaceID.utf8)
    }
}

private struct AnyImportedContextArchiveIntent: Sendable {
    let intent: AnyPreparedFileIntent
    let mapping: AnyDestinationMigrationMapping
    let fileID: String

    init(checkpoint: AnyDestinationSavedCheckpoint, reference: AnyNativeImportedContextReference) throws {
        let matches = checkpoint.plan.items.indices.filter {
            Data(checkpoint.plan.items[$0].sourceKey.utf8) == Data(reference.archiveSourceKey.utf8)
        }
        guard matches.count == 1, let index = matches.first,
              checkpoint.intents.indices.contains(index), checkpoint.mappings.indices.contains(index),
              case .file(let intent) = checkpoint.intents[index],
              intent.size == reference.archiveBytes, intent.contentSHA256 == reference.archiveSHA256,
              Data(intent.mime.utf8) == Data(AnyHeartNativePreservationArchive.mimeType.utf8),
              AnyNativeImportedContextReference.sameBinding(intent.binding, reference.binding),
              let fileID = checkpoint.mappings[index].fileID else {
            throw AnyNativeImportedContextError.unavailableArchive
        }
        self.intent = intent; mapping = checkpoint.mappings[index]; self.fileID = fileID
    }

    func currentReceipt(_ admission: AnyImportedContextAdmission) async throws -> AnyJSON {
        let binding = intent.binding
        let prefix = ["v1", "spaces", binding.workspace.spaceID, "pinkha", "migration"]
        let rawCapabilities = try await admission.get(prefix + ["file", "capabilities"])
        let capabilities = try AnyPreparedFileCapabilities(rawCapabilities, workspace: binding.workspace)
        guard same(rawCapabilities["accountId"]?.string, binding.workspace.accountID),
              same(rawCapabilities["spaceId"]?.string, binding.workspace.spaceID),
              same(capabilities.storeID, binding.storeID) else { throw AnyPreparedMigrationError.changedStore }
        let raw = try await admission.get(prefix + ["intents", intent.intentID, "file"])
        let receipt = try AnyPreparedFileReceipt(raw, intent: intent)
        guard same(raw["accountId"]?.string, binding.workspace.accountID),
              same(raw["spaceId"]?.string, binding.workspace.spaceID),
              same(raw["storeId"]?.string, binding.storeID),
              same(raw["planId"]?.string, binding.planID),
              same(raw["sourceKey"]?.string, intent.sourceKey),
              same(raw["ownerObjectId"]?.string, intent.ownerObjectID),
              receipt.isCompleteAndCurrent,
              same(receipt.fingerprint, mapping.fingerprint),
              same(receipt.objectID, mapping.objectID), same(receipt.fileID, fileID),
              receipt.recordIDs.map({ Data($0.utf8) }) == mapping.recordIDs.map({ Data($0.utf8) }),
              mapping.signedChangeIDs.contains(where: { same($0, receipt.changeID) }) else {
            throw AnyNativeImportedContextError.changedArchive
        }
        return raw
    }

    private func same(_ a: String?, _ b: String) -> Bool {
        a.map { Data($0.utf8) == Data(b.utf8) } ?? false
    }
}

private enum AnyImportedContextPrivateArchive {
    static func read(_ url: URL, expectedBytes: Int64, expectedSHA256: String) throws -> Data {
        guard url.isFileURL, (4096...Int64(AnyHeartNativePreservationArchive.maximumBytes)).contains(expectedBytes) else {
            throw AnyNativeImportedContextError.unavailableArchive
        }
        try Task.checkCancellation()
        let fd = open(url.path, O_RDONLY | O_NOFOLLOW | O_CLOEXEC)
        guard fd >= 0 else { throw AnyNativeImportedContextError.unavailableArchive }
        let handle = FileHandle(fileDescriptor: fd, closeOnDealloc: true)
        defer { try? handle.close() }
        var before = stat(), after = stat(), named = stat()
        guard fstat(fd, &before) == 0, lstat(url.path, &named) == 0,
              before.st_mode & mode_t(S_IFMT) == mode_t(S_IFREG),
              before.st_uid == geteuid(), before.st_nlink == 1,
              before.st_mode & mode_t(0o7777) == mode_t(0o400) ||
                  before.st_mode & mode_t(0o7777) == mode_t(0o600),
              before.st_size == expectedBytes, same(before, named) else {
            throw AnyNativeImportedContextError.unavailableArchive
        }
        let maximum = Int(expectedBytes)
        var data = Data()
        while data.count <= maximum {
            try Task.checkCancellation()
            let part = try handle.read(upToCount: min(1_048_576, maximum + 1 - data.count)) ?? Data()
            if part.isEmpty { break }
            data.append(part)
        }
        guard data.count == maximum, AnyContentDigest.sha256(data) == expectedSHA256,
              fstat(fd, &after) == 0, lstat(url.path, &named) == 0,
              same(before, after), same(after, named) else {
            throw AnyNativeImportedContextError.changedArchive
        }
        try Task.checkCancellation()
        return data
    }

    private static func same(_ a: stat, _ b: stat) -> Bool {
        guard a.st_dev == b.st_dev, a.st_ino == b.st_ino, a.st_mode == b.st_mode,
              a.st_nlink == b.st_nlink, a.st_uid == b.st_uid, a.st_gid == b.st_gid,
              a.st_size == b.st_size else { return false }
        #if canImport(Darwin)
        return a.st_mtimespec.tv_sec == b.st_mtimespec.tv_sec &&
            a.st_mtimespec.tv_nsec == b.st_mtimespec.tv_nsec &&
            a.st_ctimespec.tv_sec == b.st_ctimespec.tv_sec &&
            a.st_ctimespec.tv_nsec == b.st_ctimespec.tv_nsec
        #else
        return a.st_mtim.tv_sec == b.st_mtim.tv_sec && a.st_mtim.tv_nsec == b.st_mtim.tv_nsec &&
            a.st_ctim.tv_sec == b.st_ctim.tv_sec && a.st_ctim.tv_nsec == b.st_ctim.tv_nsec
        #endif
    }
}

import Foundation
import PinkhaAnyEngine
import PinkhaAnyIntegration

public enum AnyNativeImportedContextError: Error, Equatable, Sendable {
    case invalidReference
    case changedCheckpoint
    case unavailableArchive
    case changedArchive
    case closed
}

/// Persist this bounded reference beside the application's existing migration
/// selection. The actual plan and receipts remain in the original private
/// migration journal; no display name, xKey search or saved native run is used.
public struct AnyNativeImportedContextReference: Codable, Sendable {
    public static let version = "pinkha-native-imported-context-v1"
    public static let capturedVersion = "pinkha-native-imported-context-v2"
    public static let maximumBytes = 32 * 1024 * 1024
    public let contract: String
    public let destinationNetworkID: String
    public let destinationAccountID: String
    public let destinationSpaceID: String
    public let storeID: String
    public let planID: String
    public let planSHA256: String
    public let checkpointSHA256: String
    public let sourceAccountID: String
    public let sourceSpaceID: String
    public let captureManifestSHA256: String
    public let sourceWitnessSHA256: String
    public let recoveredManifestSHA256: String?
    /// Absent in the unchanged v1 locator; exactly captured-complete in v2.
    public let definitionEvidence: String?
    public let archiveSourceKey: String
    public let archiveSHA256: String
    public let archiveBytes: Int64
    public let supplementalCanonicalDefinitions: [AnyDestinationCanonicalPropertyBinding]
    public let binding: AnyPreparedMigrationPlanBinding
    public var grantsNativeAuthority: Bool { false }

    /// Called after the existing executor returned its completed progress.
    /// The reference itself is still a locator; opening it performs current
    /// native READ, engine-run and original archive-receipt validation again.
    public init(networkID: String, preservation: AnyHeartNativeSourcePreservation,
                plan: AnyDestinationMigrationPlan, progress: AnyDestinationMigrationProgress,
                supplementalCanonicalDefinitions: [AnyDestinationCanonicalPropertyBinding] = []) throws {
        guard progress.allItemsReconciled, progress.totalItems == plan.items.count,
              progress.verificationIntents.count == plan.items.count,
              Self.sameBinding(progress.binding, plan.binding),
              try AnyDestinationMigrationJournal.encoded(progress.source) ==
                AnyDestinationMigrationJournal.encoded(plan.source) else {
            throw AnyNativeImportedContextError.invalidReference
        }
        try self.init(networkID: networkID, preservation: preservation, plan: plan,
            mappings: progress.mappings, supplementalCanonicalDefinitions: supplementalCanonicalDefinitions)
    }

    /// Backfills a locator from an already-existing completed journal without
    /// replaying migration. readCompletedCheckpoint supplies historical facts
    /// only; the later context open must still admit current native authority.
    public init(networkID: String, preservation: AnyHeartNativeSourcePreservation,
                checkpoint: AnyDestinationSavedCheckpoint,
                supplementalCanonicalDefinitions: [AnyDestinationCanonicalPropertyBinding] = []) throws {
        guard checkpoint.checkpointSHA256 == (try AnyDestinationSavedCheckpoint.fingerprint(
            plan: checkpoint.plan, mappings: checkpoint.mappings)) else {
            throw AnyNativeImportedContextError.changedCheckpoint
        }
        try self.init(networkID: networkID, preservation: preservation, plan: checkpoint.plan,
            mappings: checkpoint.mappings, supplementalCanonicalDefinitions: supplementalCanonicalDefinitions)
    }

    private init(networkID: String, preservation: AnyHeartNativeSourcePreservation,
                 plan: AnyDestinationMigrationPlan, mappings: [AnyDestinationMigrationMapping],
                 supplementalCanonicalDefinitions: [AnyDestinationCanonicalPropertyBinding]) throws {
        let expected = try preservation.preservationPlan(workspace: plan.binding.workspace,
            storeID: plan.binding.storeID, planID: plan.binding.planID)
        guard expected.canonicalBytes == plan.canonicalBytes else {
            throw AnyNativeImportedContextError.invalidReference
        }
        _ = try AnyNativeImportedDefinitionDirectory(plan: plan, mappings: mappings,
            supplementalCanonicalDefinitions: supplementalCanonicalDefinitions)
        _ = try AnyNativeImportedCatalogDirectory(plan: plan, mappings: mappings)
        contract = preservation.definitionEvidence.kind == .recoveredOriginal ? Self.version : Self.capturedVersion
        definitionEvidence = preservation.definitionEvidence.kind == .capturedComplete
            ? AnyHeartNativeDefinitionEvidence.Kind.capturedComplete.rawValue : nil
        destinationNetworkID = networkID
        destinationAccountID = plan.binding.workspace.accountID
        destinationSpaceID = plan.binding.workspace.spaceID
        storeID = plan.binding.storeID; planID = plan.binding.planID; planSHA256 = plan.binding.planSHA256
        binding = plan.binding
        checkpointSHA256 = try AnyDestinationSavedCheckpoint.fingerprint(plan: plan, mappings: mappings)
        let source = preservation.archive.binding
        sourceAccountID = source.accountID; sourceSpaceID = source.spaceID
        captureManifestSHA256 = source.captureManifestSHA256
        sourceWitnessSHA256 = source.sourceWitnessSHA256
        recoveredManifestSHA256 = source.recoveredManifestSHA256
        archiveSourceKey = preservation.archiveItemSourceKey
        archiveSHA256 = preservation.archive.sha256; archiveBytes = Int64(preservation.archive.bytes.count)
        self.supplementalCanonicalDefinitions = supplementalCanonicalDefinitions
        try validate()
    }

    public func encoded() throws -> Data {
        try validate()
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        let bytes = try encoder.encode(self)
        guard bytes.count <= Self.maximumBytes else { throw AnyEngineError.readLimit }
        return bytes
    }

    /// Use for persisted/untrusted bytes. Besides the closed typed fields, the
    /// existing guard rejects duplicate/colliding keys and numeric loss.
    public static func decode(_ bytes: Data) throws -> Self {
        guard !bytes.isEmpty, bytes.count <= maximumBytes else { throw AnyEngineError.readLimit }
        let value = try JSONDecoder().decode(Self.self, from: bytes)
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: bytes, encoded: value.encoded())
        return value
    }

    func expectedArchiveBinding() throws -> AnyHeartNativePreservationArchive.Binding {
        if Data(contract.utf8) == Data(Self.version.utf8) {
            guard definitionEvidence == nil, let recoveredManifestSHA256 else {
                throw AnyNativeImportedContextError.invalidReference
            }
            return try .init(expectedAccountID: sourceAccountID, expectedSpaceID: sourceSpaceID,
                captureManifestSHA256: captureManifestSHA256, sourceWitnessSHA256: sourceWitnessSHA256,
                recoveredManifestSHA256: recoveredManifestSHA256)
        }
        guard Data(contract.utf8) == Data(Self.capturedVersion.utf8),
              definitionEvidence == AnyHeartNativeDefinitionEvidence.Kind.capturedComplete.rawValue,
              recoveredManifestSHA256 == nil else { throw AnyNativeImportedContextError.invalidReference }
        return try .init(expectedAccountID: sourceAccountID, expectedSpaceID: sourceSpaceID,
            capturedManifestSHA256: captureManifestSHA256, sourceWitnessSHA256: sourceWitnessSHA256)
    }

    private func validate() throws {
        guard [Self.version, Self.capturedVersion].contains(where: { Data($0.utf8) == Data(contract.utf8) }),
              AnyPreparedMigrationPlanBinding.validOpaque(destinationNetworkID, maximum: 4096),
              AnyPreparedMigrationPlanBinding.validOpaque(archiveSourceKey, maximum: 4096),
              [checkpointSHA256, archiveSHA256].allSatisfy(AnyDestinationPlanChecks.digest),
              (4096...Int64(AnyHeartNativePreservationArchive.maximumBytes)).contains(archiveBytes),
              supplementalCanonicalDefinitions.count <= 9,
              Self.sameBinding(binding, try .init(
                workspace: .init(accountID: destinationAccountID, spaceID: destinationSpaceID),
                storeID: storeID, planID: planID, planSHA256: planSHA256)) else {
            throw AnyNativeImportedContextError.invalidReference
        }
        _ = try expectedArchiveBinding()
        var seen = Set<Data>()
        for value in supplementalCanonicalDefinitions {
            try value.validate()
            guard seen.insert(Data(value.evidence.sourceObjectID.utf8)).inserted else {
                throw AnyNativeImportedContextError.invalidReference
            }
        }
    }

    private enum CodingKeys: String, CodingKey, CaseIterable {
        case contract, destinationNetworkID, destinationAccountID, destinationSpaceID
        case storeID, planID, planSHA256, checkpointSHA256
        case sourceAccountID, sourceSpaceID, captureManifestSHA256, sourceWitnessSHA256, recoveredManifestSHA256
        case definitionEvidence
        case archiveSourceKey, archiveSHA256, archiveBytes, supplementalCanonicalDefinitions
    }

    public init(from decoder: any Decoder) throws {
        let all = try decoder.container(keyedBy: AnyImportedContextCodingKey.self)
        let c = try decoder.container(keyedBy: CodingKeys.self)
        contract = try c.decode(String.self, forKey: .contract)
        let expectedKeys: Set<String>
        if Data(contract.utf8) == Data(Self.version.utf8) {
            expectedKeys = Set(CodingKeys.allCases.map(\.rawValue)).subtracting(["definitionEvidence"])
        } else if Data(contract.utf8) == Data(Self.capturedVersion.utf8) {
            expectedKeys = Set(CodingKeys.allCases.map(\.rawValue)).subtracting(["recoveredManifestSHA256"])
        } else { throw AnyNativeImportedContextError.invalidReference }
        guard Set(all.allKeys.map(\.stringValue)) == expectedKeys else {
            throw AnyNativeImportedContextError.invalidReference
        }
        destinationNetworkID = try c.decode(String.self, forKey: .destinationNetworkID)
        destinationAccountID = try c.decode(String.self, forKey: .destinationAccountID)
        destinationSpaceID = try c.decode(String.self, forKey: .destinationSpaceID)
        storeID = try c.decode(String.self, forKey: .storeID)
        planID = try c.decode(String.self, forKey: .planID)
        planSHA256 = try c.decode(String.self, forKey: .planSHA256)
        checkpointSHA256 = try c.decode(String.self, forKey: .checkpointSHA256)
        sourceAccountID = try c.decode(String.self, forKey: .sourceAccountID)
        sourceSpaceID = try c.decode(String.self, forKey: .sourceSpaceID)
        captureManifestSHA256 = try c.decode(String.self, forKey: .captureManifestSHA256)
        sourceWitnessSHA256 = try c.decode(String.self, forKey: .sourceWitnessSHA256)
        if Data(contract.utf8) == Data(Self.version.utf8) {
            recoveredManifestSHA256 = try c.decode(String.self, forKey: .recoveredManifestSHA256)
            definitionEvidence = nil
        } else {
            recoveredManifestSHA256 = nil
            definitionEvidence = try c.decode(String.self, forKey: .definitionEvidence)
        }
        archiveSourceKey = try c.decode(String.self, forKey: .archiveSourceKey)
        archiveSHA256 = try c.decode(String.self, forKey: .archiveSHA256)
        archiveBytes = try c.decode(Int64.self, forKey: .archiveBytes)
        supplementalCanonicalDefinitions = try c.decode([AnyDestinationCanonicalPropertyBinding].self,
                                                         forKey: .supplementalCanonicalDefinitions)
        binding = try .init(workspace: .init(accountID: destinationAccountID, spaceID: destinationSpaceID),
                            storeID: storeID, planID: planID, planSHA256: planSHA256)
        try validate()
    }

    static func sameBinding(_ a: AnyPreparedMigrationPlanBinding,
                            _ b: AnyPreparedMigrationPlanBinding) -> Bool {
        Data(a.workspace.accountID.utf8) == Data(b.workspace.accountID.utf8) &&
        Data(a.workspace.spaceID.utf8) == Data(b.workspace.spaceID.utf8) &&
        Data(a.storeID.utf8) == Data(b.storeID.utf8) &&
        Data(a.planID.utf8) == Data(b.planID.utf8) && a.planSHA256 == b.planSHA256
    }
}

private struct AnyImportedContextCodingKey: CodingKey {
    let stringValue: String
    var intValue: Int? { nil }
    init?(stringValue: String) { self.stringValue = stringValue }
    init?(intValue: Int) { return nil }
}

