import Foundation
import PinkhaAnyEngine

/// Definition provenance for one fully verified captured bundle. Neither case
/// grants a source session, destination lease or permission to execute a plan.
/// A directly captured complete census is never represented as recovery.
public enum AnyHeartNativeDefinitionEvidence: Sendable {
    public enum Kind: String, Sendable {
        case capturedComplete = "captured-complete"
        case recoveredOriginal = "recovered-original"
    }
    case capturedComplete
    case recoveredOriginal(AnyHeartNativeRecoveredDefinitions)

    public var kind: Kind {
        switch self {
        case .capturedComplete: .capturedComplete
        case .recoveredOriginal: .recoveredOriginal
        }
    }
    public var recoveredDefinitions: AnyHeartNativeRecoveredDefinitions? {
        if case .recoveredOriginal(let value) = self { return value }
        return nil
    }
    public var recoveredManifestSHA256: String? { recoveredDefinitions?.manifestSHA256 }

    /// The containing immutable capture supplies descriptor provenance. The
    /// exact native producer exports this closed, ordered census, including an
    /// explicit null/empty declaration when it used no compiled descriptors.
    public func catalog(bundle: AnyHeartNativeSpaceBundle) throws -> AnyHeartNativeDefinitionCatalog {
        switch self {
        case .recoveredOriginal(let recovered):
            // Keep the historical nonempty-missing-set validation unchanged.
            return try .init(bundle: bundle, recoveredDefinitions: recovered)
        case .capturedComplete:
            let used = bundle.bundledDefinitionsUsed.map { Data($0.utf8) }
            let captured = bundle.bundledDefinitions.map { Data($0.identity.utf8) }
            guard bundle.rawManifest["BundledDefinitions"] != nil,
                  used == captured, Set(used).count == used.count,
                  captured == captured.sorted(by: { $0.lexicographicallyPrecedes($1) }),
                  !bundle.issues.contains(where: {
                      $0.code == "compiled-definition-descriptors-not-captured"
                  }) else { throw AnyHeartNativePreservationError.binding }
            return try .init(bundle: bundle)
        }
    }
}

import Foundation
import PinkhaKit
import PinkhaAnyEngine

public enum AnyHeartNativePinkhaSourceError: Error, Equatable, Sendable {
    case sourceBinding, ambiguousManifest, invalidManifest(String)
    case missingDefinition(String), malformedValue(String, String)
    case unknownObject(String), missingMapping(String), emptyCanonicalProperty
}

/// Resolves Pinkha's actual captured manifest against native definition IDs.
/// Display names never bind a property or document type. Raw source bytes and
/// absent/empty values stay available; this component grants no migration access.
public struct AnyHeartNativePinkhaSource: Sendable {
    public enum Role: Equatable, Sendable {
        case folder, bookFolder, writingDocument(String)
    }
    public struct Property: Sendable {
        public let objectID: String
        public let key: String
        public let format: AnyHeartNativeDefinitionCatalog.Format
        public let definitionSnapshotSHA256: String
    }
    public struct HierarchyEntry: Sendable {
        public let snapshot: AnyHeartNativeSnapshotView
        public let typeID: String
        public let role: Role
        public let originalParent: AnyJSON?
        public let parentObjectID: String?
        public let originalOrder: AnyJSON?
        public let order: Double?
    }
    public struct CanonicalDocument: Sendable {
        public let snapshot: AnyHeartNativeSnapshotView
        public let propertyKey: String
        /// Explicit empty string is distinct from an absent source property.
        public let sourceBytes: Data
        public let records: [TorahStoredAssociationRecord]
        public var sourceSHA256: String { AnyContentDigest.sha256(sourceBytes) }
    }
    public struct Issue: Equatable, Sendable {
        public let objectID: String
        public let field: String
        public let reason: String
    }

    public let sourceAccountID: String
    public let sourceSpaceID: String
    public let captureManifestSHA256: String
    public let sourceWitnessSHA256: String
    public let manifestObjectID: String
    public let manifestSnapshotSHA256: String
    public let manifestBytes: Data
    public let rawManifest: AnyJSON
    public let contentSHA256: String
    public let parentProperty: Property
    public let orderProperty: Property
    public let associationsProperty: Property
    public let folderTypeID: String
    public let bookFolderTypeID: String
    public let documentTypes: [String: String]
    public let defaultTemplates: [String: String]
    public let hierarchy: [HierarchyEntry]
    public let canonicalDocuments: [CanonicalDocument]
    public let issues: [Issue]
    private let capturedObjectIDs: Set<Data>
    public var permitsDestinationWrites: Bool { false }

    public static func discover(in bundle: AnyHeartNativeSpaceBundle) throws -> Self? {
        try discover(catalog: .init(bundle: bundle), snapshots: bundle.objects)
    }

    /// Detached control boundary. Only the verified outer bundle is public.
    static func discover(catalog: AnyHeartNativeDefinitionCatalog,
                         snapshots: [AnyHeartNativeSnapshotView]) throws -> Self? {
        guard snapshots.count <= 100_000,
              snapshots.allSatisfy({ exact($0.sourceSpaceID, catalog.sourceSpaceID) }),
              Set(snapshots.map { Data($0.sourceObjectID.utf8) }).count == snapshots.count,
              Set(snapshots.map(\.sourceObjectID)).count == snapshots.count else {
            throw AnyHeartNativePinkhaSourceError.sourceBinding
        }
        var candidates: [(AnyHeartNativeSnapshotView, Data, AnyJSON)] = []
        for snapshot in snapshots {
            // This matches the original store's legacy-name discovery. The
            // complete manifest's source identity is still required below.
            guard snapshot.details["name"]?.string == PinkhaSchemaRoles.manifestName ||
                    snapshot.uniqueKey == PinkhaSchemaRoles.manifestUniqueKey else { continue }
            guard let text = snapshot.details["description"]?.string,
                  !text.isEmpty, text.utf8.count <= 1_048_576 else { continue }
            let bytes = Data(text.utf8)
            guard let raw = try? JSONDecoder().decode(AnyJSON.self, from: bytes),
                  raw.object != nil, let space = raw["spaceId"]?.string,
                  exact(space, catalog.sourceSpaceID) else { continue }
            if let owner = raw["manifestObjectId"], owner != .null {
                guard let id = owner.string, exact(id, snapshot.sourceObjectID) else { continue }
            }
            candidates.append((snapshot, bytes, raw))
        }
        guard candidates.count <= 1 else { throw AnyHeartNativePinkhaSourceError.ambiguousManifest }
        guard let (snapshot, bytes, manifest) = candidates.first else { return nil }
        return try .init(catalog: catalog, snapshots: snapshots, manifestSnapshot: snapshot,
                         manifestBytes: bytes, rawManifest: manifest)
    }

    private init(catalog: AnyHeartNativeDefinitionCatalog, snapshots: [AnyHeartNativeSnapshotView],
                 manifestSnapshot: AnyHeartNativeSnapshotView,
                 manifestBytes: Data, rawManifest: AnyJSON) throws {
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: manifestBytes, encoded: encoder.encode(rawManifest))
        guard manifestSnapshot.nativeType == 16,
              rawManifest["schemaVersion"]?.integer == Int64(PinkhaSpaceManifest.currentSchemaVersion),
              rawManifest["provisioningState"] == nil || rawManifest["provisioningState"] == .string("complete") else {
            throw AnyHeartNativePinkhaSourceError.invalidManifest("version, native kind or incomplete provisioning")
        }
        let byID = Dictionary(uniqueKeysWithValues: snapshots.map { (Data($0.sourceObjectID.utf8), $0) })
        func identifier(_ value: AnyJSON?, _ field: String) throws -> String {
            guard let id = value?.string, Self.validID(id) else {
                throw AnyHeartNativePinkhaSourceError.invalidManifest(field)
            }
            return id
        }
        func property(_ idField: String, _ keyField: String,
                      format: AnyHeartNativeDefinitionCatalog.Format) throws -> Property {
            let id = try identifier(rawManifest[idField], idField)
            let key = try identifier(rawManifest[keyField], keyField)
            guard let byID = catalog.relation(objectID: id), let byKey = catalog.relation(key: key),
                  Self.exact(byID.objectID, byKey.objectID), Self.exact(byID.relationKey, key),
                  byID.format == format else {
                throw AnyHeartNativePinkhaSourceError.missingDefinition(idField)
            }
            return .init(objectID: id, key: key, format: format,
                         definitionSnapshotSHA256: byID.snapshot.snapshotSHA256)
        }
        let parent = try property("parentPropertyId", "parentPropertyKey", format: .object)
        let order = try property("orderPropertyId", "orderPropertyKey", format: .number)
        let associations = try property("documentAssociationsPropertyId", "documentAssociationsPropertyKey", format: .longText)
        guard Set([parent.objectID, order.objectID, associations.objectID]).count == 3,
              Set([parent.key, order.key, associations.key]).count == 3 else {
            throw AnyHeartNativePinkhaSourceError.invalidManifest("aliased property roles")
        }
        let folder = try identifier(rawManifest["folderTypeId"], "folderTypeId")
        let book = try identifier(rawManifest["bookFolderTypeId"], "bookFolderTypeId")
        func roles(_ field: String) throws -> [String: String] {
            guard let values = rawManifest[field]?.object, values.count <= 128 else {
                throw AnyHeartNativePinkhaSourceError.invalidManifest(field)
            }
            return try values.reduce(into: [:]) { result, pair in
                guard Self.validID(pair.key), pair.key.utf8.count <= 128 else {
                    throw AnyHeartNativePinkhaSourceError.invalidManifest(field)
                }
                result[pair.key] = try identifier(pair.value, field + "." + pair.key)
            }
        }
        let types = try roles("registeredDocumentTypes"), templates = try roles("defaultTemplateIds")
        let required = [PinkhaSchemaRoles.chiddushKey, PinkhaSchemaRoles.articleKey, PinkhaSchemaRoles.researchKey]
        guard required.allSatisfy({ types[$0] != nil && templates[$0] != nil }),
              Set([folder, book] + Array(types.values)).count == 2 + types.count else {
            throw AnyHeartNativePinkhaSourceError.invalidManifest("missing or ambiguous type roles")
        }
        var typeRoles: [Data: Role] = [:]
        for (id, role) in [(folder, Role.folder), (book, .bookFolder)] +
                types.map({ ($0.value, Role.writingDocument($0.key)) }) {
            guard catalog.type(objectID: id) != nil else {
                throw AnyHeartNativePinkhaSourceError.missingDefinition("type role")
            }
            typeRoles[Data(id.utf8)] = role
        }
        for (role, id) in templates {
            guard types[role] != nil, byID[Data(id.utf8)] != nil else {
                throw AnyHeartNativePinkhaSourceError.missingDefinition("default template")
            }
        }
        let known: Set<String> = ["schemaVersion", "spaceId", "manifestObjectId", "provisioningState",
            "parentPropertyId", "parentPropertyKey", "orderPropertyId", "orderPropertyKey",
            "documentAssociationsPropertyId", "documentAssociationsPropertyKey",
            "folderTypeId", "bookFolderTypeId", "registeredDocumentTypes", "defaultTemplateIds",
            "createdAt", "updatedAt"]
        var issues = Set(rawManifest.object!.keys).subtracting(known).sorted().map {
            Issue(objectID: manifestSnapshot.sourceObjectID, field: $0, reason: "unknown-manifest-field-retained")
        }
        var entries: [HierarchyEntry] = [], documents: [CanonicalDocument] = []
        for snapshot in snapshots.sorted(by: { Data($0.sourceObjectID.utf8).lexicographicallyPrecedes(Data($1.sourceObjectID.utf8)) }) {
            if snapshot.objectTypes.count == 1,
               let type = catalog.type(url: snapshot.objectTypes[0]),
               let role = typeRoles[Data(type.objectID.utf8)] {
                let originalParent = snapshot.details[parent.key]
                let parentID = try Self.parentID(originalParent, objectID: snapshot.sourceObjectID, field: parent.key)
                let originalOrder = snapshot.details[order.key]
                let rank = try Self.rank(originalOrder, objectID: snapshot.sourceObjectID, field: order.key)
                entries.append(.init(snapshot: snapshot, typeID: type.objectID, role: role,
                    originalParent: originalParent, parentObjectID: parentID, originalOrder: originalOrder, order: rank))
                if let parentID, byID[Data(parentID.utf8)] == nil {
                    issues.append(.init(objectID: snapshot.sourceObjectID, field: parent.key, reason: "parent-outside-captured-source"))
                }
                if role == .bookFolder {
                    issues.append(.init(objectID: snapshot.sourceObjectID, field: "type", reason: "book-folder-needs-distinct-destination-behavior"))
                }
            }
            guard let value = snapshot.details[associations.key] else { continue }
            guard let text = value.string, text.utf8.count <= 16 * 1024 * 1024 else {
                throw AnyHeartNativePinkhaSourceError.malformedValue(snapshot.sourceObjectID, associations.key)
            }
            let bytes = Data(text.utf8)
            let records: [TorahStoredAssociationRecord]
            if text.isEmpty { records = [] } // Original Heart reader's explicit empty-string behavior.
            else {
                let location = TorahAssociationLocation(spaceId: catalog.sourceSpaceID,
                    target: .object(objectId: snapshot.sourceObjectID))
                let decoded = try TorahAssociationPayloadCodec().decodeCanonicalDocument(bytes, legacyLocation: location)
                try AnyTorahSourceJSONGuard.validateCanonicalPayload(bytes, decoded: decoded)
                guard decoded.records.allSatisfy({
                    Self.exact($0.spaceId, catalog.sourceSpaceID) && Self.exact($0.objectId, snapshot.sourceObjectID)
                }) else { throw AnyHeartNativePinkhaSourceError.malformedValue(snapshot.sourceObjectID, associations.key) }
                var stable = Set<String>(), semantic = Set<TorahAssociationIdentity>()
                for record in decoded.records {
                    guard !record.item.id.isEmpty, !record.item.providerID.isEmpty,
                          !record.item.canonicalKey.isEmpty || !record.item.externalID.isEmpty,
                          record.blockId == nil || snapshot.blocks.contains(where: { Self.exact($0.id, record.blockId!) }),
                          stable.insert("\((record.blockId ?? "").utf8.count):\(record.blockId ?? "")\(record.item.id.utf8.count):\(record.item.id)").inserted,
                          semantic.insert(.init(item: record.item, location: record.location)).inserted else {
                        throw AnyHeartNativePinkhaSourceError.malformedValue(snapshot.sourceObjectID, associations.key)
                    }
                    _ = try TorahSemanticAnchorAssociation.decoding(record.item, location: record.location)
                }
                records = decoded.records
            }
            documents.append(.init(snapshot: snapshot, propertyKey: associations.key, sourceBytes: bytes, records: records))
        }
        let entriesByID = Dictionary(uniqueKeysWithValues: entries.map { (Data($0.snapshot.sourceObjectID.utf8), $0) })
        for entry in entries {
            var visited = Set<Data>(), cursor: HierarchyEntry? = entry
            while let current = cursor {
                guard visited.insert(Data(current.snapshot.sourceObjectID.utf8)).inserted else {
                    issues.append(.init(objectID: entry.snapshot.sourceObjectID, field: parent.key, reason: "hierarchy-cycle-retained"))
                    break
                }
                cursor = current.parentObjectID.flatMap { entriesByID[Data($0.utf8)] }
            }
            if let parentID = entry.parentObjectID {
                if let target = entriesByID[Data(parentID.utf8)] {
                    if target.role != .folder {
                        issues.append(.init(objectID: entry.snapshot.sourceObjectID, field: parent.key, reason: "parent-is-not-ordinary-folder"))
                    }
                } else {
                    issues.append(.init(objectID: entry.snapshot.sourceObjectID, field: parent.key, reason: "parent-has-no-Pinkha-hierarchy-role"))
                }
            }
        }
        self.sourceAccountID = catalog.sourceAccountID; self.sourceSpaceID = catalog.sourceSpaceID
        self.captureManifestSHA256 = catalog.captureManifestSHA256; self.sourceWitnessSHA256 = catalog.sourceWitnessSHA256
        self.manifestObjectID = manifestSnapshot.sourceObjectID; self.manifestSnapshotSHA256 = manifestSnapshot.snapshotSHA256
        self.manifestBytes = manifestBytes; self.rawManifest = rawManifest
        self.parentProperty = parent; self.orderProperty = order; self.associationsProperty = associations
        self.folderTypeID = folder; self.bookFolderTypeID = book
        self.documentTypes = types; self.defaultTemplates = templates
        self.hierarchy = entries; self.canonicalDocuments = documents; self.issues = issues
        self.capturedObjectIDs = Set(byID.keys)
        let material: AnyJSON = .object(["contract": .string("pinkha-captured-schema-source-v1"),
            "catalog": .string(catalog.contentSHA256), "manifest": .string(AnyContentDigest.sha256(manifestBytes)),
            "snapshots": .array(snapshots.sorted { Data($0.sourceObjectID.utf8).lexicographicallyPrecedes(Data($1.sourceObjectID.utf8)) }.map {
                .object(["id": .string($0.sourceObjectID), "protobuf": .string($0.snapshotSHA256), "view": .string($0.viewSHA256)])
            })])
        contentSHA256 = AnyContentDigest.sha256(try encoder.encode(material))
    }

    /// Component plan from the exact captured native property. Caller must
    /// still establish current source authority and whole-source coverage.
    public func canonicalPlan(sourceObjectID: String, workspace: AnyTorahWorkspace,
                              objectIDMap: [String: String], blockIDMap: [String: String],
                              migrationKey: String) throws -> AnyTorahMigrationPlan {
        guard let document = canonicalDocuments.first(where: { Self.exact($0.snapshot.sourceObjectID, sourceObjectID) }) else {
            throw AnyHeartNativePinkhaSourceError.unknownObject(sourceObjectID)
        }
        guard !document.sourceBytes.isEmpty else { throw AnyHeartNativePinkhaSourceError.emptyCanonicalProperty }
        guard objectIDMap.allSatisfy({ capturedObjectIDs.contains(Data($0.key.utf8)) && Self.validID($0.value) }),
              Set(objectIDMap.values.map { Data($0.utf8) }).count == objectIDMap.count else {
            throw AnyHeartNativePinkhaSourceError.sourceBinding
        }
        guard let target = objectIDMap.first(where: { Self.exact($0.key, sourceObjectID) })?.value else {
            throw AnyHeartNativePinkhaSourceError.missingMapping(sourceObjectID)
        }
        return try .init(sourceBytes: document.sourceBytes, sourceSpaceID: sourceSpaceID, sourceObjectID: sourceObjectID,
            workspace: workspace, targetObjectID: target, blockIDMap: blockIDMap, objectIDMap: objectIDMap, migrationKey: migrationKey)
    }

    private static func parentID(_ value: AnyJSON?, objectID: String, field: String) throws -> String? {
        guard let value else { return nil }
        if let text = value.string {
            guard text.isEmpty || validID(text) else { throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field) }
            return text.isEmpty ? nil : text
        }
        if let rows = value.array {
            guard rows.count <= 1 else { throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field) }
            guard let first = rows.first else { return nil }
            guard let text = first.string, validID(text) else { throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field) }
            return text
        }
        throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field)
    }

    private static func rank(_ value: AnyJSON?, objectID: String, field: String) throws -> Double? {
        guard let value else { return nil }
        switch value {
        case .integer(let number):
            guard let result = Double(exactly: number) else { throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field) }
            return result
        case .number(let number):
            guard number.isFinite else { throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field) }
            return number
        default: throw AnyHeartNativePinkhaSourceError.malformedValue(objectID, field)
        }
    }
    private static func validID(_ value: String) -> Bool {
        !value.isEmpty && value.utf8.count <= 4096 &&
        value.unicodeScalars.allSatisfy { !CharacterSet.controlCharacters.contains($0) }
    }
    private static func exact(_ lhs: String, _ rhs: String) -> Bool { Data(lhs.utf8) == Data(rhs.utf8) }
}

import Foundation
import PinkhaAnyEngine

public enum AnyHeartNativePreservationError: Error, Equatable, Sendable {
    case binding, member, limit, malformedArchive
}

/// Bounded, reversible native-source file. Capture members and separately
/// recovered registry evidence retain distinct namespaces and exact bytes.
/// Decoding performs no filesystem write, restore, session acquisition or import.
public struct AnyHeartNativePreservationArchive: Sendable {
    public static let contract = "pinkha-heart-preserved-source-file-v1"
    public static let maximumBytes = 64 * 1024 * 1024
    public static let mimeType = "application/vnd.pinkha.heart-source"
    private static let magic = Data("PINKHA-HEART-SOURCE-1\u{0}".utf8)
    public static let capturedContract = "pinkha-heart-preserved-source-file-v2"
    private static let capturedMagic = Data("PINKHA-HEART-SOURCE-2\u{0}".utf8)

    public struct Binding: Equatable, Sendable {
        public let accountID: String
        public let spaceID: String
        public let captureManifestSHA256: String
        public let sourceWitnessSHA256: String
        public let definitionEvidenceKind: AnyHeartNativeDefinitionEvidence.Kind
        public let recoveredManifestSHA256: String?
        public init(bundle: AnyHeartNativeSpaceBundle, recovered: AnyHeartNativeRecoveredDefinitions) throws {
            _ = try AnyHeartNativeDefinitionCatalog(bundle: bundle, recoveredDefinitions: recovered)
            accountID = bundle.sourceAccountID; spaceID = bundle.sourceSpaceID
            captureManifestSHA256 = bundle.manifestSHA256; sourceWitnessSHA256 = bundle.sourceWitnessSHA256
            recoveredManifestSHA256 = recovered.manifestSHA256
            definitionEvidenceKind = .recoveredOriginal
        }

        public init(capturedBundle bundle: AnyHeartNativeSpaceBundle) throws {
            _ = try AnyHeartNativeDefinitionEvidence.capturedComplete.catalog(bundle: bundle)
            accountID = bundle.sourceAccountID; spaceID = bundle.sourceSpaceID
            captureManifestSHA256 = bundle.manifestSHA256; sourceWitnessSHA256 = bundle.sourceWitnessSHA256
            recoveredManifestSHA256 = nil; definitionEvidenceKind = .capturedComplete
        }

        /// An expected persisted identity, not a source session or admission.
        /// restore still checks the complete original bundle and recovered
        /// descriptors against all five values before returning any member.
        public init(expectedAccountID: String, expectedSpaceID: String,
                    captureManifestSHA256: String, sourceWitnessSHA256: String,
                    recoveredManifestSHA256: String) throws {
            func identifier(_ value: String) -> Bool {
                !value.isEmpty && value.utf8.count <= 4096 &&
                    value.unicodeScalars.allSatisfy { !CharacterSet.controlCharacters.contains($0) }
            }
            func digest(_ value: String) -> Bool {
                value.utf8.count == 64 &&
                    value.utf8.allSatisfy { (48...57).contains($0) || (97...102).contains($0) }
            }
            guard identifier(expectedAccountID), identifier(expectedSpaceID),
                  [captureManifestSHA256, sourceWitnessSHA256, recoveredManifestSHA256].allSatisfy(digest) else {
                throw AnyHeartNativePreservationError.binding
            }
            self.accountID = expectedAccountID; self.spaceID = expectedSpaceID
            self.captureManifestSHA256 = captureManifestSHA256
            self.sourceWitnessSHA256 = sourceWitnessSHA256
            self.recoveredManifestSHA256 = recoveredManifestSHA256
            self.definitionEvidenceKind = .recoveredOriginal
        }

        public init(expectedAccountID: String, expectedSpaceID: String,
                    capturedManifestSHA256: String, sourceWitnessSHA256: String) throws {
            func identifier(_ value: String) -> Bool {
                !value.isEmpty && value.utf8.count <= 4096 &&
                    value.unicodeScalars.allSatisfy { !CharacterSet.controlCharacters.contains($0) }
            }
            func digest(_ value: String) -> Bool {
                value.utf8.count == 64 &&
                    value.utf8.allSatisfy { (48...57).contains($0) || (97...102).contains($0) }
            }
            guard identifier(expectedAccountID), identifier(expectedSpaceID),
                  [capturedManifestSHA256, sourceWitnessSHA256].allSatisfy(digest) else {
                throw AnyHeartNativePreservationError.binding
            }
            accountID = expectedAccountID; spaceID = expectedSpaceID
            captureManifestSHA256 = capturedManifestSHA256
            self.sourceWitnessSHA256 = sourceWitnessSHA256
            recoveredManifestSHA256 = nil; definitionEvidenceKind = .capturedComplete
        }

        public static func == (lhs: Self, rhs: Self) -> Bool {
            Data(lhs.accountID.utf8) == Data(rhs.accountID.utf8) &&
                Data(lhs.spaceID.utf8) == Data(rhs.spaceID.utf8) &&
                lhs.captureManifestSHA256 == rhs.captureManifestSHA256 &&
                lhs.sourceWitnessSHA256 == rhs.sourceWitnessSHA256 &&
                lhs.definitionEvidenceKind == rhs.definitionEvidenceKind &&
                lhs.recoveredManifestSHA256 == rhs.recoveredManifestSHA256
        }
    }
    public struct Restored: Sendable {
        public let bundle: AnyHeartNativeSpaceBundle
        public let recoveredDefinitions: AnyHeartNativeRecoveredDefinitions?
        public var definitionEvidence: AnyHeartNativeDefinitionEvidence {
            if let recoveredDefinitions { return .recoveredOriginal(recoveredDefinitions) }
            return .capturedComplete
        }
        public let originalMemberCount: Int
        public let recoveredMemberCount: Int
        fileprivate let members: [String: Data]
        public var grantsSourceSession: Bool { false }

        /// Exact verified bytes remain available to an explicit export caller.
        /// This accessor does not write a path or restore a native account.
        public func capturedMemberData(_ member: AnyHeartNativeSpaceBundle.Member) throws -> Data {
            try memberData(member, declared: bundle.verifiedMembers, prefix: "capture/")
        }
        public func recoveredMemberData(_ member: AnyHeartNativeSpaceBundle.Member) throws -> Data {
            guard let recoveredDefinitions else { throw AnyHeartNativePreservationError.member }
            return try memberData(member, declared: recoveredDefinitions.verifiedMembers, prefix: "recovery/descriptors/")
        }
        private func memberData(_ member: AnyHeartNativeSpaceBundle.Member,
                                declared: [AnyHeartNativeSpaceBundle.Member], prefix: String) throws -> Data {
            guard declared.contains(where: {
                Data($0.path.utf8) == Data(member.path.utf8) &&
                    $0.sha256 == member.sha256 && $0.byteCount == member.byteCount
            }), let bytes = members[prefix + member.path],
                  bytes.count == member.byteCount, AnyContentDigest.sha256(bytes) == member.sha256 else {
                throw AnyHeartNativePreservationError.member
            }
            return bytes
        }
        public var restoresAnAccount: Bool { false }
    }

    public let binding: Binding
    public let bytes: Data
    public let sha256: String
    public let originalMemberCount: Int
    public let recoveredMemberCount: Int
    public var permitsDestinationWrites: Bool { false }

    public init(bundle: AnyHeartNativeSpaceBundle, recovered: AnyHeartNativeRecoveredDefinitions,
                memberData: (AnyHeartNativeSpaceBundle.Member) throws -> Data,
                recoveredMemberData: (AnyHeartNativeSpaceBundle.Member) throws -> Data) throws {
        let binding = try Binding(bundle: bundle, recovered: recovered)
        var rows: [(String, Data)] = [], names = Set<Data>(), total = 0
        func append(_ path: String, _ value: Data, expected: AnyHeartNativeSpaceBundle.Member? = nil) throws {
            guard Self.path(path), names.insert(Data(path.utf8)).inserted else {
                throw AnyHeartNativePreservationError.member
            }
            if let expected {
                guard value.count == expected.byteCount,
                      AnyContentDigest.sha256(value) == expected.sha256 else {
                    throw AnyHeartNativePreservationError.member
                }
            }
            guard value.count <= Self.maximumBytes - total else { throw AnyHeartNativePreservationError.limit }
            total += value.count; rows.append((path, value))
        }
        try append("capture/manifest.json", bundle.manifestBytes)
        for member in bundle.verifiedMembers {
            guard member.byteCount <= Self.maximumBytes - total else { throw AnyHeartNativePreservationError.limit }
            try append("capture/" + member.path, memberData(member), expected: member)
        }
        try append("recovery/binding.json", recovered.manifestBytes)
        try append("recovery/original-producer.json", recovered.originalProducerBytes)
        try append("recovery/receipt.json", recovered.recoveryReceiptBytes)
        try append("recovery/export.json", recovered.exportManifestBytes)
        for member in recovered.verifiedMembers {
            guard member.byteCount <= Self.maximumBytes - total else { throw AnyHeartNativePreservationError.limit }
            try append("recovery/descriptors/" + member.path, recoveredMemberData(member), expected: member)
        }
        rows.sort { Data($0.0.utf8).lexicographicallyPrecedes(Data($1.0.utf8)) }
        let header: AnyJSON = .object([
            "contract": .string(Self.contract), "accountID": .string(binding.accountID),
            "spaceID": .string(binding.spaceID), "captureManifestSHA256": .string(binding.captureManifestSHA256),
            "sourceWitnessSHA256": .string(binding.sourceWitnessSHA256),
            "recoveredManifestSHA256": .string(recovered.manifestSHA256),
            "members": .array(rows.map { .object(["path": .string($0.0),
                "bytes": .integer(Int64($0.1.count)), "sha256": .string(AnyContentDigest.sha256($0.1))]) }),
        ])
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        let encoded = try encoder.encode(header)
        guard encoded.count <= 4 * 1024 * 1024,
              total <= Self.maximumBytes - encoded.count - Self.magic.count - 8 else {
            throw AnyHeartNativePreservationError.limit
        }
        var data = Self.magic
        for shift in stride(from: 56, through: 0, by: -8) {
            data.append(UInt8((UInt64(encoded.count) >> UInt64(shift)) & 255))
        }
        data.append(encoded)
        for (_, value) in rows { data.append(value) }
        let restored = try Self.restore(data, expected: binding)
        guard restored.bundle.manifestBytes == bundle.manifestBytes,
              restored.recoveredDefinitions?.manifestBytes == recovered.manifestBytes else {
            throw AnyHeartNativePreservationError.binding
        }
        self.binding = binding; bytes = data; sha256 = AnyContentDigest.sha256(data)
        originalMemberCount = bundle.verifiedMembers.count + 1
        recoveredMemberCount = recovered.verifiedMembers.count + 4
    }



    /// Direct native capture, with zero missing compiled descriptors. The v2
    /// envelope contains only capture members and explicitly no recovery rows.
    public init(capturedBundle bundle: AnyHeartNativeSpaceBundle,
                memberData: (AnyHeartNativeSpaceBundle.Member) throws -> Data) throws {
        let binding = try Binding(capturedBundle: bundle)
        var rows: [(String, Data)] = [], names = Set<Data>(), total = 0
        func append(_ path: String, _ value: Data, expected: AnyHeartNativeSpaceBundle.Member? = nil) throws {
            try Task.checkCancellation()
            guard Self.path(path), names.insert(Data(path.utf8)).inserted else {
                throw AnyHeartNativePreservationError.member
            }
            if let expected {
                guard value.count == expected.byteCount,
                      AnyContentDigest.sha256(value) == expected.sha256 else {
                    throw AnyHeartNativePreservationError.member
                }
            }
            guard value.count <= Self.maximumBytes - total else { throw AnyHeartNativePreservationError.limit }
            total += value.count; rows.append((path, value))
        }
        try append("capture/manifest.json", bundle.manifestBytes)
        for member in bundle.verifiedMembers {
            guard member.byteCount <= Self.maximumBytes - total else { throw AnyHeartNativePreservationError.limit }
            try append("capture/" + member.path, memberData(member), expected: member)
        }
        rows.sort { Data($0.0.utf8).lexicographicallyPrecedes(Data($1.0.utf8)) }
        let header: AnyJSON = .object([
            "contract": .string(Self.capturedContract), "accountID": .string(binding.accountID),
            "spaceID": .string(binding.spaceID), "captureManifestSHA256": .string(binding.captureManifestSHA256),
            "sourceWitnessSHA256": .string(binding.sourceWitnessSHA256),
            "definitionEvidence": .string(AnyHeartNativeDefinitionEvidence.Kind.capturedComplete.rawValue),
            "members": .array(rows.map { .object(["path": .string($0.0),
                "bytes": .integer(Int64($0.1.count)), "sha256": .string(AnyContentDigest.sha256($0.1))]) }),
        ])
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        let encoded = try encoder.encode(header)
        guard encoded.count <= 4 * 1024 * 1024,
              total <= Self.maximumBytes - encoded.count - Self.capturedMagic.count - 8 else {
            throw AnyHeartNativePreservationError.limit
        }
        var data = Self.capturedMagic
        for shift in stride(from: 56, through: 0, by: -8) {
            data.append(UInt8((UInt64(encoded.count) >> UInt64(shift)) & 255))
        }
        data.append(encoded)
        for (_, value) in rows { data.append(value) }
        let restored = try Self.restore(data, expected: binding)
        guard restored.bundle.manifestBytes == bundle.manifestBytes,
              restored.recoveredDefinitions == nil, restored.recoveredMemberCount == 0 else {
            throw AnyHeartNativePreservationError.binding
        }
        try Task.checkCancellation()
        self.binding = binding; bytes = data; sha256 = AnyContentDigest.sha256(data)
        originalMemberCount = bundle.verifiedMembers.count + 1; recoveredMemberCount = 0
    }

    /// Reopens exactly one already-preserved source file. This validates the
    /// same complete member set as restore and never writes or restores an
    /// account. It preserves the original bytes instead of re-exporting them.
    public init(restoring data: Data, expected: Binding) throws {
        let restored = try Self.restore(data, expected: expected)
        self.binding = expected
        self.bytes = data
        self.sha256 = AnyContentDigest.sha256(data)
        self.originalMemberCount = restored.originalMemberCount
        self.recoveredMemberCount = restored.recoveredMemberCount
    }

    public static func restore(_ data: Data, expected: Binding) throws -> Restored {
        if expected.definitionEvidenceKind == .capturedComplete {
            return try restoreCaptured(data, expected: expected)
        }
        guard expected.definitionEvidenceKind == .recoveredOriginal,
              let recoverySHA256 = expected.recoveredManifestSHA256 else {
            throw AnyHeartNativePreservationError.binding
        }
        guard data.count <= maximumBytes, data.count >= magic.count + 8,
              data.prefix(magic.count) == magic else { throw AnyHeartNativePreservationError.malformedArchive }
        var cursor = magic.count
        var headerLength: UInt64 = 0
        for byte in data[cursor..<(cursor + 8)] { headerLength = (headerLength << 8) | UInt64(byte) }
        cursor += 8
        guard headerLength <= 4 * 1024 * 1024, headerLength <= UInt64(data.count - cursor) else {
            throw AnyHeartNativePreservationError.limit
        }
        let headerBytes = data.subdata(in: cursor..<(cursor + Int(headerLength))); cursor += Int(headerLength)
        let header = try JSONDecoder().decode(AnyJSON.self, from: headerBytes)
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: headerBytes, encoded: encoder.encode(header))
        guard let object = header.object,
              Set(object.keys) == ["contract", "accountID", "spaceID", "captureManifestSHA256",
                                   "sourceWitnessSHA256", "recoveredManifestSHA256", "members"],
              header["contract"] == .string(contract),
              same(header["accountID"]?.string, expected.accountID),
              same(header["spaceID"]?.string, expected.spaceID),
              header["captureManifestSHA256"] == .string(expected.captureManifestSHA256),
              header["sourceWitnessSHA256"] == .string(expected.sourceWitnessSHA256),
              header["recoveredManifestSHA256"] == .string(recoverySHA256),
              let declared = header["members"]?.array, !declared.isEmpty, declared.count <= 100_000 else {
            throw AnyHeartNativePreservationError.binding
        }
        var members: [String: Data] = [:], rawNames = Set<Data>(), previous: Data?
        for value in declared {
            guard let row = value.object, Set(row.keys) == ["path", "bytes", "sha256"],
                  let name = value["path"]?.string, path(name),
                  let count = value["bytes"]?.integer, count >= 0, count <= Int64(data.count - cursor),
                  let hash = value["sha256"]?.string, hash.count == 64,
                  rawNames.insert(Data(name.utf8)).inserted,
                  members[name] == nil, previous.map({ $0.lexicographicallyPrecedes(Data(name.utf8)) }) ?? true else {
                throw AnyHeartNativePreservationError.member
            }
            previous = Data(name.utf8)
            let body = data.subdata(in: cursor..<(cursor + Int(count))); cursor += Int(count)
            guard AnyContentDigest.sha256(body) == hash else { throw AnyHeartNativePreservationError.member }
            members[name] = body
        }
        guard cursor == data.count else { throw AnyHeartNativePreservationError.malformedArchive }
        func require(_ path: String) throws -> Data {
            guard let value = members[path] else { throw AnyHeartNativePreservationError.member }
            return value
        }
        let manifest = try require("capture/manifest.json")
        guard AnyContentDigest.sha256(manifest) == expected.captureManifestSHA256 else {
            throw AnyHeartNativePreservationError.binding
        }
        let bundle = try AnyHeartNativeSpaceBundle(manifest: manifest,
            sourceAccountID: expected.accountID, sourceSpaceID: expected.spaceID) {
                try require("capture/" + $0.path)
            }
        guard bundle.sourceWitnessSHA256 == expected.sourceWitnessSHA256 else {
            throw AnyHeartNativePreservationError.binding
        }
        let recovered = try AnyHeartNativeRecoveredDefinitions(bundle: bundle,
            manifest: require("recovery/binding.json"),
            expectedManifestSHA256: recoverySHA256,
            originalProducer: require("recovery/original-producer.json"),
            recoveryReceipt: require("recovery/receipt.json"),
            registryExport: require("recovery/export.json")) {
                try require("recovery/descriptors/" + $0.path)
            }
        let expectedPaths = Set(["capture/manifest.json", "recovery/binding.json",
            "recovery/original-producer.json", "recovery/receipt.json", "recovery/export.json"] +
            bundle.verifiedMembers.map { "capture/" + $0.path } +
            recovered.verifiedMembers.map { "recovery/descriptors/" + $0.path })
        let expectedRawPaths = Set(expectedPaths.map { Data($0.utf8) })
        guard Set(members.keys.map { Data($0.utf8) }) == expectedRawPaths,
              members.count == expectedRawPaths.count else {
            throw AnyHeartNativePreservationError.member
        }
        return .init(bundle: bundle, recoveredDefinitions: recovered,
            originalMemberCount: bundle.verifiedMembers.count + 1,
            recoveredMemberCount: recovered.verifiedMembers.count + 4, members: members)
    }


    private static func restoreCaptured(_ data: Data, expected: Binding) throws -> Restored {
        try Task.checkCancellation()
        guard expected.definitionEvidenceKind == .capturedComplete,
              expected.recoveredManifestSHA256 == nil,
              data.count <= maximumBytes, data.count >= capturedMagic.count + 8,
              data.prefix(capturedMagic.count) == capturedMagic else {
            throw AnyHeartNativePreservationError.malformedArchive
        }
        var cursor = capturedMagic.count
        var headerLength: UInt64 = 0
        for byte in data[cursor..<(cursor + 8)] { headerLength = (headerLength << 8) | UInt64(byte) }
        cursor += 8
        guard headerLength <= 4 * 1024 * 1024, headerLength <= UInt64(data.count - cursor) else {
            throw AnyHeartNativePreservationError.limit
        }
        let headerBytes = data.subdata(in: cursor..<(cursor + Int(headerLength))); cursor += Int(headerLength)
        let header = try JSONDecoder().decode(AnyJSON.self, from: headerBytes)
        let encoder = JSONEncoder(); encoder.outputFormatting = [.sortedKeys]
        try AnyTorahSourceJSONGuard.validateRoundTrip(original: headerBytes, encoded: encoder.encode(header))
        guard let object = header.object,
              Set(object.keys) == ["contract", "accountID", "spaceID", "captureManifestSHA256",
                                   "sourceWitnessSHA256", "definitionEvidence", "members"],
              header["contract"] == .string(capturedContract),
              header["definitionEvidence"] == .string(AnyHeartNativeDefinitionEvidence.Kind.capturedComplete.rawValue),
              same(header["accountID"]?.string, expected.accountID),
              same(header["spaceID"]?.string, expected.spaceID),
              header["captureManifestSHA256"] == .string(expected.captureManifestSHA256),
              header["sourceWitnessSHA256"] == .string(expected.sourceWitnessSHA256),
              let declared = header["members"]?.array, !declared.isEmpty, declared.count <= 100_000 else {
            throw AnyHeartNativePreservationError.binding
        }
        var members: [String: Data] = [:], rawNames = Set<Data>(), previous: Data?
        for value in declared {
            try Task.checkCancellation()
            guard let row = value.object, Set(row.keys) == ["path", "bytes", "sha256"],
                  let name = value["path"]?.string, path(name), name.hasPrefix("capture/"),
                  let count = value["bytes"]?.integer, count >= 0, count <= Int64(data.count - cursor),
                  let hash = value["sha256"]?.string, hash.count == 64,
                  rawNames.insert(Data(name.utf8)).inserted,
                  members[name] == nil, previous.map({ $0.lexicographicallyPrecedes(Data(name.utf8)) }) ?? true else {
                throw AnyHeartNativePreservationError.member
            }
            previous = Data(name.utf8)
            let body = data.subdata(in: cursor..<(cursor + Int(count))); cursor += Int(count)
            guard AnyContentDigest.sha256(body) == hash else { throw AnyHeartNativePreservationError.member }
            members[name] = body
        }
        guard cursor == data.count, let manifest = members["capture/manifest.json"],
              AnyContentDigest.sha256(manifest) == expected.captureManifestSHA256 else {
            throw AnyHeartNativePreservationError.malformedArchive
        }
        let bundle = try AnyHeartNativeSpaceBundle(manifest: manifest,
            sourceAccountID: expected.accountID, sourceSpaceID: expected.spaceID) { member in
                guard let value = members["capture/" + member.path] else { throw AnyHeartNativePreservationError.member }
                return value
            }
        guard bundle.sourceWitnessSHA256 == expected.sourceWitnessSHA256,
              try Binding(capturedBundle: bundle) == expected else {
            throw AnyHeartNativePreservationError.binding
        }
        let expectedPaths = Set((["capture/manifest.json"] +
            bundle.verifiedMembers.map { "capture/" + $0.path }).map { Data($0.utf8) })
        guard Set(members.keys.map { Data($0.utf8) }) == expectedPaths,
              members.count == expectedPaths.count else { throw AnyHeartNativePreservationError.member }
        try Task.checkCancellation()
        return .init(bundle: bundle, recoveredDefinitions: nil,
            originalMemberCount: bundle.verifiedMembers.count + 1, recoveredMemberCount: 0, members: members)
    }

    private static func same(_ lhs: String?, _ rhs: String) -> Bool {
        lhs.map { Data($0.utf8) == Data(rhs.utf8) } ?? false
    }
    private static func path(_ path: String) -> Bool {
        let parts = path.split(separator: "/", omittingEmptySubsequences: false)
        return !path.isEmpty && path.utf8.count <= 4096 && !path.utf8.contains(0) &&
            !path.contains("\\") && parts.allSatisfy { !$0.isEmpty && $0 != "." && $0 != ".." }
    }
}

